/// In-progress joint (Joint tool, #894): the picked parts, the mate that places them
/// (#1021 — a face on a face, then the line-up rows), the kind, and the joint being
/// re-edited.
#[derive(Clone, Debug, PartialEq, Default)]
pub struct CreatingJoint {
    pub members: Vec<crate::model::JointRef>,
    /// Index into `members` of the held side — the first picked, unless the pane swaps it.
    pub base: usize,
    pub kind: crate::model::JointKind,
    /// Where the parts start out (#1021/#1079): the **same** in-progress move the Move tool
    /// drives. Sharing the state rather than a component is what keeps the two from quietly
    /// drifting into two behaviours (#1068).
    pub placement: CreatingMove,
    pub position: String,
    pub position2: String,
    pub position3: String,
    /// How the joint works (#1079): the frame its freedoms act in, seeded by the mate and
    /// editable either way.
    pub frame: crate::model::JointFrame,
    /// Travel limits (#896), carried whole — expressions and stop targets.
    pub limits: crate::model::JointLimits,
    /// `Some(joint)` while re-editing a committed joint.
    pub editing: Option<crate::model::JointKey>,
}

/// The frame a joint is stored with (#1079): whatever was set, with anything left blank
/// filled in from the mate — a mate that names a fixed face names the natural axis, and its
/// first line-up row the natural second one.
///
/// Seeding rather than deriving is the whole point: a mate that names no plane simply leaves
/// the inputs empty for the user, and one that does can still be overruled. It runs where the
/// joint is built rather than at commit, so a scripted joint is seeded exactly like a drawn
/// one.
fn seeded_joint_frame(
    frame: &crate::model::JointFrame,
    placement: &crate::model::MoveOperation,
) -> crate::model::JointFrame {
    let mut frame = frame.clone();
    // A Face Snap placement names a plane: its fixed face is the natural axis, and the point
    // it lands on the natural origin. Every other mode names none, and leaves these empty.
    if frame.primary.is_none() {
        frame.primary = match placement.end_point_a {
            Some(crate::model::MovePointRef::OnFace { body, centroid, normal, .. }) => {
                Some(crate::model::MateRef::Face { body, centroid, normal })
            }
            _ => None,
        };
    }
    frame
}

impl CreatingMove {
    /// This in-progress move as a stored [`crate::model::MoveOperation`] (#1079) — how a
    /// joint keeps its placement, and the shape `extrude::move_op_transform` resolves.
    pub fn as_op(&self) -> crate::model::MoveOperation {
        crate::model::MoveOperation {
            keep_inputs: false,
            targets: self.targets.clone(),
            translate_mode: self.translate_mode,
            start_point_a: self.start_point_a,
            end_point_a: self.end_point_a,
            start_point_b: self.start_point_b,
            end_point_b: self.end_point_b,
            start_point_c: self.start_point_c,
            end_point_c: self.end_point_c,
            plane_targets: self.plane_targets.clone(),
            image_targets: self.image_targets.clone(),
            instance_targets: self.instance_targets.clone(),
            tx: self.tx.clone(),
            ty: self.ty.clone(),
            tz: self.tz.clone(),
            rx: self.rx.clone(),
            ry: self.ry.clone(),
            rz: self.rz.clone(),
            roll_angle: self.roll_angle.clone(),
            face_flip: self.face_flip,
            face_spin: self.face_spin.clone(),
            face_offset: self.face_offset.clone(),
            outputs: Vec::new(),
            name: None,
        }
    }

    /// Image-only planar Move (#1601): the host-plane normal when every target is an image
    /// on the same (or parallel) plane.
    pub fn planar_normal(&self, doc: &crate::model::Document) -> Option<glam::Vec3> {
        crate::extrude::image_planar_move_normal(
            doc,
            &self.image_targets,
            &self.targets,
            &self.plane_targets,
            &self.instance_targets,
        )
    }

    /// World-axis index an image-only move skips for translation and keeps for rotation.
    pub fn planar_skip_axis(&self, doc: &crate::model::Document) -> Option<usize> {
        self.planar_normal(doc).map(crate::extrude::planar_skip_axis)
    }

    /// The face a Face Snap side has settled on (#1075): the one whose point is already
    /// picked, else the one waiting for its point.
    pub fn face_pick(&self, moving: bool) -> Option<crate::model::MateRef> {
        let point = if moving { self.start_point_a } else { self.end_point_a };
        point
            .as_ref()
            .and_then(crate::model::move_point_host_mate_ref)
            .or(if moving { self.pending_face_a } else { self.pending_face_b })
    }

    /// Take a Face Snap pick (#1075): the **face** first, then a **point on that face**.
    /// Returns whether anything changed. Picking a face again starts that side over.
    pub fn take_face_snap_pick(
        &mut self,
        moving: bool,
        face: Option<crate::model::MateRef>,
        point: Option<crate::model::MovePointRef>,
    ) -> bool {
        self.translate_mode = crate::model::MoveTranslateMode::FaceSnap;
        match (face, point) {
            (Some(face), _) => {
                if moving {
                    self.pending_face_a = Some(face);
                    self.start_point_a = None;
                } else {
                    self.pending_face_b = Some(face);
                    self.end_point_a = None;
                }
                true
            }
            (None, Some(point)) => {
                if moving {
                    self.start_point_a = Some(point);
                    self.pending_face_a = None;
                } else {
                    self.end_point_a = Some(point);
                    self.pending_face_b = None;
                }
                true
            }
            (None, None) => false,
        }
    }

    /// Clear one Face Snap side outright (#1075) — the face takes its point with it.
    pub fn clear_face_snap_side(&mut self, moving: bool) {
        if moving {
            self.pending_face_a = None;
            self.start_point_a = None;
        } else {
            self.pending_face_b = None;
            self.end_point_a = None;
        }
    }

    /// The inverse: a stored placement loaded back into the tool (#1079).
    pub fn from_op(op: &crate::model::MoveOperation) -> Self {
        Self {
            targets: op.targets.clone(),
            translate_mode: op.translate_mode,
            start_point_a: op.start_point_a,
            end_point_a: op.end_point_a,
            start_point_b: op.start_point_b,
            end_point_b: op.end_point_b,
            start_point_c: op.start_point_c,
            end_point_c: op.end_point_c,
            plane_targets: op.plane_targets.clone(),
            image_targets: op.image_targets.clone(),
            instance_targets: op.instance_targets.clone(),
            tx: op.tx.clone(),
            ty: op.ty.clone(),
            tz: op.tz.clone(),
            rx: op.rx.clone(),
            ry: op.ry.clone(),
            rz: op.rz.clone(),
            roll_angle: op.roll_angle.clone(),
            face_flip: op.face_flip,
            face_spin: op.face_spin.clone(),
            face_offset: op.face_offset.clone(),
            // A stored placement's points already carry their faces; nothing is half-picked.
            pending_face_a: None,
            pending_face_b: None,
            editing: None,
            pending_gizmo_focus_axis: None,
        }
    }
}

impl CreatingJoint {
    /// The **mobile** (driven) side of a two-sided joint (#991) — the member that isn't the
    /// base. `None` until one is picked.
    ///
    /// Every kind but Rigid joins exactly two parts, and which is held and which moves is the
    /// whole meaning of the joint — so the pane picks them as two named slots rather than as a
    /// list plus a swap button. `members`/`base` stay the model's shape: `base` is the index of
    /// the held side, so the mobile one is simply the other. With a single member picked, a
    /// `base` past the end says that member is the mobile one and nothing is held yet.
    pub fn mobile_member(&self) -> Option<crate::model::JointRef> {
        (0..self.members.len())
            .find(|i| *i != self.base)
            .map(|i| self.members[i])
    }

    /// The **fixed** (held) side — the base.
    pub fn fixed_member(&self) -> Option<crate::model::JointRef> {
        self.members.get(self.base).copied()
    }

    /// Put `part` in the mobile slot (or empty it). Keeps `base` pointing at the held side.
    pub fn set_mobile(&mut self, part: Option<crate::model::JointRef>) {
        match (part, (0..self.members.len()).find(|i| *i != self.base)) {
            (Some(part), Some(i)) => self.members[i] = part,
            // Nothing mobile yet: either no members at all, or the one held member. Inserting
            // ahead of it keeps the held one addressable — it just shifts to index 1.
            (Some(part), None) => {
                self.members.insert(0, part);
                self.base = 1;
            }
            (None, Some(i)) => {
                self.members.remove(i);
                // Only the held member is left, at index 0.
                self.base = 0;
            }
            (None, None) => {}
        }
    }

    /// Put `part` in the fixed slot (or empty it).
    pub fn set_fixed(&mut self, part: Option<crate::model::JointRef>) {
        match part {
            Some(part) if self.base < self.members.len() => self.members[self.base] = part,
            Some(part) => {
                self.members.push(part);
                self.base = self.members.len() - 1;
            }
            None if self.base < self.members.len() => {
                self.members.remove(self.base);
                // Whatever is left is the mobile one, so nothing is held: point past the end.
                self.base = if self.members.is_empty() { 0 } else { 1 };
            }
            None => {}
        }
    }

    /// Load a committed joint back into the tool (#894).
    pub fn from_joint(joint: &crate::model::Joint, editing: crate::model::JointKey) -> Self {
        Self {
            members: joint.members.clone(),
            base: joint.base,
            kind: joint.kind.clone(),
            placement: CreatingMove::from_op(&joint.placement),
            frame: joint.frame.clone(),
            position: joint.position.clone(),
            position2: joint.position2.clone(),
            position3: joint.position3.clone(),
            limits: joint.limits.clone(),
            editing: Some(editing),
        }
    }
}

