    use super::*;

    /// #1765: face-anchored cutting planes expose their tilt-ring handles at the world
    /// positions the viewport draws, so scripts can aim a real pointer drag at them.
    #[test]
    fn gizmos_expose_section_tilt_ring_handles() {
        let mut state = AppState::default();
        state.creating_section = Some(CreatingSectionPlane {
            anchor: Some(crate::hierarchy::SceneElement::ConstructionPlane(pkey(0))),
            roll_deg: 30.0,
            tilt_v_deg: 40.0,
            ..Default::default()
        });
        let gizmos = available_gizmos(&state);
        let tilt_u = gizmos.iter().find(|g| g.name == "tilt_u").expect("tilt_u gizmo");
        let tilt_v = gizmos.iter().find(|g| g.name == "tilt_v").expect("tilt_v gizmo");
        let handle = |axis: Vec3, zero: Vec3, angle_deg: f32| {
            let dir = glam::Quat::from_axis_angle(axis.normalize_or_zero(), angle_deg.to_radians())
                * zero;
            Vec3::ZERO + dir * crate::construction::AXIS_ANGLE_GIZMO_RADIUS_MM
        };
        let (u, v) = crate::construction::plane_basis(Vec3::Z);
        let close = |a: Vec3, b: Vec3| (a - b).length() < 1e-3;
        let tilt_u = tilt_u.position.expect("tilt_u handle position");
        let tilt_v = tilt_v.position.expect("tilt_v handle position");
        assert!(
            close(tilt_u, handle(u, v, 30.0)),
            "tilt_u handle at the drawn spot, got {tilt_u:?}"
        );
        assert!(
            close(tilt_v, handle(v, u, 40.0)),
            "tilt_v handle at the drawn spot, got {tilt_v:?}"
        );
    }

    /// #991: a two-sided joint's parts are picked as two named slots — the **mobile** part and
    /// the **fixed** one it is held against — which `members`/`base` already encode: `base` is
    /// the index of the held side, so the mobile one is the other. The slots must survive
    /// being filled in either order, and being cleared.
    #[test]
    fn a_joints_mobile_and_fixed_slots_fill_in_either_order() {
        use crate::model::JointRef;
        let (a, b) = (JointRef::Body(bkey(0)), JointRef::Body(bkey(1)));

        // Mobile first, then fixed.
        let mut cj = CreatingJoint::default();
        cj.set_mobile(Some(a));
        assert_eq!(cj.mobile_member(), Some(a));
        assert_eq!(cj.fixed_member(), None, "nothing is held yet");
        cj.set_fixed(Some(b));
        assert_eq!(cj.mobile_member(), Some(a));
        assert_eq!(cj.fixed_member(), Some(b));
        assert_eq!(cj.members.len(), 2, "exactly the two sides");
        assert_eq!(cj.members[cj.base], b, "base names the held side");

        // Fixed first, then mobile — the same joint either way round.
        let mut cj = CreatingJoint::default();
        cj.set_fixed(Some(b));
        assert_eq!(cj.fixed_member(), Some(b));
        assert_eq!(cj.mobile_member(), None);
        cj.set_mobile(Some(a));
        assert_eq!(cj.mobile_member(), Some(a));
        assert_eq!(cj.fixed_member(), Some(b));
        assert_eq!(cj.members[cj.base], b);

        // Replacing one side leaves the other alone.
        let c = JointRef::Body(bkey(2));
        cj.set_mobile(Some(c));
        assert_eq!(cj.mobile_member(), Some(c));
        assert_eq!(cj.fixed_member(), Some(b));
        cj.set_fixed(Some(a));
        assert_eq!(cj.mobile_member(), Some(c));
        assert_eq!(cj.fixed_member(), Some(a));

        // Clearing either side leaves the other still readable in its own slot.
        let mut cleared = cj.clone();
        cleared.set_fixed(None);
        assert_eq!(cleared.mobile_member(), Some(c));
        assert_eq!(cleared.fixed_member(), None);
        cleared.set_mobile(None);
        assert_eq!(cleared.mobile_member(), None);
        assert!(cleared.members.is_empty());

        let mut cleared = cj.clone();
        cleared.set_mobile(None);
        assert_eq!(cleared.fixed_member(), Some(a));
        assert_eq!(cleared.mobile_member(), None);
    }

    /// #218: while a body-gathering tool is active, clicking a body (Elements pane / `select`)
    /// toggles it into the tool's set instead of the persistent selection — you can pick bodies
    /// from the pane regardless of the viewport's sub-element picking.
    /// #429: creating a component selects and activates it; elements created while a
    /// component is active are filed into it automatically.
    #[test]
    fn help_mode_toggles_and_sets_explicitly() {
        let mut state = AppState::default();
        assert!(!state.help_mode, "help mode is off by default");

        state.apply(Action::SetHelpMode(None));
        assert!(state.help_mode);
        assert_eq!(state.status, "Help mode on");

        state.apply(Action::SetHelpMode(None));
        assert!(!state.help_mode);

        state.apply(Action::SetHelpMode(Some(true)));
        state.apply(Action::SetHelpMode(Some(true)));
        assert!(state.help_mode, "setting it on twice leaves it on");
    }

    /// #1509: the viewport hint line is on by default and can be set or toggled.
    #[test]
    fn tool_hints_toggles_and_sets_explicitly() {
        let mut state = AppState::default();
        assert!(state.show_tool_hints, "tool hints are on by default");

        state.apply(Action::SetToolHints(None));
        assert!(!state.show_tool_hints);
        assert_eq!(state.status, "Tool hints off");

        state.apply(Action::SetToolHints(None));
        assert!(state.show_tool_hints);
        assert_eq!(state.status, "Tool hints on");

        state.apply(Action::SetToolHints(Some(false)));
        state.apply(Action::SetToolHints(Some(false)));
        assert!(!state.show_tool_hints, "setting it off twice leaves it off");
        state.apply(Action::SetToolHints(Some(true)));
        assert!(state.show_tool_hints);
    }

    #[test]
    fn set_tool_mode_switches_the_active_tool_and_rejects_the_rest() {
        use crate::model::{BooleanOpKind, MoveTranslateMode};
        let mut state = AppState::default();

        // Combine: the mode row, reachable without clicking it.
        state.tool = Tool::Combine;
        assert!(set_tool_mode(&mut state, "cut").is_ok());
        assert_eq!(state.creating_boolean.as_ref().unwrap().kind, BooleanOpKind::Cut);
        assert!(set_tool_mode(&mut state, "intersect").is_ok());
        assert_eq!(state.creating_boolean.as_ref().unwrap().kind, BooleanOpKind::Intersect);
        assert!(set_tool_mode(&mut state, "nonsense").is_err());

        // Switching back to Combine folds side B into side A, as the pane's row does.
        let cb = state.creating_boolean.as_mut().unwrap();
        cb.a = vec![bkey(0)];
        cb.b = vec![bkey(1)];
        cb.picking_b = true;
        set_tool_mode(&mut state, "combine").unwrap();
        let cb = state.creating_boolean.as_ref().unwrap();
        assert_eq!(cb.a, vec![bkey(0), bkey(1)]);
        assert!(cb.b.is_empty());
        assert!(!cb.picking_b);

        // #1533: with side A already filled, leaving Combine for a two-sided mode
        // arms Side B so the next click is the other operand, not another A body.
        for mode in ["cut", "intersect", "difference"] {
            set_tool_mode(&mut state, "combine").unwrap();
            let cb = state.creating_boolean.as_mut().unwrap();
            cb.a = vec![bkey(0)];
            cb.b.clear();
            cb.picking_b = false;
            state.picker_focus = Some(crate::context::PickerTarget::CombineA);
            set_tool_mode(&mut state, mode).unwrap();
            let cb = state.creating_boolean.as_ref().unwrap();
            assert!(
                cb.picking_b,
                "mode {mode} after a Side A pick should arm Side B"
            );
            assert_eq!(
                state.picker_focus,
                Some(crate::context::PickerTarget::CombineB),
                "mode {mode} should focus the Side B picker, not Side A"
            );
        }

        // Empty Side A still needs an A pick — don't skip ahead to B.
        set_tool_mode(&mut state, "combine").unwrap();
        let cb = state.creating_boolean.as_mut().unwrap();
        cb.a.clear();
        cb.b.clear();
        cb.picking_b = false;
        state.picker_focus = Some(crate::context::PickerTarget::CombineA);
        set_tool_mode(&mut state, "cut").unwrap();
        let cb = state.creating_boolean.as_ref().unwrap();
        assert!(!cb.picking_b, "empty Side A stays on A");
        assert_ne!(
            state.picker_focus,
            Some(crate::context::PickerTarget::CombineB),
            "empty Side A must not jump to Side B"
        );

        // Move: only while something is in progress.
        state.tool = Tool::Move;
        assert!(set_tool_mode(&mut state, "free").is_err(), "nothing in progress to set");
        state.creating_move = Some(CreatingMove::default());
        assert!(set_tool_mode(&mut state, "free").is_ok());
        assert_eq!(
            state.creating_move.as_ref().unwrap().translate_mode,
            MoveTranslateMode::Free
        );

        // A tool with no modes says so.
        state.tool = Tool::Circle;
        assert!(set_tool_mode(&mut state, "free").is_err());

        // Shape: cuboid / cylinder / sphere (#1320).
        state.tool = Tool::Shape;
        state.apply(Action::SetTool(Tool::Shape));
        assert!(set_tool_mode(&mut state, "cylinder").is_ok());
        assert_eq!(state.shape_kind, crate::model::PrimitiveKind::Cylinder);
        assert_eq!(
            state.creating_shape.as_ref().unwrap().shape.kind,
            crate::model::PrimitiveKind::Cylinder
        );
        assert!(set_tool_mode(&mut state, "sphere").is_ok());
        assert_eq!(state.shape_kind, crate::model::PrimitiveKind::Sphere);
        assert!(set_tool_mode(&mut state, "cuboid").is_ok());
        assert_eq!(state.shape_kind, crate::model::PrimitiveKind::Cuboid);
        assert!(set_tool_mode(&mut state, "free").is_err());
    }

    /// #1524: Extrude / Revolve / Sweep / Loft / Mirror expose their Output row
    /// through `set_tool_mode("new"|"merge"|"cut")`, and the armed mode is readable.
    #[test]
    fn set_tool_mode_sets_output_row_and_is_readable() {
        use crate::model::MirrorMode;
        let mut state = AppState::default();

        // Extrude: nothing in progress is a clear error; a live draft accepts the names.
        state.tool = Tool::Extrude;
        assert!(
            set_tool_mode(&mut state, "cut").is_err(),
            "nothing in progress to set"
        );
        assert!(current_tool_mode(&state).is_none());
        let sketch = begin_default_sketch(&mut state);
        let rect = crate::construction::add_line_rectangle(
            &mut state.doc, sketch, 0.0, 0.0, 10.0, 10.0, [false; 4],
        );
        state.apply(Action::SetTool(Tool::Extrude));
        state.apply(Action::ToggleExtrudeFace {
            face: ExtrudeFace::Polygon(rect.to_vec()),
        });
        let host = state.doc.bodies.insert(crate::model::Body {
            source: crate::model::BodySource::Extrusion(crate::arena::Key::from_bits(0)),
            material: None,
            name: None,
            shadow: false,
        });
        if let Some(ce) = state.creating_extrusion.as_mut() {
            ce.merge_candidate = Some(host);
        }
        assert!(set_tool_mode(&mut state, "cut").is_ok());
        assert!(matches!(
            state.creating_extrusion.as_ref().unwrap().body_mode,
            ExtrudeBodyMode::Cut(_)
        ));
        assert_eq!(current_tool_mode(&state).as_deref(), Some("cut"));
        assert!(set_tool_mode(&mut state, "merge").is_ok());
        assert!(matches!(
            state.creating_extrusion.as_ref().unwrap().body_mode,
            ExtrudeBodyMode::MergeInto(_)
        ));
        assert_eq!(current_tool_mode(&state).as_deref(), Some("merge"));
        assert!(set_tool_mode(&mut state, "new").is_ok());
        assert_eq!(
            state.creating_extrusion.as_ref().unwrap().body_mode,
            ExtrudeBodyMode::NewBody
        );
        assert_eq!(current_tool_mode(&state).as_deref(), Some("new"));
        assert!(set_tool_mode(&mut state, "nonsense").is_err());

        // Revolve / Sweep / Loft / Mirror share the same three names.
        state.tool = Tool::Revolve;
        state.creating_revolve = Some(CreatingRevolve::default());
        assert!(set_tool_mode(&mut state, "cut").is_ok());
        assert_eq!(
            state.creating_revolve.as_ref().unwrap().body_choice,
            RevolveBodyChoice::Cut
        );
        assert_eq!(current_tool_mode(&state).as_deref(), Some("cut"));
        assert!(set_tool_mode(&mut state, "merge").is_ok());
        assert_eq!(
            state.creating_revolve.as_ref().unwrap().body_choice,
            RevolveBodyChoice::AddTouching
        );

        state.tool = Tool::Sweep;
        state.creating_sweep = Some(CreatingSweep::default());
        assert!(set_tool_mode(&mut state, "cut").is_ok());
        assert_eq!(
            state.creating_sweep.as_ref().unwrap().body_choice,
            RevolveBodyChoice::Cut
        );

        state.tool = Tool::Loft;
        state.creating_loft = Some(CreatingLoft::default());
        assert!(set_tool_mode(&mut state, "merge").is_ok());
        assert_eq!(
            state.creating_loft.as_ref().unwrap().body_choice,
            RevolveBodyChoice::AddTouching
        );

        state.tool = Tool::Mirror;
        state.creating_mirror = Some(CreatingMirror::default());
        assert!(set_tool_mode(&mut state, "cut").is_ok());
        assert_eq!(state.creating_mirror.as_ref().unwrap().mode, MirrorMode::Cut);
        assert!(set_tool_mode(&mut state, "merge").is_ok());
        assert_eq!(state.creating_mirror.as_ref().unwrap().mode, MirrorMode::Join);
        assert_eq!(current_tool_mode(&state).as_deref(), Some("merge"));
    }

    #[test]
    fn active_component_receives_new_elements() {
        use crate::hierarchy::SceneElement;
        use crate::model::ComponentMember as CM;
        let mut state = AppState::default();
        state.apply(Action::CreateComponent { name: Some("Frame".to_string()), parent: None });
        assert_eq!(state.active_component, Some(ckey(0)));
        assert!(state.scene_selection.is_selected(SceneElement::Component(ckey(0))));

        // A plane created now lands in the component.
        state.apply(Action::AddConstructionPlane { from: pkey(0), offset_mm: 20.0 });
        let plane = state.doc.construction_planes.keys().last().unwrap();
        assert_eq!(state.doc.component_of(CM::ConstructionPlane(plane)), Some(ckey(0)));

        // Deactivating (the Document row) stops the filing.
        state.active_component = None;
        state.apply(Action::AddConstructionPlane { from: pkey(0), offset_mm: 40.0 });
        let plane2 = state.doc.construction_planes.keys().last().unwrap();
        assert_eq!(state.doc.component_of(CM::ConstructionPlane(plane2)), None);
    }

    /// #522: the dirty flag tracks divergence from the last-saved baseline — set by a
    /// mutation, cleared by save, and (crucially) cleared again when undo returns the
    /// document to the saved state.
    #[test]
    fn dirty_flag_tracks_saved_baseline() {
        let mut state = AppState::default();
        assert!(!state.dirty, "a fresh empty document is clean");

        // A mutation dirties it.
        state.apply(Action::AddConstructionPlane { from: pkey(0), offset_mm: 20.0 });
        assert!(state.dirty, "adding geometry marks the document dirty");

        // Saving clears it.
        let path = std::env::temp_dir()
            .join(format!("bearcad_dirty_{}.bearcad", std::process::id()))
            .to_string_lossy()
            .into_owned();
        let r = state.apply(Action::Save { path: Some(path.clone()) });
        assert!(matches!(r, ActionResult::Ok), "save should succeed");
        assert!(!state.dirty, "saving clears the dirty flag");

        // A further edit dirties it again; undoing back to the saved state clears it.
        state.apply(Action::AddConstructionPlane { from: pkey(0), offset_mm: 40.0 });
        assert!(state.dirty, "the new edit is unsaved");
        state.apply(Action::UndoLast);
        assert!(
            !state.dirty,
            "undoing back to the saved state reads as clean again"
        );

        // A new document is clean.
        state.apply(Action::AddConstructionPlane { from: pkey(0), offset_mm: 60.0 });
        assert!(state.dirty);
        state.apply(Action::NewDocument);
        assert!(!state.dirty, "New document starts clean");

        let _ = std::fs::remove_file(&path);
    }

    /// #1341: after Save, an added body is written incrementally (not a full rewrite)
    /// and stays invisible to a second connection until the next Save.
    #[test]
    fn save_then_add_body_is_uncommitted_until_save() {
        use crate::model::{Primitive, PrimitiveKind};
        let mut state = AppState::default();
        state.apply(Action::CreateShape {
            shape: Primitive {
                kind: PrimitiveKind::Cuboid,
                origin: [0.0, 0.0, 0.0],
                normal: [0.0, 0.0, 1.0],
                u_axis: [1.0, 0.0, 0.0],
                width: "10".into(),
                depth: "8".into(),
                height: "6".into(),
                radius: String::new(),
                name: Some("first".into()),
            },
        });
        let path = std::env::temp_dir()
            .join(format!("bearcad_incr_app_{}.bearcad", std::process::id()))
            .to_string_lossy()
            .into_owned();
        let _ = std::fs::remove_file(&path);
        assert!(matches!(
            state.apply(Action::Save {
                path: Some(path.clone())
            }),
            ActionResult::Ok
        ));
        let bodies_at_save: i64 = {
            let conn = rusqlite::Connection::open(&path).unwrap();
            conn.query_row("SELECT COUNT(*) FROM bodies", [], |r| r.get(0))
                .unwrap()
        };
        assert_eq!(bodies_at_save, 1);
        let lines_at_save: i64 = {
            let conn = rusqlite::Connection::open(&path).unwrap();
            conn.query_row("SELECT COUNT(*) FROM lines", [], |r| r.get(0))
                .unwrap()
        };

        state.apply(Action::CreateShape {
            shape: Primitive {
                kind: PrimitiveKind::Cuboid,
                origin: [20.0, 0.0, 0.0],
                normal: [0.0, 0.0, 1.0],
                u_axis: [1.0, 0.0, 0.0],
                width: "4".into(),
                depth: "4".into(),
                height: "4".into(),
                radius: String::new(),
                name: Some("second".into()),
            },
        });
        assert!(state.dirty, "unsaved body keeps the dirty marker");
        {
            let session = state.document_session.as_ref().expect("pathed session");
            let session = session.borrow();
            let w = session.last_write();
            assert_eq!(w.inserts("bodies"), 1);
            assert!(
                !w.touched("lines"),
                "existing lines must not be rewritten: {w:?}"
            );
            assert_eq!(
                session.query_i64("SELECT COUNT(*) FROM bodies").unwrap(),
                bodies_at_save + 1
            );
        }
        let other: i64 = {
            let conn = rusqlite::Connection::open(&path).unwrap();
            conn.query_row("SELECT COUNT(*) FROM bodies", [], |r| r.get(0))
                .unwrap()
        };
        assert_eq!(other, bodies_at_save, "another connection sees last commit");

        assert!(matches!(
            state.apply(Action::Save { path: None }),
            ActionResult::Ok
        ));
        assert!(!state.dirty);
        let after: i64 = {
            let conn = rusqlite::Connection::open(&path).unwrap();
            conn.query_row("SELECT COUNT(*) FROM bodies", [], |r| r.get(0))
                .unwrap()
        };
        assert_eq!(after, bodies_at_save + 1);
        let lines_after: i64 = {
            let conn = rusqlite::Connection::open(&path).unwrap();
            conn.query_row("SELECT COUNT(*) FROM lines", [], |r| r.get(0))
                .unwrap()
        };
        assert_eq!(lines_after, lines_at_save);

        drop(state);
        let _ = std::fs::remove_file(&path);
    }

    /// #523: mirroring a body across a plane creates a reflected output body, keeps the
    /// original (never shadowed), and reflects the geometry across the plane. Editing the
    /// target set grows/shrinks the outputs; deleting the op removes only the reflections.
    #[test]
    fn mirror_reflects_a_body_across_a_plane() {
        use crate::hierarchy::SceneElement;
        let mut state = AppState::default();
        // A construction plane = the ground XY (z = 0) plane, normal +Z.
        state.doc.construction_planes.insert(crate::face::default_xy_plane());
        // An imported-mesh tetra sitting entirely above the plane (z in [1, 2]).
        let tetra = vec![
            [Vec3::new(0.0, 0.0, 1.0), Vec3::new(2.0, 0.0, 1.0), Vec3::new(0.0, 2.0, 1.0)],
            [Vec3::new(0.0, 0.0, 1.0), Vec3::new(0.0, 2.0, 1.0), Vec3::new(0.0, 0.0, 2.0)],
            [Vec3::new(0.0, 0.0, 1.0), Vec3::new(0.0, 0.0, 2.0), Vec3::new(2.0, 0.0, 1.0)],
            [Vec3::new(2.0, 0.0, 1.0), Vec3::new(0.0, 0.0, 2.0), Vec3::new(0.0, 2.0, 1.0)],
        ];
        state.import_mesh_body("tetra.stl", tetra, None);
        let body = state.doc.bodies.keys().last().unwrap();

        let r = state.apply(Action::CreateMirrorOperation {
            plane: FaceId::ConstructionPlane(pkey(0)),
            targets: vec![body],
            mode: crate::model::MirrorMode::NewBody,
        });
        assert!(matches!(r, ActionResult::Ok), "mirror should succeed: {r:?}");
        assert_eq!(state.doc.mirror_ops.len(), 1);
        assert_eq!(state.doc.mirror_ops.values().nth(0).unwrap().outputs.len(), 1);

        // The original body is kept and NOT shadowed (a mirror adds, it doesn't relocate).
        assert!(state.doc.bodies.get(body).is_some_and(|b| !b.shadow));

        // The reflected body's geometry sits below the plane (z in [-2, -1]).
        let out = state.doc.mirror_ops.values().nth(0).unwrap().outputs[0];
        let mesh = crate::extrude::body_solid_mesh(&state.doc, out).expect("reflected mesh");
        let (min, max) = mesh.bounds().expect("bounds");
        assert!(
            max.z < 0.0 && (min.z + 2.0).abs() < 0.05 && (max.z + 1.0).abs() < 0.05,
            "reflected z should be ~[-2,-1], got {min:?}..{max:?}"
        );

        // Editing to an empty target set removes the reflected body; back to one restores it.
        state.apply(Action::EditMirrorOperation {
            op: mirkey(0),
            plane: FaceId::ConstructionPlane(pkey(0)),
            targets: vec![body],
            mode: crate::model::MirrorMode::NewBody,
        });
        assert!(state.doc.bodies.contains(out));

        // Deleting the op removes the reflection but keeps the source.
        state.apply(Action::DeleteElement { element: SceneElement::MirrorOp(mirkey(0)) });
        assert!(!state.doc.bodies.contains(out), "reflection removed");
        assert!(!!state.doc.bodies.contains(body), "source kept");
    }

    /// #639: the Mirror tool's Output modes. `Join` fuses each reflection into its own source
    /// (so the output spans both halves and the source is consumed), `Cut` subtracts it, and
    /// switching back to `NewBody` releases the source again.
    #[test]
    fn mirror_output_modes_join_and_cut_against_the_source() {
        use crate::hierarchy::SceneElement;
        use crate::model::{FaceId, MirrorMode};
        // A box extruded z in [0, 5]. Mirrored across the XY plane its reflection is
        // z in [-5, 0], so a Join spans [-5, 5]. (Join/Cut are kernel booleans, so this
        // needs a real BREP body, not an imported mesh.)
        let mut state = box_extrusion_state();
        let body = bkey(0);

        let r = state.apply(Action::CreateMirrorOperation {
            plane: FaceId::ConstructionPlane(pkey(0)),
            targets: vec![body],
            mode: MirrorMode::Join,
        });
        assert!(matches!(r, ActionResult::Ok), "join mirror should succeed: {r:?}");
        assert_eq!(state.doc.mirror_ops.values().nth(0).unwrap().mode, MirrorMode::Join);
        // Join consumes its input, like Move does.
        assert!(state.doc.bodies[body].shadow, "the source is consumed by a Join");

        let out = state.doc.mirror_ops.values().nth(0).unwrap().outputs[0];
        let mesh = crate::extrude::body_solid_mesh(&state.doc, out).expect("joined mesh");
        let (min, max) = mesh.bounds().expect("bounds");
        assert!(
            min.z < -4.9 && max.z > 4.9,
            "a joined mirror spans both halves, got {min:?}..{max:?}"
        );

        // Re-editing back to NewBody releases the source and restores a lone reflection.
        let r = state.apply(Action::EditMirrorOperation {
            op: mirkey(0),
            plane: FaceId::ConstructionPlane(pkey(0)),
            targets: vec![body],
            mode: MirrorMode::NewBody,
        });
        assert!(matches!(r, ActionResult::Ok), "re-edit should succeed: {r:?}");
        assert!(!state.doc.bodies[body].shadow, "NewBody releases the source");
        let mesh = crate::extrude::body_solid_mesh(&state.doc, out).expect("reflected mesh");
        let (min, max) = mesh.bounds().expect("bounds");
        assert!(
            max.z < 0.01 && min.z < -4.9,
            "a plain reflection sits below the plane, got {min:?}..{max:?}"
        );

        // Cut consumes the source too.
        state.apply(Action::EditMirrorOperation {
            op: mirkey(0),
            plane: FaceId::ConstructionPlane(pkey(0)),
            targets: vec![body],
            mode: MirrorMode::Cut,
        });
        assert!(state.doc.bodies[body].shadow, "the source is consumed by a Cut");
        assert_eq!(state.doc.mirror_ops.values().nth(0).unwrap().mode, MirrorMode::Cut);

        // Deleting the op still keeps the source.
        state.apply(Action::DeleteElement { element: SceneElement::MirrorOp(mirkey(0)) });
        assert!(!!state.doc.bodies.contains(body), "source kept");
    }

    /// #523/#528: an in-sketch mirror reflects the picked lines/circles across the mirror
    /// line, keeps the originals, and its outputs are removed when the op is deleted.
    #[test]
    fn sketch_mirror_reflects_geometry_across_a_line() {
        use crate::hierarchy::SceneElement;
        use crate::model::Line;
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        // Mirror axis: the vertical line x = 0.
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, -10.0, 0.0, 10.0)); // 0
        // Target: a segment on the +x side.
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 5.0, 0.0, 8.0, 3.0)); // 1

        let r = state.apply(Action::CreateSketchMirrorOperation {
            sketch,
            line: lkey(0).into(),
            line_targets: vec![lkey(1)],
            circle_targets: vec![],
        });
        assert!(matches!(r, ActionResult::Ok), "sketch mirror should succeed: {r:?}");
        assert_eq!(state.doc.sketch_mirror_ops.len(), 1);
        assert_eq!(state.doc.sketch_mirror_ops.values().nth(0).unwrap().line_outputs.len(), 1);

        // Reflected across x = 0: (5,0)→(-5,0), (8,3)→(-8,3).
        let out = state.doc.sketch_mirror_ops.values().nth(0).unwrap().line_outputs[0];
        let o = &state.doc.lines[out];
        assert!((o.x0 + 5.0).abs() < 1e-3 && o.y0.abs() < 1e-3, "start {:?}", (o.x0, o.y0));
        assert!((o.x1 + 8.0).abs() < 1e-3 && (o.y1 - 3.0).abs() < 1e-3, "end {:?}", (o.x1, o.y1));
        // The original stays.
        assert!(state.doc.lines.contains(lkey(1)));

        // Deleting the op removes the reflection.
        state.apply(Action::DeleteElement { element: SceneElement::SketchMirrorOp(skop(0)) });
        assert!(!state.doc.lines.contains(out), "reflected line removed with the op");
        assert!(state.doc.lines.contains(lkey(1)), "source kept");
    }

    /// #549: after placing a new dimension on a line, the selection clears so the next click
    /// starts a fresh pick instead of adding to the just-dimensioned line.
    #[test]
    fn dimensioning_a_line_clears_the_selection() {
        use crate::hierarchy::SceneElement;
        use crate::model::Line;
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0)); // line 0
        state.apply(Action::ClickSceneElement { element: SceneElement::Line(lkey(0)), additive: false });
        assert!(!state.scene_selection.is_empty(), "the line is selected");
        assert!(state.try_begin_dimension_from_selection(), "a single line dimensions its length");
        // That starts placement (#763); the placement click opens the editor.
        state.tool = Tool::Dimension;
        state.apply(Action::BeginDimensionEdit {
            target: crate::model::DimensionTarget::Distance(
                crate::model::DistanceTarget::LineLength(lkey(0)),
            ),
        });
        assert!(state.editing_committed_dim.is_some());
        let r = state.apply(Action::CommitCommittedDim);
        assert!(matches!(r, ActionResult::Ok), "{r:?}");
        assert!(
            state.scene_selection.is_empty(),
            "the dimensioned line is deselected (#549)"
        );
    }

    /// #547: mirroring a rectangle reflects its corner-coincidences too, so the reflected edges
    /// join into a closed loop (a fillable/extrudable face) — face detection keys vertices by
    /// coincidence, not position.
    #[test]
    fn sketch_mirror_of_a_rectangle_forms_a_face() {
        use crate::model::{Constraint, ConstraintEntity, ConstraintKind, ConstraintPoint, Line, LineEnd};
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        // Line 0: the mirror axis x = 0. Lines 1..=4: a square on the +x side.
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, -20.0, 0.0, 20.0)); // 0 axis
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 2.0, 2.0, 6.0, 2.0)); // 1
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 6.0, 2.0, 6.0, 6.0)); // 2
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 6.0, 6.0, 2.0, 6.0)); // 3
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 2.0, 6.0, 2.0, 2.0)); // 4
        // Stitch the square's four corners with coincidences.
        for (la, ea, lb, eb) in [
            (lkey(1), LineEnd::End, lkey(2), LineEnd::Start),
            (lkey(2), LineEnd::End, lkey(3), LineEnd::Start),
            (lkey(3), LineEnd::End, lkey(4), LineEnd::Start),
            (lkey(4), LineEnd::End, lkey(1), LineEnd::Start),
        ] {
            state.doc.constraints.insert(Constraint {
                sketch,
                kind: ConstraintKind::Coincident {
                    a: ConstraintEntity::Point(ConstraintPoint::LineEndpoint { line: la, end: ea }),
                    b: ConstraintEntity::Point(ConstraintPoint::LineEndpoint { line: lb, end: eb }),
                },
                expression: String::new(),
                dim_offset: None,
                name: None,
            });
        }
        // Before mirroring: exactly one closed loop (the square).
        assert_eq!(crate::polygon::closed_line_loops(&state.doc, sketch).len(), 1);

        state.apply(Action::CreateSketchMirrorOperation {
            sketch,
            line: lkey(0).into(),
            line_targets: vec![lkey(1), lkey(2), lkey(3), lkey(4)],
            circle_targets: vec![],
        });
        assert_eq!(state.doc.sketch_mirror_ops.values().nth(0).unwrap().line_outputs.len(), 4);
        assert_eq!(
            state.doc.sketch_mirror_ops.values().nth(0).unwrap().constraint_outputs.len(),
            4,
            "the four corner-coincidences are reflected"
        );
        // Now two closed loops exist: the source square and its reflection.
        let loops = crate::polygon::closed_line_loops(&state.doc, sketch);
        assert_eq!(loops.len(), 2, "the reflected rectangle forms its own face: {loops:?}");
        // One loop is made entirely of the reflected output lines.
        let outs: std::collections::HashSet<crate::model::LineKey> =
            state.doc.sketch_mirror_ops.values().nth(0).unwrap().line_outputs.iter().copied().collect();
        assert!(
            loops.iter().any(|l| l.iter().all(|li| outs.contains(li))),
            "a face is formed from the reflected lines: {loops:?}"
        );
    }

    /// Seed the in-sketch Mirror pickers the way a pane frame does (#1539).
    fn arm_sketch_mirror_shapes(state: &mut AppState, sketch: crate::model::SketchId) {
        use crate::element_picker::{ElementFilter, ElementKind, ElementPicker, PickLimit};
        let mut line = ElementPicker::new(
            ElementFilter::kind(ElementKind::Line)
                .rule(crate::element_picker::PickRule::InSketch(sketch)),
            PickLimit::Finite(1),
        );
        line.set_focused(false);
        let mut shapes = ElementPicker::new(
            ElementFilter::kinds(&[ElementKind::Line, ElementKind::Circle])
                .rule(crate::element_picker::PickRule::InSketch(sketch)),
            PickLimit::Infinite,
        );
        shapes.set_focused(true);
        state.tool_pickers = vec![
            crate::context::ToolPickerView {
                heading: "Mirror line",
                picker: line,
                target: crate::context::PickerTarget::SketchMirrorLine,
                separator_above: true,
                render: crate::context::PickerRender::Inline,
            },
            crate::context::ToolPickerView {
                heading: "Shapes",
                picker: shapes,
                target: crate::context::PickerTarget::SketchMirrorShapes,
                separator_above: false,
                render: crate::context::PickerRender::Inline,
            },
        ];
    }

    /// #1539: offering a closed sketch profile to the Shapes picker means its boundary
    /// lines, the same expansion a hover-highlighted face click must take.
    #[test]
    fn sketch_mirror_shape_pick_takes_a_profile_as_its_lines() {
        use crate::hierarchy::SceneElement;
        use crate::model::{FaceId, Line};
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, -20.0, 0.0, 20.0)); // 0 axis
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 2.0, 2.0, 6.0, 2.0)); // 1
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 6.0, 2.0, 6.0, 6.0)); // 2
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 6.0, 6.0, 2.0, 6.0)); // 3
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 2.0, 6.0, 2.0, 2.0)); // 4
        state.apply(Action::SetTool(Tool::Mirror));
        let sm = state
            .creating_sketch_mirror
            .get_or_insert_with(|| CreatingSketchMirror::new(sketch));
        sm.line = Some(lkey(0).into());
        arm_sketch_mirror_shapes(&mut state, sketch);
        let face = SceneElement::from_face_id(FaceId::Polygon(vec![
            lkey(1),
            lkey(2),
            lkey(3),
            lkey(4),
        ]));
        state.apply(Action::ClickSceneElement {
            element: face,
            additive: false,
        });
        let sm = state.creating_sketch_mirror.as_ref().expect("mirror armed");
        let mut got = sm.line_targets.clone();
        got.sort();
        assert_eq!(
            got,
            vec![lkey(1), lkey(2), lkey(3), lkey(4)],
            "a face pick should gather the profile's four lines, got {got:?}"
        );
    }

    /// #543: dragging the mirror line re-reflects the sources live — the drag solve doesn't run
    /// the full recompute, so the drag handlers rebuild the mirrors themselves.
    #[test]
    fn sketch_mirror_reflection_tracks_a_dragged_mirror_line() {
        use crate::hierarchy::SceneElement;
        use crate::model::Line;
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        // Mirror axis x = 0 (line 0), a source segment on the +x side (line 1).
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, -10.0, 0.0, 10.0)); // 0
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 5.0, 0.0, 8.0, 0.0)); // 1
        state.apply(Action::CreateSketchMirrorOperation {
            sketch,
            line: lkey(0).into(),
            line_targets: vec![lkey(1)],
            circle_targets: vec![],
        });
        let out = state.doc.sketch_mirror_ops.values().nth(0).unwrap().line_outputs[0];
        assert!((state.doc.lines[out].x0 + 5.0).abs() < 1e-3, "initial reflection at x=-5");

        // Drag the whole mirror line to x = 2 (both endpoints shift +2 in u), by selecting it
        // and dragging. The reflection of (5,0) across x=2 is (-1,0).
        state.apply(Action::ClickSceneElement { element: SceneElement::Line(lkey(0)), additive: false });
        state.apply(Action::BeginLineDrag {
            target: crate::model::ConstraintLine::Line(lkey(0)),
            anchor_u: 0.0,
            anchor_v: 0.0,
        });
        state.apply(Action::DragLine { u: 2.0, v: 0.0 });
        // Sanity: the mirror line actually moved.
        let ml = &state.doc.lines[lkey(0)];
        assert!((ml.x0 - 2.0).abs() < 1e-3, "mirror line moved to x=2: {}", ml.x0);
        // The reflection followed: (5,0) across x=2 → (-1,0).
        let o = &state.doc.lines[out];
        assert!(
            (o.x0 + 1.0).abs() < 1e-2,
            "reflection should track the moved line, got x0={}",
            o.x0
        );
    }

    /// #1538: a sketch origin axis or an in-plane world axis is a valid 2D mirror line.
    #[test]
    fn sketch_mirror_reflects_across_origin_and_world_axes() {
        use crate::model::{Line, SketchAxis, SketchMirrorAxis};
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state
            .doc
            .lines
            .insert(Line::from_local_endpoints(sketch, 5.0, 1.0, 8.0, 4.0));

        let r = state.apply(Action::CreateSketchMirrorOperation {
            sketch,
            line: SketchMirrorAxis::OriginAxis(SketchAxis::Y),
            line_targets: vec![lkey(0)],
            circle_targets: vec![],
        });
        assert!(matches!(r, ActionResult::Ok), "origin Y axis: {r:?}");
        let out = state.doc.sketch_mirror_ops.values().nth(0).unwrap().line_outputs[0];
        let o = &state.doc.lines[out];
        assert!(
            (o.x0 + 5.0).abs() < 1e-3 && (o.y0 - 1.0).abs() < 1e-3,
            "across local Y (x=0): {:?}",
            (o.x0, o.y0)
        );

        state.apply(Action::UndoLast);
        let r = state.apply(Action::CreateSketchMirrorOperation {
            sketch,
            line: SketchMirrorAxis::X,
            line_targets: vec![lkey(0)],
            circle_targets: vec![],
        });
        assert!(matches!(r, ActionResult::Ok), "world X axis: {r:?}");
        let out = state.doc.sketch_mirror_ops.values().nth(0).unwrap().line_outputs[0];
        let o = &state.doc.lines[out];
        assert!(
            (o.x0 - 5.0).abs() < 1e-3 && (o.y0 + 1.0).abs() < 1e-3,
            "across world X (y=0): {:?}",
            (o.x0, o.y0)
        );
    }

    /// #521 / #1284: exporting a component gathers every body filed into it and its nested
    /// components (not bodies in unrelated components), and produces non-empty STL/STEP/3MF bytes.
    #[test]
    fn component_export_gathers_nested_bodies() {
        use crate::model::ComponentMember as CM;
        let mut state = AppState::default();
        state.apply(Action::CreateComponent { name: Some("Frame".to_string()), parent: None }); // 0
        state.apply(Action::CreateComponent { name: None, parent: Some(ckey(0)) }); // 1 (nested in 0)
        state.apply(Action::CreateComponent { name: Some("Other".to_string()), parent: None }); // 2

        // Three imported-mesh bodies (each a tetrahedron so meshing yields triangles).
        let tetra = vec![
            [Vec3::ZERO, Vec3::X, Vec3::Y],
            [Vec3::ZERO, Vec3::Y, Vec3::Z],
            [Vec3::ZERO, Vec3::Z, Vec3::X],
            [Vec3::X, Vec3::Z, Vec3::Y],
        ];
        for name in ["a.stl", "b.stl", "c.stl"] {
            state.import_mesh_body(name, tetra.clone(), None);
        }
        // Body 0 → Frame (0), body 1 → nested (1), body 2 → the unrelated Other (2).
        state.doc.set_component_member(CM::Body(bkey(0)), Some(ckey(0)));
        state.doc.set_component_member(CM::Body(bkey(1)), Some(ckey(1)));
        state.doc.set_component_member(CM::Body(bkey(2)), Some(ckey(2)));

        // Exporting Frame gathers its own body and the nested component's, not Other's.
        let mut frame = state.component_body_indices(ckey(0));
        frame.sort_unstable();
        assert_eq!(frame, vec![bkey(0), bkey(1)], "Frame export = its body + the nested body");
        assert_eq!(state.component_body_indices(ckey(1)), vec![bkey(1)], "the nested component alone");
        assert_eq!(state.component_body_indices(ckey(2)), vec![bkey(2)], "Other is independent");

        // The export produces real geometry.
        let stl = state
            .export_component_stl_bytes(ckey(0))
            .expect("frame STL export");
        assert!(!stl.is_empty(), "STL bytes produced");
        assert!(
            state.export_component_step_bytes(ckey(0)).is_ok_and(|b| !b.is_empty()),
            "STEP bytes produced"
        );
        let threemf = state
            .export_component_3mf_bytes(ckey(0))
            .expect("frame 3MF export");
        assert!(!threemf.is_empty(), "3MF bytes produced");
        assert_eq!(&threemf[0..4], b"PK\x03\x04", "3MF is a ZIP package");

        // An empty component reports an error rather than an empty file.
        state.apply(Action::CreateComponent { name: Some("Empty".to_string()), parent: None }); // 3
        assert!(state.component_body_indices(ckey(3)).is_empty());
        assert!(state.export_component_stl_bytes(ckey(3)).is_err());
        assert!(state.export_component_3mf_bytes(ckey(3)).is_err());
    }

    /// #1294 / #1299: multi-body 3MF export keeps each body as its own object with
    /// m:colorgroup colors so Bambu Studio assigns distinct filament slots.
    #[test]
    fn export_3mf_preserves_body_colors() {
        let mut state = two_box_state(false);
        // Seeded palette: Yellow is index 4, Red is index 3.
        let yellow = state
            .doc
            .materials
            .iter()
            .find(|(_, m)| m.name == "Yellow")
            .map(|(k, _)| k)
            .expect("Yellow material");
        let red = state
            .doc
            .materials
            .iter()
            .find(|(_, m)| m.name == "Red")
            .map(|(k, _)| k)
            .expect("Red material");
        state.apply(Action::SetBodyMaterial {
            body: bkey(0),
            material: Some(yellow),
        });
        state.apply(Action::SetBodyMaterial {
            body: bkey(1),
            material: Some(red),
        });

        let bytes = state
            .export_3mf_bytes(None)
            .expect("document 3MF export");
        assert_eq!(&bytes[0..4], b"PK\x03\x04");

        // Pull the model XML from the store-method ZIP the same way threemf tests do.
        let model = {
            let want = b"3D/3dmodel.model";
            let mut pos = 0;
            let archive = &bytes;
            let mut found = None;
            while pos + 30 <= archive.len() {
                let sig = u32::from_le_bytes(archive[pos..pos + 4].try_into().unwrap());
                if sig != 0x04034b50 {
                    break;
                }
                let method = u16::from_le_bytes(archive[pos + 8..pos + 10].try_into().unwrap());
                let comp =
                    u32::from_le_bytes(archive[pos + 18..pos + 22].try_into().unwrap()) as usize;
                let name_len =
                    u16::from_le_bytes(archive[pos + 26..pos + 28].try_into().unwrap()) as usize;
                let extra_len =
                    u16::from_le_bytes(archive[pos + 28..pos + 30].try_into().unwrap()) as usize;
                let name_start = pos + 30;
                let name_end = name_start + name_len;
                let data_start = name_end + extra_len;
                let data_end = data_start + comp;
                if &archive[name_start..name_end] == want {
                    assert_eq!(method, 0, "store only");
                    found = Some(String::from_utf8(archive[data_start..data_end].to_vec()).unwrap());
                    break;
                }
                pos = data_end;
            }
            found.expect("3D/3dmodel.model in package")
        };

        assert!(
            model.contains("<basematerials id=\"1\">"),
            "must declare basematerials:\n{model}"
        );
        assert!(
            model.contains("<m:colorgroup id=\"2\">"),
            "must declare m:colorgroup for Bambu filament mapping:\n{model}"
        );
        assert!(
            model.contains("name=\"Yellow\" displaycolor=\"#E8C94AFF\""),
            "yellow material missing:\n{model}"
        );
        assert!(
            model.contains("name=\"Red\" displaycolor=\"#E8615CFF\""),
            "red material missing:\n{model}"
        );
        assert!(
            model.contains("<m:color color=\"#E8C94AFF\"/>"),
            "yellow m:color:\n{model}"
        );
        assert!(
            model.contains("<m:color color=\"#E8615CFF\"/>"),
            "red m:color:\n{model}"
        );
        // Objects pid into colorgroup (id=2) with distinct pindex → Fila 1 and 2.
        assert!(model.contains("pid=\"2\" pindex=\"0\""), "first color:\n{model}");
        assert!(model.contains("pid=\"2\" pindex=\"1\""), "second color:\n{model}");
        assert!(model.contains("objectid=\"3\"") && model.contains("objectid=\"4\""));
        // Not a single fused object.
        assert_eq!(
            model.matches("<object ").count(),
            2,
            "one object per body, got:\n{model}"
        );
    }

    /// #423: components group elements; membership, nesting, visibility cascade, and
    /// unit inheritance all flow through the component chain.
    #[test]
    fn components_group_hide_and_inherit_units() {
        use crate::hierarchy::SceneElement;
        use crate::model::ComponentMember as CM;
        let mut state = AppState::default();

        state.apply(Action::CreateComponent { name: Some("Frame".to_string()), parent: None });
        state.apply(Action::CreateComponent { name: None, parent: Some(ckey(0)) });
        assert_eq!(state.doc.components.len(), 2);
        assert_eq!(state.doc.components[ckey(1)].parent, Some(ckey(0)));

        // A cycle is refused.
        let r = state.apply(Action::MoveToComponent {
            element: SceneElement::Component(ckey(0)),
            component: Some(ckey(1)),
        });
        assert!(matches!(r, ActionResult::Err(_)), "cycle must be refused");

        // File a plane (and thus its sketch) into the nested component.
        let plane = state.doc.construction_planes.insert(crate::face::default_xy_plane());
        let sketch = state.doc.add_sketch(crate::model::FaceId::ConstructionPlane(plane));
        state.apply(Action::MoveToComponent {
            element: SceneElement::ConstructionPlane(plane),
            component: Some(ckey(1)),
        });
        assert_eq!(state.doc.component_of(CM::ConstructionPlane(plane)), Some(ckey(1)));

        // Hiding the OUTER component hides the plane and sketch inside the inner one.
        assert!(state
            .element_visibility
            .effective_visible(&state.doc, SceneElement::ConstructionPlane(plane)));
        state.element_visibility.set_visible(SceneElement::Component(ckey(0)), false);
        assert!(!state
            .element_visibility
            .effective_visible(&state.doc, SceneElement::ConstructionPlane(plane)));
        assert!(!state
            .element_visibility
            .effective_visible(&state.doc, SceneElement::Sketch(sketch)));
        state.element_visibility.set_visible(SceneElement::Component(ckey(0)), true);

        // Units: the sketch inherits the outer component's override through the chain.
        state.apply(Action::SetComponentUnits {
            component: ckey(0),
            length: Some(crate::value::LengthUnit::In),
            angle: None,
        });
        assert_eq!(
            crate::model::effective_length_unit(&state.doc, sketch),
            crate::value::LengthUnit::In
        );
        // The inner component's own override wins over the outer's.
        state.apply(Action::SetComponentUnits {
            component: ckey(1),
            length: Some(crate::value::LengthUnit::Cm),
            angle: None,
        });
        assert_eq!(
            crate::model::effective_length_unit(&state.doc, sketch),
            crate::value::LengthUnit::Cm
        );

        // Deleting the inner component re-homes its member to the outer one.
        state.apply(Action::DeleteElement { element: SceneElement::Component(ckey(1)) });
        assert!(!state.doc.components.contains(ckey(1)));
        assert_eq!(state.doc.component_of(CM::ConstructionPlane(plane)), Some(ckey(0)));
        assert_eq!(
            crate::model::effective_length_unit(&state.doc, sketch),
            crate::value::LengthUnit::In,
            "after the inner component is gone the outer override applies"
        );
    }

