    #[test]
    fn body_click_feeds_the_active_tool_set() {
        use crate::model::{ExtrudeFace, FaceId};
        let mut state = AppState::default();
        state.apply(Action::BeginSketch { face: FaceId::ConstructionPlane(pkey(0)), viewport: None });
        let sketch = state.sketch_session.unwrap().sketch;
        let lines =
            crate::construction::add_line_rectangle(&mut state.doc, sketch, 0.0, 0.0, 10.0, 10.0, [false; 4]);
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![ExtrudeFace::Polygon(lines.to_vec())],
            distance: 5.0,
            body: ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
        
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,

        });
        assert_eq!(state.doc.bodies.len(), 1);

        state.apply(Action::SetTool(Tool::Move));
        // A body click lands in the Move set, not the persistent selection.
        state.apply(Action::ClickSceneElement { element: SceneElement::Body(bkey(0)), additive: false });
        assert_eq!(state.creating_move.as_ref().unwrap().targets, vec![bkey(0)]);
        assert!(state.scene_selection.is_empty(), "tool click must not touch the selection");
        // Clicking again toggles it back out.
        state.apply(Action::ClickSceneElement { element: SceneElement::Body(bkey(0)), additive: false });
        assert!(state.creating_move.as_ref().unwrap().targets.is_empty());

        // With the Select tool, a body click is an ordinary selection.
        state.apply(Action::SetTool(Tool::Select));
        state.apply(Action::ClickSceneElement { element: SceneElement::Body(bkey(0)), additive: false });
        assert!(state.scene_selection.is_selected(SceneElement::Body(bkey(0))));
    }

    /// #1086: the Move tool's translate mode is sticky for the session. Set it (via the
    /// scripted mode setter), leave the tool, come back — the fresh in-progress move
    /// starts in the mode it was left in, not back at Point Snap.
    #[test]
    fn move_translate_mode_survives_switching_tools() {
        use crate::model::MoveTranslateMode as M;
        let mut state = AppState::default();
        assert_eq!(state.move_translate_mode, M::default());

        state.apply(Action::SetTool(Tool::Move));
        assert_eq!(
            state.creating_move.as_ref().unwrap().translate_mode,
            M::default(),
            "a first entry starts at the default"
        );

        // Switch to Face Snap through the scripted mode setter (#672), which records the
        // sticky session mode.
        set_tool_mode(&mut state, "face_snap").unwrap();
        assert_eq!(state.move_translate_mode, M::FaceSnap);
        assert_eq!(state.creating_move.as_ref().unwrap().translate_mode, M::FaceSnap);

        // Leave the tool and come back: the in-progress move is discarded and recreated,
        // but the fresh one opens in Face Snap.
        state.apply(Action::SetTool(Tool::Select));
        assert!(state.creating_move.is_none(), "leaving Move drops the in-progress move");
        state.apply(Action::SetTool(Tool::Move));
        assert_eq!(
            state.creating_move.as_ref().unwrap().translate_mode,
            M::FaceSnap,
            "the mode came back with the tool (#1086)"
        );
    }

    /// #217: a Move op can target a construction plane, transforming its frame in place; the
    /// plane's origin shifts, and anything anchored to it follows (it's plane-relative).
    #[test]
    fn moving_a_construction_plane_shifts_its_frame() {
        let mut state = AppState::default();
        let base = state.doc.construction_planes[pkey(0)].origin;
        let result = state.apply(Action::CreateMoveOperation {
            keep_inputs: false,
            translate_mode: crate::model::MoveTranslateMode::Free,
            start_point_a: None,
            end_point_a: None,
            start_point_b: None,
            end_point_b: None,
            start_point_c: None,
            end_point_c: None,
            targets: vec![],
            plane_targets: vec![pkey(0)],
            image_targets: vec![],
            instance_targets: Vec::new(),
            tx: String::new(),
            ty: String::new(),
            tz: "40mm".to_string(),
            rx: String::new(),
            ry: String::new(),
            rz: String::new(),
            face_flip: false,
            face_spin: String::new(),
            roll_angle: String::new(),
            face_offset: String::new(),
        });
        assert!(matches!(result, ActionResult::Ok), "{}", state.status);
        let moved = state.doc.construction_planes[pkey(0)].origin;
        assert!(
            (moved.z - base.z - 40.0).abs() < 1e-3,
            "plane should move +40 in z (base {} -> {})",
            base.z,
            moved.z
        );
        // Editing the op back to zero returns the plane home.
        let op = state.doc.move_ops.keys().last().unwrap();
        state.apply(Action::EditMoveOperation {
translate_mode: crate::model::MoveTranslateMode::Free,
            start_point_a: None,
            end_point_a: None,
            start_point_b: None,
            end_point_b: None,
            start_point_c: None,
            end_point_c: None,
            op,
            targets: vec![],
            plane_targets: vec![pkey(0)],
            image_targets: vec![],
            instance_targets: Vec::new(),
            tx: String::new(),
            ty: String::new(),
            tz: String::new(),
            rx: String::new(),
            ry: String::new(),
            rz: String::new(),
            face_flip: false,
            face_spin: String::new(),
            roll_angle: String::new(),
            face_offset: String::new(),
        });
        assert!((state.doc.construction_planes[pkey(0)].origin.z - base.z).abs() < 1e-3);
    }

