    /// #721: importing a file that (transitively) imports this document is refused.
    #[test]
    fn import_unit_refuses_a_cycle() {
        let dir = std::env::temp_dir();
        let b_path = dir.join("bearcad_unit_cycle_b.bearcad");

        // A imports B (by relative path), saved beside it.
        let mut a_state = AppState::default();
        a_state.doc.units.insert(crate::model::ImportedUnit {
            source: crate::model::UnitSource::RelativePath(
                "bearcad_unit_cycle_b.bearcad".to_string(),
            ),
            link: crate::model::LinkMode::Dynamic,
            document: crate::model::Document::default(),
            source_mtime: None,
            source_hash: None,
        });
        let a_path = dir.join("bearcad_unit_cycle_a.bearcad");
        let _ = std::fs::remove_file(&a_path);
        crate::storage::save(&a_path.to_string_lossy(), &a_state.doc).unwrap();

        // B tries to import A back.
        let mut state = AppState::default();
        state.path = Some(b_path.to_string_lossy().to_string());
        let result = state.apply(Action::ImportUnit {
            path: a_path.to_string_lossy().to_string(),
            link: None,
            name: None,
        });
        assert!(matches!(result, ActionResult::Err(_)), "cycle must be refused");
        assert!(state.status.contains("cycle"), "status: {}", state.status);
        assert!(state.doc.units.is_empty(), "refused import leaves nothing behind");
        assert!(state.doc.unit_instances.is_empty());

        let _ = std::fs::remove_file(&a_path);
    }

    /// #721: a relative-path import survives the importing document being saved elsewhere —
    /// the embedded copy keeps the document self-contained.
    #[test]
    fn imported_unit_survives_saving_the_document_elsewhere() {
        let unit_path = write_unit_file("bearcad_unit_move_a.bearcad");
        let mut state = AppState::default();
        state.path = Some(
            std::env::temp_dir().join("bearcad_unit_move_b.bearcad").to_string_lossy().to_string(),
        );
        state.apply(Action::ImportUnit {
            path: unit_path.to_string_lossy().to_string(),
            link: None,
            name: None,
        });
        assert_eq!(state.doc.units.len(), 1);
        // The source file disappears and B is saved somewhere else entirely.
        std::fs::remove_file(&unit_path).unwrap();
        let elsewhere_dir = std::env::temp_dir().join("bearcad_unit_move_elsewhere");
        std::fs::create_dir_all(&elsewhere_dir).unwrap();
        let elsewhere = elsewhere_dir.join("b.bearcad");
        let r = state.apply(Action::Save { path: Some(elsewhere.to_string_lossy().to_string()) });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);

        let loaded = crate::storage::open(&elsewhere.to_string_lossy()).unwrap();
        assert_eq!(loaded.units.len(), 1, "the embedded copy travels with the document");
        assert_eq!(loaded.unit_instances.len(), 1);
        assert_eq!(loaded.units[ukey(0)].document.parameters.values().next().unwrap().name, "width");

        let _ = std::fs::remove_dir_all(&elsewhere_dir);
    }

    /// A unit file whose document extrudes a 10×10 square to a parametric `width` height
    /// (#724), so overrides visibly move its geometry.
    fn write_solid_unit_file(name: &str) -> std::path::PathBuf {
        let mut doc = crate::model::Document::default();
        doc.parameters.insert(crate::model::Parameter {
            name: "width".to_string(),
            expression: "10".to_string(),
            primary: false,
            minimum: None,
            maximum: None,
            step: None,
            source: None,
        });
        let sketch = doc.add_sketch(crate::model::FaceId::ConstructionPlane(pkey(0)));
        crate::construction::add_line_rectangle(&mut doc, sketch, 0.0, 0.0, 10.0, 10.0, [false; 4]);
        doc.extrusions.insert(crate::model::Extrusion {
            sketch,
            faces: vec![crate::model::ExtrudeFace::Polygon(vec![lkey(0), lkey(1), lkey(2), lkey(3)])],
            distance: 10.0,
            target: None,
            expression: "width".to_string(),
            symmetric: false,
            name: None,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: String::new(),
            edge_treatments: Vec::new(),
        });
        doc.bodies.insert(crate::model::Body {
            source: crate::model::BodySource::Extrusion(xkey(0)),
            material: None,
            name: None,
            shadow: false,
        });
        let path = std::env::temp_dir().join(name);
        let _ = std::fs::remove_file(&path);
        crate::storage::save(&path.to_string_lossy(), &doc).unwrap();
        path
    }

    /// Import a solid unit into a fresh state anchored in the temp dir; returns the state
    /// and the materialized unit body's index (#724).
    fn state_with_solid_unit(file: &str, anchor: &str) -> (AppState, crate::model::BodyKey) {
        let unit_path = write_solid_unit_file(file);
        let mut state = AppState::default();
        state.path = Some(std::env::temp_dir().join(anchor).to_string_lossy().to_string());
        let r = state.apply(Action::ImportUnit {
            path: unit_path.to_string_lossy().to_string(),
            link: None,
            name: None,
        });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        let _ = std::fs::remove_file(&unit_path);
        let body = state
            .doc
            .bodies
            .iter()
            .find_map(|(k, b)| {
                matches!(b.source, crate::model::BodySource::UnitInstance(i) if i == uikey(0))
                    .then_some(k)
            })
            .expect("the instance materialized as a body");
        (state, body)
    }

    /// #724: a unit's corners are Move snap points, exactly like a body's — the same
    /// quantized-key `MovePointRef` resolves against the materialized body's mesh.
    #[test]
    fn move_snaps_onto_a_unit_vertex() {
        let (state, body) = state_with_solid_unit(
            "bearcad_unit_snap_a.bearcad",
            "bearcad_unit_snap_b.bearcad",
        );
        let corner = glam::Vec3::new(10.0, 10.0, 10.0);
        let key = crate::hierarchy::quantize_body_point(corner);
        let resolved = crate::extrude::move_point_world(
            &state.doc,
            &crate::model::MovePointRef::Vertex { body, p: key },
        )
        .expect("the unit corner resolves as a Move snap point");
        assert!((resolved - corner).length() < 1e-2, "{resolved:?}");
    }

    /// #724: a dimension to a unit edge is stored analytically, so it re-resolves — and
    /// its value updates — when the instance's parameter overrides change.
    #[test]
    fn dimension_to_a_unit_edge_follows_overrides() {
        let (mut state, body) = state_with_solid_unit(
            "bearcad_unit_dim_a.bearcad",
            "bearcad_unit_dim_b.bearcad",
        );
        // Select a vertical edge (its length is the parametric extrusion height).
        let (a, b) = (
            crate::hierarchy::quantize_body_point(glam::Vec3::new(10.0, 10.0, 0.0)),
            crate::hierarchy::quantize_body_point(glam::Vec3::new(10.0, 10.0, 10.0)),
        );
        state.apply(Action::ClickSceneElement {
            element: SceneElement::BodyEdge { body, a, b },
            additive: false,
        });
        let source = crate::parameters::derived_source_from_selection(&state.doc, &state.scene_selection)
            .expect("the unit edge measures");
        assert!(
            matches!(source, crate::model::ParameterSource::UnitEdgeLength { .. }),
            "the unit edge upgrades to its analytic identity: {source:?}"
        );
        let pi = crate::parameters::add_derived_parameter(&mut state.doc, source, None).unwrap();
        let value = |doc: &crate::model::Document, pi: crate::model::ParameterKey| {
            crate::value::eval_length_mm_in_doc(&doc.parameters[pi].expression, doc).unwrap()
        };
        assert!((value(&state.doc, pi) - 10.0).abs() < 1e-2);

        // Overriding the unit's width re-resolves the same analytic edge at its new length.
        state.doc.unit_instances[uikey(0)].parameter_overrides =
            vec![("width".to_string(), "25".to_string())];
        crate::parameters::recompute_document_geometry(&mut state.doc).unwrap();
        assert!(
            (value(&state.doc, pi) - 25.0).abs() < 1e-2,
            "the dimension follows the override: {}",
            state.doc.parameters[pi].expression
        );
    }

    /// #724: a unit's flat face is an ordinary pickable body face — `ElementKind::of`
    /// classifies it as a face, so any face picker accepts it.
    #[test]
    fn a_picker_accepts_a_unit_face() {
        let (state, body) = state_with_solid_unit(
            "bearcad_unit_face_a.bearcad",
            "bearcad_unit_face_b.bearcad",
        );
        let solid = crate::extrude::body_solid_mesh(&state.doc, body).expect("unit body meshes");
        let faces = crate::gpu_viewport::solid_mesh_coplanar_faces(&solid);
        assert!(!faces.is_empty(), "the unit body has pickable coplanar faces");
        let tris = &faces[0];
        let centroid = tris
            .iter()
            .flat_map(|t| t.iter())
            .copied()
            .fold(glam::Vec3::ZERO, |acc, p| acc + p)
            / (tris.len() * 3) as f32;
        let normal = (tris[0][1] - tris[0][0]).cross(tris[0][2] - tris[0][0]).normalize();
        let element = SceneElement::BodyFace {
            body,
            centroid: crate::hierarchy::quantize_body_point(centroid),
            normal: crate::hierarchy::quantize_body_point(normal),
        };
        assert_eq!(
            crate::element_picker::ElementKind::of(&element),
            crate::element_picker::ElementKind::Face,
            "face pickers accept the unit face"
        );
        assert!(crate::document_lifecycle::element_alive(&state.doc, element));
    }

    /// The top cap of the solid unit's box as a sketchable unit face (#725).
    fn unit_top_face(state: &AppState) -> crate::model::FaceId {
        let inner_face = crate::units::inner_face_ids(
            &crate::units::evaluate_instance(&state.doc, uikey(0)).unwrap().document,
        )
        .into_iter()
        .find(|f| matches!(f, crate::model::FaceId::ExtrudeCap { top: true, .. }))
        .expect("the unit box has a top cap");
        crate::model::FaceId::UnitFace { instance: uikey(0), face: Box::new(inner_face) }
    }

    /// #725: sketching on a unit's face projects its outline in as associative
    /// construction edges, which re-project when an instance override changes.
    #[test]
    fn sketch_on_a_unit_face_projects_its_outline_and_follows_overrides() {
        let (mut state, _) = state_with_solid_unit(
            "bearcad_unit_sketchface_a.bearcad",
            "bearcad_unit_sketchface_b.bearcad",
        );
        let face = unit_top_face(&state);
        let r = state.apply(Action::BeginSketch { face: face.clone(), viewport: None });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        let sketch = state.sketch_session.unwrap().sketch;

        let projected: Vec<crate::model::LineKey> = state
            .doc
            .lines
            .iter()
            .filter(|(_, l)| {
                l.sketch == sketch
                    && matches!(l.projection, Some(crate::model::ProjectionSource::UnitEdge { .. }))
            })
            .map(|(li, _)| li)
            .collect();
        assert_eq!(projected.len(), 4, "the square cap projects its four edges");
        assert!(
            projected.iter().all(|&li| state.doc.lines[li].construction),
            "projected edges are construction references"
        );
        let side = |doc: &crate::model::Document, li: crate::model::LineKey| {
            let l = &doc.lines[li];
            (((l.x1 - l.x0).powi(2) + (l.y1 - l.y0).powi(2)) as f32).sqrt()
        };
        assert!((side(&state.doc, projected[0]) - 10.0).abs() < 1e-2);

        // The cap sits at the parametric height; overriding `width` moves it and the
        // sketch's frame + projections follow. The cap outline stays 10x10 (only the
        // height changes), so verify by the sketch frame's origin height instead.
        state.doc.unit_instances[uikey(0)].parameter_overrides =
            vec![("width".to_string(), "25".to_string())];
        crate::parameters::recompute_document_geometry(&mut state.doc).unwrap();
        let frame = crate::face::sketch_frame(&state.doc, face).expect("frame still resolves");
        assert!(
            (frame.origin.z - 25.0).abs() < 1e-2,
            "the sketch plane follows the override: {:?}",
            frame.origin
        );
        // Re-projection kept the outline attached (endpoints still resolve, same length).
        assert!((side(&state.doc, projected[0]) - 10.0).abs() < 1e-2);
    }

    /// #725: deleting the instance takes the sketch on its face unhealthy rather than
    /// letting it land somewhere wrong.
    #[test]
    fn deleting_the_instance_takes_the_unit_face_sketch_unhealthy() {
        let (mut state, _) = state_with_solid_unit(
            "bearcad_unit_sketchdead_a.bearcad",
            "bearcad_unit_sketchdead_b.bearcad",
        );
        let face = unit_top_face(&state);
        state.apply(Action::BeginSketch { face, viewport: None });
        let sketch = state.sketch_session.unwrap().sketch;
        state.apply(Action::ExitSketch);

        state.apply(Action::ClickSceneElement {
            element: SceneElement::UnitInstance(uikey(0)),
            additive: false,
        });
        state.apply(Action::DeleteSelection);
        assert_eq!(
            state
                .document_health
                .element_status(SceneElement::Sketch(sketch)),
            crate::document_health::HealthStatus::Invalid,
            "the orphaned sketch reports invalid"
        );
        assert!(
            state
                .document_health
                .element_reason(SceneElement::Sketch(sketch))
                .is_some(),
            "with a reason saying why"
        );
    }

    /// #726: an extrusion with Output = Cut drawn on a unit's face cuts into the unit —
    /// the result is the importing document's own body, the unit stays intact (its
    /// materialized body just shadows as the consumed input), and a re-sync-style
    /// replacement of the embedded copy re-runs the cut against the new geometry.
    #[test]
    fn cutting_extrude_targets_a_unit_and_survives_resync() {
        let (mut state, unit_body) = state_with_solid_unit(
            "bearcad_unit_cut_a.bearcad",
            "bearcad_unit_cut_b.bearcad",
        );
        let face = unit_top_face(&state);
        state.apply(Action::BeginSketch { face, viewport: None });
        let sketch = state.sketch_session.unwrap().sketch;
        let hole = crate::construction::add_line_rectangle(
            &mut state.doc, sketch, 3.0, 3.0, 4.0, 4.0, [false; 4],
        );
        let r = state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![crate::model::ExtrudeFace::Polygon(hole.to_vec())],
            distance: -10.0,
            body: ExtrudeBodyChoice::Cut,
            target: None,
            symmetric: false,
        
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,

        });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);

        let cut_body = state
            .doc
            .bodies
            .iter()
            .find_map(|(k, b)| {
                matches!(b.source, crate::model::BodySource::UnitCut { instance, .. } if instance == uikey(0))
                    .then_some(k)
            })
            .expect("the cut lands on the document's own UnitCut body");
        assert!(
            state.doc.bodies[unit_body].shadow,
            "the consumed unit body shadows; the unit itself is untouched"
        );
        assert_eq!(
            state.doc.units[ukey(0)].document.extrusions.len(),
            1,
            "the embedded copy still has only its own extrusion"
        );
        let volume = |mesh: &crate::extrude::SolidMesh| {
            let (min, max) = mesh.bounds().unwrap();
            (max - min).length()
        };
        let cut_mesh =
            crate::extrude::body_solid_mesh(&state.doc, cut_body).expect("cut body meshes");
        assert!(!cut_mesh.is_empty());
        let before = volume(&cut_mesh);

        // A boolean with the unit on side B (#726): the unit body feeds the op like any
        // other body.
        let plate_lines = {
            state.apply(Action::BeginSketch {
                face: crate::model::FaceId::ConstructionPlane(pkey(0)),
                viewport: None,
            });
            let s2 = state.sketch_session.unwrap().sketch;
            let l = crate::construction::add_line_rectangle(
                &mut state.doc, s2, -20.0, 0.0, 10.0, 10.0, [false; 4],
            );
            state.apply(Action::CreateExtrusion {
                expression: None,
                sketch: s2,
                faces: vec![crate::model::ExtrudeFace::Polygon(l.to_vec())],
                distance: 4.0,
                body: ExtrudeBodyChoice::New,
                target: None,
                symmetric: false,
            
                taper: 0.0,
                taper_mode: crate::model::ExtrudeTaperMode::Distance,
                taper_expression: None,

            });
            l
        };
        let _ = plate_lines;
        let own_body = state
            .doc
            .bodies
            .iter()
            .find_map(|(k, b)| (!b.shadow && matches!(b.source, crate::model::BodySource::Extrusion(_))).then_some(k))
            .expect("the plate body exists");
        let rb = state.apply(Action::CreateBooleanOperation {
            kind: crate::model::BooleanOpKind::Cut,
            a: vec![own_body],
            b: vec![unit_body],
            keep_b: false,
            solid_count: None,
        });
        assert_eq!(rb, ActionResult::Ok, "status: {}", state.status);
        assert!(
            !state.doc.boolean_ops.is_empty(),
            "the boolean took the unit as an input"
        );

        // Re-sync simulation (#732 will do this from disk): the embedded copy is replaced
        // with new geometry; both operations re-run against it.
        let mut taller = state.doc.units[ukey(0)].document.clone();
        taller.parameters.values_mut().next().unwrap().expression = "18".to_string();
        crate::parameters::recompute_document_geometry(&mut taller).unwrap();
        state.doc.units[ukey(0)].document = taller;
        state.refresh_document_health();
        let cut_after =
            crate::extrude::body_solid_mesh(&state.doc, cut_body).expect("cut re-runs");
        assert!(
            (volume(&cut_after) - before).abs() > 1e-3,
            "the cut result follows the replaced embedded geometry"
        );
    }

    /// #728: an override changes one instance only; clearing it restores the unit's own
    /// value; the pane's row model hides secondary parameters until asked.
    #[test]
    fn unit_parameter_overrides_are_per_instance_and_revertable() {
        let unit_path = write_solid_unit_file("bearcad_unit_override_a.bearcad");
        let mut state = AppState::default();
        state.path = Some(
            std::env::temp_dir().join("bearcad_unit_override_b.bearcad").to_string_lossy().to_string(),
        );
        for _ in 0..2 {
            state.apply(Action::ImportUnit {
                path: unit_path.to_string_lossy().to_string(),
                link: None,
                name: None,
            });
        }
        let _ = std::fs::remove_file(&unit_path);
        // Mark `width` primary in the embedded copy, and add a secondary internal.
        state.doc.units[ukey(0)].document.parameters.values_mut().next().unwrap().primary = true;
        state.doc.units[ukey(0)].document.parameters.insert(crate::model::Parameter {
            name: "internal".to_string(),
            expression: "width * 2".to_string(),
            primary: false,
            minimum: None,
            maximum: None,
            step: None,
            source: None,
        });

        let r = state.apply(Action::SetUnitParameterOverride {
            instance: uikey(0),
            name: "width".to_string(),
            expression: Some("25".to_string()),
        });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        let height = |doc: &crate::model::Document, instance: crate::model::UnitInstanceKey| {
            let eval = crate::units::evaluate_instance(doc, instance).unwrap();
            let (min, max) = eval.meshes[0].bounds().unwrap();
            max.z - min.z
        };
        assert!((height(&state.doc, uikey(0)) - 25.0).abs() < 1e-2, "instance 0 follows its override");
        assert!((height(&state.doc, uikey(1)) - 10.0).abs() < 1e-2, "instance 1 is untouched");

        // The pane's rows: overridden value shows, secondary hidden until asked.
        let rows = crate::parameters::unit_parameter_rows(&state.doc, uikey(0), false);
        assert_eq!(rows.len(), 1, "only the primary knob shows by default");
        assert_eq!(rows[0].name, "width");
        assert!(rows[0].overridden);
        assert_eq!(rows[0].expression, "25");
        let all_rows = crate::parameters::unit_parameter_rows(&state.doc, uikey(0), true);
        assert_eq!(all_rows.len(), 2, "internals appear when asked");
        assert!(all_rows.iter().any(|r| r.name == "internal" && !r.primary));

        // Clearing the override restores the unit's own value.
        state.apply(Action::SetUnitParameterOverride {
            instance: uikey(0),
            name: "width".to_string(),
            expression: None,
        });
        assert!((height(&state.doc, uikey(0)) - 10.0).abs() < 1e-2, "back to the unit's own value");
        assert!(state.doc.unit_instances[uikey(0)].parameter_overrides.is_empty());
    }

    /// #1404: cloning a unit instance copies its parameter overrides to the new instance.
    #[test]
    fn clone_unit_instance_copies_parameter_overrides() {
        let unit_path = write_solid_unit_file("bearcad_unit_clone_a.bearcad");
        let mut state = AppState::default();
        state.path = Some(
            std::env::temp_dir().join("bearcad_unit_clone_b.bearcad").to_string_lossy().to_string(),
        );
        state.apply(Action::ImportUnit {
            path: unit_path.to_string_lossy().to_string(),
            link: None,
            name: None,
        });
        let _ = std::fs::remove_file(&unit_path);
        state.doc.units[ukey(0)].document.parameters.values_mut().next().unwrap().primary = true;
        state.apply(Action::SetUnitParameterOverride {
            instance: uikey(0),
            name: "width".to_string(),
            expression: Some("25".to_string()),
        });
        assert_eq!(state.doc.unit_instances.len(), 1);
        let r = state.apply(Action::CloneUnitInstance { instance: uikey(0) });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        assert_eq!(state.doc.unit_instances.len(), 2, "a second instance appears");
        assert_eq!(
            state.doc.unit_instances[uikey(1)].unit,
            state.doc.unit_instances[uikey(0)].unit,
            "the clone references the same unit"
        );
        // The clone carries the same overrides as the source.
        assert_eq!(
            state.doc.unit_instances[uikey(0)].parameter_overrides,
            state.doc.unit_instances[uikey(1)].parameter_overrides,
            "clone keeps the source's parameter overrides"
        );
        assert_eq!(state.doc.unit_instances[uikey(1)].parameter_overrides[0].1, "25");
        // Different instance names.
        assert_ne!(
            state.doc.unit_instances[uikey(0)].name,
            state.doc.unit_instances[uikey(1)].name
        );
    }

    /// #1176: unit overrides clamp to min/max and snap to step defined on the unit.
    #[test]
    fn unit_override_respects_parameter_bounds() {
        let unit_path = write_solid_unit_file("bearcad_unit_bounds.bearcad");
        let mut state = AppState::default();
        state.path = Some(
            std::env::temp_dir()
                .join("bearcad_unit_bounds_host.bearcad")
                .to_string_lossy()
                .to_string(),
        );
        state.apply(Action::ImportUnit {
            path: unit_path.to_string_lossy().to_string(),
            link: None,
            name: None,
        });
        let _ = std::fs::remove_file(&unit_path);
        // width on the unit: min 0, max 20, step 5.
        let p = state.doc.units[ukey(0)]
            .document
            .parameters
            .values_mut()
            .next()
            .unwrap();
        p.primary = true;
        p.minimum = Some("0".into());
        p.maximum = Some("20".into());
        p.step = Some("5".into());

        let r = state.apply(Action::SetUnitParameterOverride {
            instance: uikey(0),
            name: "width".to_string(),
            expression: Some("12".to_string()),
        });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        let stored = &state.doc.unit_instances[uikey(0)].parameter_overrides[0].1;
        let v = crate::value::eval_length_mm(stored).unwrap();
        assert!(
            (v - 10.0).abs() < 1e-2,
            "12 snaps to 10; stored {stored} ({v})"
        );

        let r = state.apply(Action::SetUnitParameterOverride {
            instance: uikey(0),
            name: "width".to_string(),
            expression: Some("99".to_string()),
        });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        let stored = &state.doc.unit_instances[uikey(0)].parameter_overrides[0].1;
        let v = crate::value::eval_length_mm(stored).unwrap();
        assert!((v - 20.0).abs() < 1e-2, "99 clamps to max 20; got {stored} ({v})");

        // Slider-range rows expose min+max.
        let rows = crate::parameters::unit_parameter_rows(&state.doc, uikey(0), false);
        let width = rows.iter().find(|r| r.name == "width").unwrap();
        assert!(width.limits.unwrap().min.is_some() && width.limits.unwrap().max.is_some());
    }

    /// #731: renaming an instance rewrites every reference to it — parameter
    /// expressions, dimensioned lines, tool fields, other instances' overrides — in the
    /// same undoable step; a colliding rename is refused.
    #[test]
    fn renaming_an_instance_rewrites_references_and_undoes_as_one_step() {
        let unit_path = write_solid_unit_file("bearcad_unit_rename_a.bearcad");
        let mut state = AppState::default();
        state.path = Some(
            std::env::temp_dir().join("bearcad_unit_rename_b.bearcad").to_string_lossy().to_string(),
        );
        for _ in 0..2 {
            state.apply(Action::ImportUnit {
                path: unit_path.to_string_lossy().to_string(),
                link: None,
                name: None,
            });
        }
        let _ = std::fs::remove_file(&unit_path);
        let first = state.doc.unit_instances[uikey(0)].name.clone().unwrap();
        assert_eq!(first, "bearcad_unit_rename_a");

        // References of several kinds.
        state.apply(Action::AddParameter {
            name: "x".to_string(),
            expression: format!("{first}.width * 2"),
        });
        state.doc.extrusions.insert(crate::model::Extrusion {
            sketch: skey(0),
            faces: Vec::new(),
            distance: 10.0,
            target: None,
            expression: format!("{first}.width + 1"),
            symmetric: false,
            name: None,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: String::new(),
            edge_treatments: Vec::new(),
        });
        state.doc.unit_instances[uikey(1)].parameter_overrides =
            vec![("width".to_string(), format!("{first}.width / 2"))];
        state.doc.unit_instances[uikey(1)].placement.tx = format!("{first}.width");

        let r = state.apply(Action::CommitElementName {
            element: SceneElement::UnitInstance(uikey(0)),
            name: "left bracket".to_string(),
        });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        assert_eq!(
            state.doc.parameters.values().find(|p| p.name == "x").unwrap().expression,
            "`left bracket`.width * 2",
            "a spaced new name rewrites into its backticked spelling"
        );
        assert_eq!(
            state.doc.extrusions.values().last().unwrap().expression,
            "`left bracket`.width + 1",
            "tool fields rewrite too"
        );
        assert_eq!(
            state.doc.unit_instances[uikey(1)].parameter_overrides[0].1,
            "`left bracket`.width / 2"
        );
        assert_eq!(state.doc.unit_instances[uikey(1)].placement.tx, "`left bracket`.width");
        assert_eq!(
            crate::value::eval_length_mm_in_doc("`left bracket`.width", &state.doc),
            Some(10.0),
            "the qualified reference still evaluates after the rename"
        );

        // A collision is refused.
        let r = state.apply(Action::CommitElementName {
            element: SceneElement::UnitInstance(uikey(1)),
            name: "left bracket".to_string(),
        });
        assert!(matches!(r, ActionResult::Err(_)), "colliding rename refused");
        assert!(state.status.contains("already named"), "status: {}", state.status);

        // One undo restores both the name and the references.
        state.apply(Action::UndoLast);
        assert_eq!(
            state.doc.unit_instances[uikey(0)].name.as_deref(),
            Some(first.as_str()),
            "undo restores the name"
        );
        assert_eq!(
            state.doc.parameters.values().find(|p| p.name == "x").unwrap().expression,
            format!("{first}.width * 2"),
            "…and the references, in the same step"
        );
    }

    /// #732: a dynamic unit picks up a changed source (updating every instance at once);
    /// a static one waits until told; a sync that orphans a reference reports unhealthy
    /// and undoes cleanly; a missing source leaves the document fully usable.

    /// Hover-seeded sizes make `can_commit` true from the first click; Enter on Radius
    /// must still be an advance, not a commit.
    #[test]
    fn shape_enter_finishes_only_on_the_last_dimension() {
        use crate::model::PrimitiveKind as K;
        assert!(!shape_enter_finishes_placement(K::Cylinder, Some(ShapeDimension::Radius)));
        assert!(shape_enter_finishes_placement(K::Cylinder, Some(ShapeDimension::Height)));
        assert!(!shape_enter_finishes_placement(K::Cuboid, None));
        assert!(shape_enter_finishes_placement(K::Cuboid, Some(ShapeDimension::Height)));
        assert!(shape_enter_finishes_placement(K::Sphere, Some(ShapeDimension::Radius)));
        assert!(!shape_enter_finishes_placement(K::Sphere, Some(ShapeDimension::Height)));
    }

    /// #909/#911: the Shape tool arms a shape of the last-used kind, its shortcut cycles
    /// which shape, and committing lands a body.
    #[test]
    fn shape_tool_arms_cycles_and_commits() {
        use crate::model::PrimitiveKind as K;
        let mut state = AppState::default();
        state.apply(Action::SetTool(Tool::Shape));
        let creating = state.creating_shape.as_ref().expect("the tool arms a shape");
        assert_eq!(creating.shape.kind, K::Cuboid, "the first shape is a cuboid");
        assert!(!creating.can_commit(&state.doc), "with no dimensions yet");

        // Cycling keeps the tool armed and remembers the choice for next time.
        state.apply(Action::SetShapeKind { kind: state.shape_kind.next() });
        assert_eq!(state.shape_kind, K::Cylinder);
        assert_eq!(state.creating_shape.as_ref().unwrap().shape.kind, K::Cylinder);

        state.apply(Action::SetShapeDimension {
            field: ShapeDimension::Radius,
            text: "5".to_string(),
        });
        assert!(!state.creating_shape.as_ref().unwrap().can_commit(&state.doc));
        state.apply(Action::SetShapeDimension {
            field: ShapeDimension::Height,
            text: "20".to_string(),
        });
        assert!(state.creating_shape.as_ref().unwrap().can_commit(&state.doc));

        state.apply(Action::CommitShape);
        assert_eq!(state.doc.primitives.len(), 1);
        assert_eq!(state.doc.bodies.len(), 1);
        assert!(
            state.creating_shape.as_ref().is_some_and(|c| c.phase == ShapePhase::Anchor),
            "stay armed with an empty draft (#1498)"
        );
        assert_eq!(state.tool, Tool::Shape);
    }

