    #[test]
    fn syncing_replaces_the_embedded_copy() {
        let unit_path = write_solid_unit_file("bearcad_unit_sync_a.bearcad");
        let mut state = AppState::default();
        state.path = Some(
            std::env::temp_dir().join("bearcad_unit_sync_b.bearcad").to_string_lossy().to_string(),
        );
        for _ in 0..2 {
            state.apply(Action::ImportUnit {
                path: unit_path.to_string_lossy().to_string(),
                link: None, // dynamic
                name: None,
            });
        }
        assert_eq!(state.doc.units.len(), 1);
        let height = |doc: &crate::model::Document, instance: crate::model::UnitInstanceKey| {
            let eval = crate::units::evaluate_instance(doc, instance).unwrap();
            let (min, max) = eval.meshes[0].bounds().unwrap();
            max.z - min.z
        };
        assert!((height(&state.doc, uikey(0)) - 10.0).abs() < 1e-2);

        // B references the unit's parameter; the source then changes on disk (taller box,
        // `width` renamed to `w` — the rename can't be followed, it just goes missing).
        let first = state.doc.unit_instances[uikey(0)].name.clone().unwrap();
        state.apply(Action::AddParameter {
            name: "x".to_string(),
            expression: format!("{first}.width"),
        });
        let mut v2 = state.doc.units[ukey(0)].document.clone();
        v2.parameters.values_mut().next().unwrap().name = "w".to_string();
        v2.extrusions[xkey(0)].expression = "w * 2".to_string();
        std::thread::sleep(std::time::Duration::from_millis(1100)); // move the mtime second
        crate::storage::save(&unit_path.to_string_lossy(), &v2).unwrap();

        assert!(
            crate::units::unit_is_stale(&state.doc.units[ukey(0)], state.path.as_deref(), None),
            "the changed source reads as stale"
        );
        // The dynamic auto-sync path (open / poll) picks it up without being told.
        assert_eq!(state.sync_stale_dynamic_units(), 1);
        assert!((height(&state.doc, uikey(0)) - 20.0).abs() < 1e-2, "instance 0 updated");
        assert!((height(&state.doc, uikey(1)) - 20.0).abs() < 1e-2, "…and instance 1, at once");

        // The orphaned reference reports through health rather than blocking the sync.
        state.refresh_document_health();
        let xi = state
            .doc
            .parameters
            .iter()
            .find_map(|(k, p)| (p.name == "x").then_some(k))
            .unwrap();
        assert_ne!(
            state.document_health.parameter_status(xi),
            crate::document_health::HealthStatus::Healthy,
            "the reference to the renamed parameter reports unhealthy"
        );

        // A static unit does not sync by itself — only when told.
        state.doc.units[ukey(0)].link = crate::model::LinkMode::Static;
        let mut v3 = v2.clone();
        v3.extrusions[xkey(0)].expression = "w * 3".to_string();
        std::thread::sleep(std::time::Duration::from_millis(1100));
        crate::storage::save(&unit_path.to_string_lossy(), &v3).unwrap();
        assert_eq!(state.sync_stale_dynamic_units(), 0, "static units never auto-sync");
        assert!((height(&state.doc, uikey(0)) - 20.0).abs() < 1e-2, "unchanged until told");
        let r = state.apply(Action::SyncUnit { unit: ukey(0) });
        assert_eq!(r, ActionResult::Ok, "status: {}", state.status);
        assert!((height(&state.doc, uikey(0)) - 30.0).abs() < 1e-2, "explicit update applies");

        // Undo puts the previous embedded copy back.
        state.apply(Action::UndoLast);
        assert!((height(&state.doc, uikey(0)) - 20.0).abs() < 1e-2, "undo restores the copy");

        // A missing source refuses the sync and leaves everything usable.
        std::fs::remove_file(&unit_path).unwrap();
        let r = state.apply(Action::SyncUnit { unit: ukey(0) });
        assert!(matches!(r, ActionResult::Err(_)));
        assert!((height(&state.doc, uikey(0)) - 20.0).abs() < 1e-2, "the embedded copy still builds");
        assert!(
            !crate::units::unit_is_stale(&state.doc.units[ukey(0)], state.path.as_deref(), None),
            "a missing source is not 'stale' — the embedded copy is the truth"
        );
    }

    /// #733: the source watcher reports a changed dynamic source once it has sat quiet
    /// for a poll (rapid rewrites collapse to one rebuild, mid-write saves are never
    /// read); static units are never watched.
    #[test]
    fn source_watcher_debounces_and_ignores_static_units() {
        let unit_path = write_solid_unit_file("bearcad_unit_watch_a.bearcad");
        let mut state = AppState::default();
        state.path = Some(
            std::env::temp_dir().join("bearcad_unit_watch_b.bearcad").to_string_lossy().to_string(),
        );
        state.apply(Action::ImportUnit {
            path: unit_path.to_string_lossy().to_string(),
            link: None, // dynamic
            name: None,
        });
        let mut watcher = crate::units::UnitSourceWatcher::default();
        assert!(
            watcher.poll(&state.doc, state.path.as_deref(), None).is_empty(),
            "an unchanged source reports nothing (first pass observes)"
        );
        assert!(watcher.poll(&state.doc, state.path.as_deref(), None).is_empty());

        // The source is rewritten — twice, quickly (an editor's temp-write dance).
        let mut v2 = state.doc.units[ukey(0)].document.clone();
        v2.parameters.values_mut().next().unwrap().expression = "17".to_string();
        crate::storage::save(&unit_path.to_string_lossy(), &v2).unwrap();
        assert!(
            watcher.poll(&state.doc, state.path.as_deref(), None).is_empty(),
            "a fresh change waits for a quiet poll"
        );
        std::thread::sleep(std::time::Duration::from_millis(30));
        v2.parameters.values_mut().next().unwrap().expression = "18".to_string();
        crate::storage::save(&unit_path.to_string_lossy(), &v2).unwrap();
        assert!(
            watcher.poll(&state.doc, state.path.as_deref(), None).is_empty(),
            "still moving — still waiting"
        );
        assert_eq!(
            watcher.poll(&state.doc, state.path.as_deref(), None),
            vec![ukey(0)],
            "quiet now: exactly one rebuild for the whole burst"
        );
        // The app then syncs it; afterwards the watcher goes quiet again.
        assert_eq!(state.apply(Action::SyncUnit { unit: ukey(0) }), ActionResult::Ok);
        assert!(watcher.poll(&state.doc, state.path.as_deref(), None).is_empty());

        // A static unit is never reported, however stale.
        state.doc.units[ukey(0)].link = crate::model::LinkMode::Static;
        v2.parameters.values_mut().next().unwrap().expression = "19".to_string();
        std::thread::sleep(std::time::Duration::from_millis(30));
        crate::storage::save(&unit_path.to_string_lossy(), &v2).unwrap();
        assert!(watcher.poll(&state.doc, state.path.as_deref(), None).is_empty());
        assert!(watcher.poll(&state.doc, state.path.as_deref(), None).is_empty());

        let _ = std::fs::remove_file(&unit_path);
    }

