    /// #1656: the kernel (BREP) STEP path must carry the part name into the file —
    /// it used to leave OCCT's own defaults ('Open CASCADE STEP translator ...'), so
    /// the part arrived in the recipient's CAD tool nameless.
    #[test]
    #[cfg(not(target_arch = "wasm32"))]
    fn step_brep_export_names_the_product() {
        let mut state = AppState::default();
        state.apply(Action::CreateShape {
            shape: crate::model::Primitive {
                kind: crate::model::PrimitiveKind::Cuboid,
                origin: [0.0, 0.0, 0.0],
                normal: [0.0, 0.0, 1.0],
                u_axis: [1.0, 0.0, 0.0],
                width: "10".into(),
                depth: "10".into(),
                height: "10".into(),
                radius: String::new(),
                name: Some("Bracket".into()),
            },
        });
        let body = state.doc.bodies.keys().next().expect("the cuboid body");
        crate::names::set_element_name(
            &mut state.doc,
            crate::hierarchy::SceneElement::Body(body),
            "Bracket".to_string(),
        )
        .expect("name the body");
        assert!(
            crate::extrude::posed_body_shape(&state.doc, body).is_some(),
            "this test needs the kernel BREP path"
        );
        let path = std::env::temp_dir().join(format!(
            "bearcad_step_name_{}.step",
            std::process::id()
        ));
        let p = path.to_string_lossy().to_string();
        assert!(matches!(
            state.apply(Action::ExportStepBody { path: p, body }),
            ActionResult::Ok
        ));
        let text = std::fs::read_to_string(&path).expect("read exported step");
        let _ = std::fs::remove_file(&path);
        assert!(
            text.contains("PRODUCT('Bracket'"),
            "product must be named: {}",
            text.lines().filter(|l| l.contains("PRODUCT(")).collect::<Vec<_>>().join("\n")
        );
        assert!(
            text.contains("FILE_NAME('Bracket'"),
            "header must be named: {}",
            text.lines().filter(|l| l.contains("FILE_NAME")).collect::<Vec<_>>().join("\n")
        );
        assert!(
            !text.contains("Open CASCADE STEP translator"),
            "OCCT's default product name must be replaced"
        );

        // The name rides through OCCT's own writer, which escapes Part 21 strings —
        // pin that so an apostrophe can't produce a malformed file (#1655).
        crate::names::set_element_name(
            &mut state.doc,
            crate::hierarchy::SceneElement::Body(body),
            "Bob's Block".to_string(),
        )
        .expect("rename the body");
        let p = path.to_string_lossy().to_string();
        assert!(matches!(
            state.apply(Action::ExportStepBody { path: p, body }),
            ActionResult::Ok
        ));
        let text = std::fs::read_to_string(&path).expect("read exported step");
        let reread = crate::kernel::Shape::read_step(&path);
        let _ = std::fs::remove_file(&path);
        assert!(text.contains("PRODUCT('Bob''s Block'"), "{}",
            text.lines().filter(|l| l.contains("PRODUCT(")).collect::<Vec<_>>().join("\n"));
        assert!(reread.is_some(), "an apostrophe must not break the file");
    }

    /// #1029: combining a STEP import with an extruded cube must leave a solid body.
    /// STEP used to land as triangles only, so the boolean had no BREP for the import and
    /// the combined body tessellated to nothing.
    #[test]
    #[cfg(not(target_arch = "wasm32"))]
    fn combining_a_step_import_with_a_cube_keeps_a_solid() {
        // A 10³ box as real BREP STEP (same path the catalog uses).
        let box_shape = crate::kernel::Shape::prism(
            &[
                glam::Vec3::new(0.0, 0.0, 0.0),
                glam::Vec3::new(10.0, 0.0, 0.0),
                glam::Vec3::new(10.0, 10.0, 0.0),
                glam::Vec3::new(0.0, 10.0, 0.0),
            ],
            glam::Vec3::new(0.0, 0.0, 10.0),
        )
        .expect("prism");
        let path = std::env::temp_dir().join(format!(
            "bearcad_combine_step_{}.step",
            std::process::id()
        ));
        assert!(box_shape.write_step(&path), "write STEP");

        let mut state = AppState::default();
        assert!(matches!(
            state.apply(Action::ImportStep {
                path: path.to_string_lossy().to_string()
            }),
            ActionResult::Ok
        ));
        let _ = std::fs::remove_file(&path);
        let mesh = state.doc.imported_meshes.keys().next().expect("the imported mesh");
        assert!(
            state.doc.imported_meshes[mesh].step_bytes.is_some(),
            "a kernel STEP import must keep the BREP bytes"
        );
        assert!(
            crate::extrude::occt_body_shape(&state.doc, bkey(0)).is_some(),
            "the import must re-read as a kernel solid"
        );

        // An extruded cube next to it (disjoint).
        let sketch = begin_default_sketch(&mut state);
        let rect = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            20.0,
            0.0,
            30.0,
            10.0,
            [false; 4],
        );
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![ExtrudeFace::Polygon(rect.to_vec())],
            distance: 10.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
        
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,

        });
        assert_eq!(state.doc.bodies.len(), 2);

        assert!(matches!(
            state.apply(Action::CreateBooleanOperation {
                kind: crate::model::BooleanOpKind::Combine,
                a: vec![bkey(0), bkey(1)],
                b: Vec::new(),
                keep_b: false,
                solid_count: None,
            }),
            ActionResult::Ok
        ));
        let outputs = &state.doc.boolean_ops.values().nth(0).unwrap().outputs;
        assert!(!outputs.is_empty(), "combine should produce at least one body");
        let mut any_vol: f64 = 0.0;
        for &out in outputs {
            let mesh = crate::extrude::body_solid_mesh(&state.doc, out)
                .expect("each combined body should have a mesh");
            assert!(
                !mesh.triangles.is_empty(),
                "combining a STEP import with a cube must not produce an empty body"
            );
            let vol = crate::extrude::occt_body_shape(&state.doc, out)
                .and_then(|s| s.volume())
                .unwrap_or(0.0);
            any_vol = any_vol.max(vol);
        }
        // Without the BREP bytes the fuse used to yield nothing (empty body, volume 0).
        // With them there is real solid — at least one 10³ cube's worth of material.
        assert!(
            any_vol > 500.0,
            "combined body should have real volume, got max {any_vol}"
        );
    }

