    /// Revolve (SPEC §3.5): committing a face + axis creates the revolution and its body
    /// under one marker; undo removes both. Cut mode requires picked bodies.
    #[test]
    fn commit_revolve_creates_body_and_undo_removes_both() {
        let mut state = AppState::default();
        let sketch = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
        let lines = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            10.0,
            0.0,
            10.0,
            10.0,
            [false; 4],
        );
        state.creating_revolve = Some(CreatingRevolve {
            sketch: Some(sketch),
            faces: vec![crate::model::ExtrudeFace::Polygon(lines.to_vec())],
            axis: Some(crate::model::RevolveAxis::Y),
            ..CreatingRevolve::default()
        });
        assert!(matches!(state.apply(Action::CommitRevolve), ActionResult::Ok));
        assert_eq!(state.doc.revolutions.len(), 1);
        let rev = state.doc.revolutions.keys().next().expect("the revolve");
        assert!((state.doc.revolutions[rev].angle_deg - 360.0).abs() < 1e-3);
        assert_eq!(
            state.doc.bodies.values().last().map(|b| b.source.clone()),
            Some(crate::model::BodySource::Revolve(rev))
        );
        assert_eq!(state.doc.shape_order.last(), Some(&ShapeKind::Revolution));
        assert!(state.creating_revolve.is_none());
        assert!(crate::extrude::body_solid_mesh(&state.doc, state.doc.bodies.keys().last().unwrap()).is_some());

        state.apply(Action::UndoLast);
        assert!(state.doc.revolutions.is_empty());
        assert!(state.doc.bodies.is_empty());
    }

    /// #sweep: committing a sweep stores the op + its NewBody body under one undo
    /// marker; a single undo removes both (mirrors the revolve commit test).
    #[test]
    fn commit_sweep_creates_body_and_undo_removes_both() {
        let mut state = AppState::default();
        let sketch = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
        let lines = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            0.0,
            0.0,
            10.0,
            10.0,
            [false; 4],
        );
        // A vertical plane (normal Y, u→X, v→Z) so the path line leaves the ground plane.
        state.doc.construction_planes.insert(crate::model::ConstructionPlane {
            origin: glam::Vec3::ZERO,
            normal: glam::Vec3::Y,
            u_axis: glam::Vec3::X,
            v_axis: glam::Vec3::Z,
            parent: crate::model::ConstructionPlaneParent::Root,
            definition: crate::face::default_xy_plane_definition(),
            repeat_instance: None,
            name: None,
            extent: crate::model::PlaneExtent::default(),
        });
        let path_sketch = state
            .doc
            .add_sketch(FaceId::ConstructionPlane(
                state.doc.construction_planes.keys().last().unwrap(),
            ));
        state
            .doc
            .lines
            .insert(crate::model::Line::from_local_endpoints(path_sketch, 5.0, 0.0, 5.0, 25.0));
        let li = state.doc.lines.keys().last().expect("the line just added");
        state.creating_sweep = Some(CreatingSweep {
            sketch: Some(sketch),
            faces: vec![crate::model::ExtrudeFace::Polygon(lines.to_vec())],
            path: vec![li],
            ..CreatingSweep::default()
        });
        assert!(matches!(state.apply(Action::CommitSweep), ActionResult::Ok));
        assert_eq!(state.doc.sweeps.len(), 1);
        let sweep = state.doc.sweeps.keys().next().expect("the sweep");
        assert_eq!(state.doc.sweeps[sweep].path, vec![li]);
        assert_eq!(
            state.doc.bodies.values().last().map(|b| b.source.clone()),
            Some(crate::model::BodySource::Sweep(sweep))
        );
        assert_eq!(state.doc.shape_order.last(), Some(&ShapeKind::Sweep));
        assert!(state.creating_sweep.is_none());
        assert!(crate::extrude::body_solid_mesh(&state.doc, state.doc.bodies.keys().last().unwrap()).is_some());

        state.apply(Action::UndoLast);
        assert!(state.doc.sweeps.is_empty());
        assert!(state.doc.bodies.is_empty());
    }

    /// Editing a committed revolution (#211) re-points it in place: the angle changes, no new
    /// revolution or body is created, and its NewBody output body is preserved.
    #[test]
    fn edit_revolve_updates_params_in_place() {
        let mut state = AppState::default();
        let sketch = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
        let lines = crate::construction::add_line_rectangle(
            &mut state.doc, sketch, 10.0, 0.0, 10.0, 10.0, [false; 4],
        );
        let faces = vec![crate::model::ExtrudeFace::Polygon(lines.to_vec())];
        state.creating_revolve = Some(CreatingRevolve {
            sketch: Some(sketch),
            faces: faces.clone(),
            axis: Some(crate::model::RevolveAxis::Y),
            ..CreatingRevolve::default()
        });
        assert!(matches!(state.apply(Action::CommitRevolve), ActionResult::Ok));
        assert_eq!(state.doc.revolutions.len(), 1);
        let rev = state.doc.revolutions.keys().next().expect("the revolve");
        let body_count = state.doc.bodies.len();

        // Re-open the revolution for editing with a new (180°) sweep.
        state.creating_revolve = Some(CreatingRevolve {
            sketch: Some(sketch),
            faces,
            axis: Some(crate::model::RevolveAxis::Y),
            text: "180".to_string(),
            user_edited: true,
            editing: Some(rev),
            ..CreatingRevolve::default()
        });
        assert!(matches!(state.apply(Action::CommitRevolve), ActionResult::Ok));
        // Same revolution and body count; only the angle changed.
        assert_eq!(state.doc.revolutions.len(), 1);
        assert_eq!(state.doc.bodies.len(), body_count);
        assert!((state.doc.revolutions[rev].angle_deg - 180.0).abs() < 1e-3);
        assert!(state.creating_revolve.is_none());
    }

