    /// A fillet/chamfer trim must re-target the trimmed lines' LENGTH dimensions:
    /// with stale dims, the next full solve dragged the endpoints back and mangled
    /// the treated corner (the Quickstart bracket's bend collapsed one step later).
    ///
    /// #538: under the parametric operation model the source edge is instead **shadowed** and kept
    /// solving at its full length, so its length dimension is UNCHANGED (it references the virtual
    /// sharp corner, standard CAD). The visible trim lives on the op's generated output.
    #[test]
    fn chamfer_shadows_the_source_and_leaves_its_length_dimension_untouched() {
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        // Two lines meeting at (10, 0), each with a numeric length dim (like typed input).
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0));
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 10.0, 0.0, 10.0, 10.0));
        for (li, len) in [(lkey(0), "10"), (lkey(1), "10")] {
            state.doc.constraints.insert(crate::model::Constraint {
                sketch,
                kind: ConstraintKind::Distance {
                    target: DistanceTarget::LineLength(li),
                },
                expression: len.to_string(),
                dim_offset: None,
                name: None,
            });
        }
        state.doc.constraints.insert(crate::model::Constraint {
            sketch,
            kind: ConstraintKind::Coincident {
                a: ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
                    line: lkey(0),
                    end: LineEnd::End,
                }),
                b: ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
                    line: lkey(1),
                    end: LineEnd::Start,
                }),
            },
            expression: String::new(),
            dim_offset: None,
            name: None,
        });
        let result = state.apply(Action::CommitVertexTreatment {
            point: ConstraintPoint::LineEndpoint { line: lkey(0), end: LineEnd::End },
            kind: VertexTreatmentKind::Chamfer,
            amount: "3.0".to_string(),
        });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        // The source edge is shadowed and stays at its FULL length (virtual sharp corner intact).
        assert!(state.doc.lines[lkey(0)].shadow, "source line 0 becomes a shadow");
        assert!(
            (state.doc.lines[lkey(0)].x1 - 10.0).abs() < 1e-3,
            "source stays full length, got x1 = {}",
            state.doc.lines[lkey(0)].x1
        );
        // Its length dimension is unchanged — still the plain typed "10".
        let dim0 = state
            .doc
            .constraints
            .values()
            .find(|c| {
                matches!(
                        &c.kind,
                        ConstraintKind::Distance { target: DistanceTarget::LineLength(_) }
                    )
            })
            .expect("length dim");
        assert_eq!(dim0.expression, "10", "the source's length dim must be untouched");
        // A live op owns the treated corner; its output is the trimmed copy that lands at x = 7.
        assert_eq!(state.doc.sketch_vertex_treatment_ops.len(), 1);
        let op = &state.doc.sketch_vertex_treatment_ops.values().nth(0).unwrap();
        assert_eq!(op.line_targets, vec![lkey(0), lkey(1)]);
        assert_eq!(op.corners.len(), 1);
        assert_eq!(op.line_outputs.len(), 2);
        assert_eq!(op.bridge_outputs.len(), 1);
        let trimmed0 = &state.doc.lines[op.line_outputs[0]];
        assert!(!trimmed0.shadow, "the trimmed copy is visible geometry");
        assert!(
            (trimmed0.x1 - 7.0).abs() < 1e-3,
            "trimmed output ends at x = 7, got {}",
            trimmed0.x1
        );
        // A full recompute keeps the source full-length and re-derives the same trim.
        crate::parameters::recompute_document_geometry(&mut state.doc).unwrap();
        assert!((state.doc.lines[lkey(0)].x1 - 10.0).abs() < 1e-2, "source stays full after recompute");
        let op = &state.doc.sketch_vertex_treatment_ops.values().nth(0).unwrap();
        assert!((state.doc.lines[op.line_outputs[0]].x1 - 7.0).abs() < 1e-2);
    }

    /// #538 (parametric amount): a chamfer amount given as a parameter follows edits — changing the
    /// parameter and recomputing moves the trim (the bridge endpoints shift).
    #[test]
    fn chamfer_amount_as_a_parameter_follows_edits_on_recompute() {
        let mut state = AppState::default();
        let (sketch, point) = two_coincident_lines_at_a_right_angle(&mut state);
        state.apply(Action::AddParameter {
            name: "cham".to_string(),
            expression: "3".to_string(),
        });
        // Commit with the amount tied to the parameter by name (the real end-to-end flow): the
        // expression is stored on the corner verbatim, so it keeps following the parameter.
        let result = state.apply(Action::CommitVertexTreatment {
            point,
            kind: VertexTreatmentKind::Chamfer,
            amount: "cham".to_string(),
        });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        assert_eq!(
            state.doc.sketch_vertex_treatment_ops.values().nth(0).unwrap().corners[0].amount, "cham",
            "the parametric amount expression is stored verbatim on the corner"
        );
        let _ = sketch;

        crate::parameters::recompute_document_geometry(&mut state.doc).unwrap();
        let bridge_at = |s: &AppState| {
            let op = &s.doc.sketch_vertex_treatment_ops.values().nth(0).unwrap();
            let b = &s.doc.lines[op.bridge_outputs[0]];
            (b.x0, b.y0, b.x1, b.y1)
        };
        let before = bridge_at(&state);
        // Grow the parameter; the trim (and hence the bridge) must move.
        let param = state.doc.parameters.keys().next().expect("the parameter");
        state.apply(Action::CommitParameterExpression {
            index: param,
            expression: "6".to_string(),
        });
        crate::parameters::recompute_document_geometry(&mut state.doc).unwrap();
        let after = bridge_at(&state);
        let moved = (before.0 - after.0).abs()
            + (before.1 - after.1).abs()
            + (before.2 - after.2).abs()
            + (before.3 - after.3).abs();
        assert!(moved > 1.0, "changing the parameter must move the bridge, moved = {moved}");
    }

    /// Loft (SPEC §3.5): toggling two circle sections and committing creates a loft plus
    /// its body under one undo marker; undo removes both together.
    #[test]
    fn commit_loft_creates_body_and_undo_removes_both() {
        let mut state = AppState::default();
        let bottom = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
        state
            .doc
            .circles
            .insert(crate::model::Circle::from_local_center_radius(bottom, 0.0, 0.0, 5.0, 0.0));
        state.doc.construction_planes.insert(plane_from_definition(
            &definition_from_reference(
                &PlaneReference::Face {
                    origin: Vec3::ZERO,
                    normal: Vec3::Z,
                    label: "Ground".to_string(),
                },
                10.0,
                0.0,
            ),
            ConstructionPlaneParent::Root,
        ));
        let top = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(1)));
        state
            .doc
            .circles
            .insert(crate::model::Circle::from_local_center_radius(top, 0.0, 0.0, 2.0, 0.0));

        for (sketch, ci) in [(bottom, rkey(0)), (top, rkey(1))] {
            let result = state.apply(Action::ToggleLoftSection {
                section: crate::model::LoftSection {
                    sketch,
                    face: crate::model::ExtrudeFace::Circle(ci),
                },
            });
            assert!(matches!(result, ActionResult::Ok));
        }
        assert!(matches!(state.apply(Action::CommitLoft), ActionResult::Ok));
        assert_eq!(state.doc.lofts.len(), 1);
        let loft_key = state.doc.lofts.keys().next().expect("one loft");
        assert_eq!(state.doc.lofts[loft_key].sections.len(), 2);
        assert_eq!(
            state.doc.bodies.values().last().map(|b| b.source.clone()),
            Some(crate::model::BodySource::Loft(loft_key))
        );
        assert_eq!(state.doc.shape_order.last(), Some(&ShapeKind::Loft));
        assert!(state.creating_loft.is_none());
        assert!(crate::extrude::body_solid_mesh(&state.doc, state.doc.bodies.keys().last().unwrap()).is_some());

        state.apply(Action::UndoLast);
        assert!(state.doc.lofts.is_empty());
        assert!(state.doc.bodies.is_empty());
        assert!(!state.doc.shape_order.contains(&ShapeKind::Loft));
    }

