    /// #834: a material is created, handed to the selected bodies, renamed and recolored;
    /// a body with none keeps the default look.
    #[test]
    fn materials_are_assigned_named_and_recolored() {
        let mut state = two_box_state(false);
        // #925/#928: a document starts with the whole default palette, Unobtainium first.
        let seeded = state.doc.materials.len();
        let unobtainium = state.doc.default_material().expect("a seeded palette");
        assert_eq!(state.doc.materials[unobtainium].name, "Unobtainium");
        // A body carries no material of its own until one is picked; that reads as the
        // document's first material — Unobtainium (#924).
        assert_eq!(state.doc.bodies[bkey(0)].material, None);

        state.apply(Action::AddMaterial {
            name: Some("Brass".to_string()),
            color: Some([0x10, 0x20, 0x30]),
            bodies: vec![bkey(0)],
        });
        let brass = state.doc.bodies[bkey(0)].material.expect("Brass was handed to it");
        assert_eq!(state.doc.materials.len(), seeded + 1);
        assert_eq!(state.doc.materials[brass].name, "Brass");
        assert_eq!(state.doc.bodies[bkey(1)].material, None, "only the listed bodies get it");

        // A second material gets the next palette color and its own name by default.
        state.apply(Action::AddMaterial { name: None, color: None, bodies: vec![bkey(1)] });
        let second = state.doc.bodies[bkey(1)].material.expect("and this one to the other body");
        assert_ne!(state.doc.materials[second].color, state.doc.materials[brass].color);

        state.apply(Action::SetBodyMaterial { body: bkey(1), material: Some(brass) });
        assert_eq!(state.doc.bodies[bkey(1)].material, Some(brass));
        state.apply(Action::SetBodyMaterial { body: bkey(1), material: Some(unobtainium) });
        assert_eq!(
            state.doc.bodies[bkey(1)].material,
            Some(unobtainium),
            "back to Unobtainium"
        );
        state.apply(Action::SetBodyMaterial { body: bkey(1), material: None });
        assert_eq!(state.doc.bodies[bkey(1)].material, None, "and clearing it reads the same");

        state.apply(Action::SetMaterialName { material: brass, name: "  Bronze ".to_string() });
        assert_eq!(state.doc.materials[brass].name, "Bronze", "the name is trimmed");
        state.apply(Action::SetMaterialColor { material: brass, color: [1, 2, 3] });
        assert_eq!(state.doc.materials[brass].color, [1, 2, 3]);
    }

    /// Names are unique and non-empty, and only live materials can be assigned (#834).
    #[test]
    fn material_edits_are_validated() {
        let mut state = two_box_state(false);
        state.apply(Action::AddMaterial {
            name: Some("Steel".to_string()),
            color: None,
            bodies: vec![],
        });
        assert!(matches!(
            state.apply(Action::AddMaterial {
                name: Some("steel".to_string()),
                color: None,
                bodies: vec![],
            }),
            ActionResult::Err(_)
        ));
        let first = state.doc.default_material().expect("a seeded palette");
        assert!(matches!(
            state.apply(Action::SetMaterialName { material: first, name: "  ".to_string() }),
            ActionResult::Err(_)
        ));
        // A key to a material that was removed: absent, not whatever took the slot (#1055).
        let unknown = {
            let mut doc = state.doc.clone();
            let key = doc.materials.insert(crate::model::Material {
                name: "Gone".to_string(),
                color: [0, 0, 0],
            });
            doc.materials.remove(key);
            key
        };
        assert!(matches!(
            state.apply(Action::SetBodyMaterial { body: bkey(0), material: Some(unknown) }),
            ActionResult::Err(_)
        ));
        assert!(matches!(
            state.apply(Action::SetBodyMaterial { body: bkey(99), material: None }),
            ActionResult::Err(_)
        ));
        // Undo takes the added material back out, leaving the seeded palette.
        let seeded = crate::model::Material::DEFAULTS.len();
        state.apply(Action::UndoLast);
        assert_eq!(state.doc.materials.len(), seeded, "one undo removes the material");
    }

    /// #1218: any body can be turned into a shadow body (and back) so it no longer shows
    /// as a live solid and drops out of whole-document export.
    #[test]
    fn set_body_shadow_toggles_and_undoes() {
        let mut state = two_box_state(false);
        let a = bkey(0);
        let b = bkey(1);
        assert!(!state.doc.bodies[a].shadow);
        assert!(!state.doc.bodies[b].shadow);

        assert!(matches!(
            state.apply(Action::SetBodyShadow { body: a, shadow: true }),
            ActionResult::Ok
        ));
        assert!(state.doc.bodies[a].shadow, "body A is a shadow");
        assert!(!state.doc.bodies[b].shadow, "body B is untouched");

        // Whole-document mesh must omit the shadow body — two live boxes have more
        // triangles than one.
        let both = crate::extrude::document_solid_mesh(&state.doc);
        state.apply(Action::SetBodyShadow { body: a, shadow: false });
        let live_both = crate::extrude::document_solid_mesh(&state.doc);
        state.apply(Action::SetBodyShadow { body: a, shadow: true });
        let one_live = crate::extrude::document_solid_mesh(&state.doc);
        assert!(
            one_live.triangles.len() < live_both.triangles.len(),
            "shadowing a body shrinks the export mesh ({} vs {})",
            one_live.triangles.len(),
            live_both.triangles.len()
        );
        assert_eq!(
            both.triangles.len(),
            one_live.triangles.len(),
            "document_solid_mesh already skipped the shadow"
        );

        // Undo restores the live body.
        state.apply(Action::UndoLast);
        assert!(!state.doc.bodies[a].shadow, "undo restores the live body");

        assert!(matches!(
            state.apply(Action::SetBodyShadow { body: bkey(99), shadow: true }),
            ActionResult::Err(_)
        ));
    }

    /// #833: resizing a plane is one undoable edit.
