    /// #1055/#1060: a key must mean the same thing across an undo. Undo restores a whole
    /// `Document`, so the arena's free list comes back with it — but the argument is
    /// reasoning, so this is the evidence: delete a body, make another (which reuses the
    /// freed slot), then walk back and forward through history and check that every key
    /// captured along the way resolves to its own body or to nothing, never to a different
    /// one. With positional identity the recreated body would have answered to the deleted
    /// one's index.
    #[test]
    fn a_body_key_never_resolves_to_a_different_body_across_undo_and_redo() {
        let mut state = two_box_state(false);
        let first = state.doc.body_at(0).expect("two bodies");
        let second = state.doc.body_at(1).expect("two bodies");
        let name_of = |s: &AppState, k: crate::model::BodyKey| {
            s.doc.bodies.get(k).map(|b| format!("{:?}", b.source))
        };
        let first_source = name_of(&state, first).expect("body 0 is there");

        state.apply(Action::DeleteElement {
            element: crate::hierarchy::SceneElement::Body(first),
        });
        assert!(state.doc.bodies.get(first).is_none(), "deleting removes it");

        // A fresh body reuses the freed slot, and must not answer to the old key.
        let reused = state.doc.bodies.insert(crate::model::Body {
            source: crate::model::BodySource::Extrusion(xkey(99)),
            name: None,
            material: None,
            shadow: false,
        });
        assert_eq!(reused.index(), first.index(), "the slot was reused");
        assert!(state.doc.bodies.get(first).is_none(), "the stale key stays dead");

        // Back through history: the deleted body returns under its own key, and the
        // scratch body's key stops resolving because that document never had it.
        state.apply(Action::UndoLast);
        assert_eq!(
            name_of(&state, first).as_deref(),
            Some(first_source.as_str()),
            "undo brings the body back as itself"
        );
        assert!(name_of(&state, second).is_some(), "and its neighbour is untouched");
        assert_ne!(
            name_of(&state, reused),
            Some(format!("{:?}", crate::model::BodySource::Extrusion(xkey(99)))),
            "the scratch body's key does not resolve to it in the restored document"
        );

        // Forward again: the deletion is back, and `first` is absent rather than aliased.
        state.apply(Action::RedoLast);
        assert!(
            state.doc.bodies.get(first).is_none(),
            "redo re-applies the deletion; the key reads as gone, not as someone else"
        );
    }

    fn box_extrusion_state() -> AppState {
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        let rect_lines = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            0.0,
            0.0,
            10.0,
            10.0,
            [false; 4],
        );
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![ExtrudeFace::Polygon(rect_lines.to_vec())],
            distance: 5.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
        
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,

        });
        state
    }

    /// Two separate extruded box bodies side by side (overlapping when `overlap`).
    fn two_box_state(overlap: bool) -> AppState {
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        let a = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            0.0,
            0.0,
            10.0,
            10.0,
            [false; 4],
        );
        let x1 = if overlap { 5.0 } else { 20.0 };
        let b = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            x1,
            0.0,
            x1 + 10.0,
            10.0,
            [false; 4],
        );
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![ExtrudeFace::Polygon(a.to_vec())],
            distance: 5.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
        
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,

        });
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![ExtrudeFace::Polygon(b.to_vec())],
            distance: 5.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
        
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,

        });
        assert_eq!(state.doc.bodies.len(), 2);
        state
    }

    /// Combine tool: committing shadows the inputs, creates the operation element and its
    /// output bodies, and one undo restores everything.
    #[test]
    fn boolean_combine_creates_outputs_and_shadows_inputs() {
        let mut state = two_box_state(true);
        let result = state.apply(Action::CreateBooleanOperation {
            kind: crate::model::BooleanOpKind::Combine,
            a: vec![bkey(0), bkey(1)],
            b: Vec::new(),
            keep_b: false,
            solid_count: None,
        });
        assert!(matches!(result, ActionResult::Ok));
        assert_eq!(state.doc.boolean_ops.len(), 1);
        let op = &state.doc.boolean_ops.values().nth(0).unwrap();
        assert!(!op.outputs.is_empty());
        for &out in &op.outputs {
            assert!(matches!(
                state.doc.bodies[out].source,
                crate::model::BodySource::Boolean { op, .. } if op == bopkey(0)
            ));
            assert!(!state.doc.bodies[out].shadow);
        }
        assert!(state.doc.bodies.values().nth(0).unwrap().shadow, "input A should be a shadow body");
        assert!(state.doc.bodies.values().nth(1).unwrap().shadow, "input B should be a shadow body");

        state.apply(Action::UndoLast);
        assert!(state.doc.boolean_ops.is_empty());
        assert_eq!(state.doc.bodies.len(), 2);
        assert!(!state.doc.bodies.values().nth(0).unwrap().shadow);
        assert!(!state.doc.bodies.values().nth(1).unwrap().shadow);
    }

    /// Cut with keep leftovers leaves the B-side inputs as real bodies (the cutting shape).
    #[test]
    fn boolean_cut_keep_b_leaves_b_real() {
        let mut state = two_box_state(true);
        let result = state.apply(Action::CreateBooleanOperation {
            kind: crate::model::BooleanOpKind::Cut,
            a: vec![bkey(0)],
            b: vec![bkey(1)],
            keep_b: true,
            solid_count: None,
        });
        assert!(matches!(result, ActionResult::Ok));
        assert!(state.doc.bodies.values().nth(0).unwrap().shadow);
        assert!(!state.doc.bodies.values().nth(1).unwrap().shadow, "keep_b must leave B real");
        assert_eq!(
            state.doc.boolean_ops.values().nth(0).unwrap().outputs.len(),
            1,
            "cut leftovers are the original cutter, not extra result solids"
        );
    }

    fn live_boolean_volumes(state: &AppState) -> Vec<f32> {
        let mut vols: Vec<f32> = state
            .doc
            .bodies
            .iter()
            .filter(|(_, b)| !b.shadow)
            .filter_map(|(k, _)| {
                crate::extrude::body_solid_mesh(&state.doc, k)
                    .map(|m| crate::extrude::mesh_signed_volume(&m).abs())
            })
            .collect();
        vols.sort_by(|a, b| a.partial_cmp(b).unwrap());
        vols
    }

    /// #1581: with leftovers kept, Intersect and Difference both split A and B into the
    /// three parts A−B, A∩B, and B−A — so they produce the same live solids.
    #[test]
    fn boolean_keep_leftovers_makes_intersect_and_difference_identical() {
        let volumes = |kind| {
            let mut state = two_box_state(true);
            let result = state.apply(Action::CreateBooleanOperation {
                kind,
                a: vec![bkey(0)],
                b: vec![bkey(1)],
                keep_b: true,
                solid_count: None,
            });
            assert!(matches!(result, ActionResult::Ok), "{kind:?}: {result:?}");
            assert!(
                state.doc.bodies.values().nth(0).unwrap().shadow,
                "{kind:?}: A is consumed"
            );
            assert!(
                state.doc.bodies.values().nth(1).unwrap().shadow,
                "{kind:?}: leftover pieces are new bodies, so B is consumed"
            );
            live_boolean_volumes(&state)
        };
        let intersect = volumes(crate::model::BooleanOpKind::Intersect);
        let difference = volumes(crate::model::BooleanOpKind::Difference);
        assert_eq!(intersect.len(), 3, "three-part split, got {intersect:?}");
        assert_eq!(
            intersect, difference,
            "intersect+keep and difference+keep are the same split"
        );
        assert!(
            intersect.iter().all(|v| *v > 1.0),
            "each leftover part has volume, got {intersect:?}"
        );
    }

    /// Validation: combine needs two inputs; consumed (shadow) inputs are rejected; the
    /// two-sided ops need a B side.
    #[test]
    fn boolean_validation_rejects_bad_inputs() {
        let mut state = two_box_state(true);
        assert!(matches!(
            state.apply(Action::CreateBooleanOperation {
                kind: crate::model::BooleanOpKind::Combine,
                a: vec![bkey(0)],
                b: Vec::new(),
                keep_b: false,
                solid_count: None,
            }),
            ActionResult::Err(_)
        ));
        assert!(matches!(
            state.apply(Action::CreateBooleanOperation {
                kind: crate::model::BooleanOpKind::Cut,
                a: vec![bkey(0)],
                b: Vec::new(),
                keep_b: false,
                solid_count: None,
            }),
            ActionResult::Err(_)
        ));
        // Consume both, then try to reuse a shadow input.
        state.apply(Action::CreateBooleanOperation {
            kind: crate::model::BooleanOpKind::Combine,
            a: vec![bkey(0), bkey(1)],
            b: Vec::new(),
            keep_b: false,
            solid_count: None,
        });
        let out = state.doc.boolean_ops.values().nth(0).unwrap().outputs[0];
        assert!(matches!(
            state.apply(Action::CreateBooleanOperation {
                kind: crate::model::BooleanOpKind::Cut,
                a: vec![out],
                b: vec![bkey(0)],
                keep_b: false,
                solid_count: None,
            }),
            ActionResult::Err(_)
        ));
    }

