    /// Move tool: committing shadows the inputs, creates the operation + one moved output
    /// per input, geometry lands offset, and one undo restores everything.
    #[test]
    fn move_commit_creates_outputs_and_shadows_inputs() {
        let mut state = two_box_state(false);
        let result = state.apply(Action::CreateMoveOperation {
            keep_inputs: false,
            translate_mode: crate::model::MoveTranslateMode::Free,
            start_point_a: None,
            end_point_a: None,
            start_point_b: None,
            end_point_b: None,
            start_point_c: None,
            end_point_c: None,
            targets: vec![bkey(0), bkey(1)],
            plane_targets: vec![],
            image_targets: vec![],
            instance_targets: Vec::new(),
            tx: "25".to_string(),
            ty: String::new(),
            tz: String::new(),
            rx: String::new(),
            ry: String::new(),
            rz: String::new(),
            face_flip: false,
            face_spin: String::new(),
            roll_angle: String::new(),
            face_offset: String::new(),
        });
        assert!(matches!(result, ActionResult::Ok));
        assert_eq!(state.doc.move_ops.len(), 1);
        let op = state.doc.move_ops.values().nth(0).unwrap().clone();
        assert_eq!(op.outputs.len(), 2);
        assert!(state.doc.bodies.values().nth(0).unwrap().shadow);
        assert!(state.doc.bodies.values().nth(1).unwrap().shadow);
        // The moved copy sits 25mm along +X of its source.
        let src = crate::extrude::body_solid_mesh(&state.doc, bkey(0)).unwrap();
        let out = crate::extrude::body_solid_mesh(&state.doc, op.outputs[0]).unwrap();
        let min_x = |m: &crate::extrude::SolidMesh| {
            m.triangles
                .iter()
                .flat_map(|t| t.iter())
                .map(|p| p.x)
                .fold(f32::INFINITY, f32::min)
        };
        assert!((min_x(&out) - min_x(&src) - 25.0).abs() < 1e-3);

        state.apply(Action::UndoLast);
        assert!(state.doc.move_ops.is_empty());
        assert_eq!(state.doc.bodies.len(), 2);
        assert!(!state.doc.bodies.values().nth(0).unwrap().shadow);
    }

