    /// Repeat tool: count × gap produces N-1 output bodies at increasing offsets; undo
    /// removes everything; the original stays real (never shadowed).
    #[test]
    fn repeat_count_gap_creates_offset_instances() {
        let mut state = two_box_state(false);
        let result = state.apply(Action::CreateRepeatOperation {
            targets: vec![bkey(0)],
            plane_targets: Vec::new(),
            extrusion_targets: Vec::new(),
            sketch_targets: Vec::new(),
            axis: crate::model::RevolveAxis::X,
            path_circle: None,
            around_axis: false,
            flip: false,
            mode: crate::model::RepeatMode::CountGap,
            count: "3".to_string(),
            spacing: "5".to_string(),
            length: String::new(),
            length_target: None,
        });
        assert!(matches!(result, ActionResult::Ok));
        let op = state.doc.repeat_ops.values().nth(0).unwrap().clone();
        assert_eq!(op.outputs.len(), 2, "3 instances = original + 2 outputs");
        assert!(!state.doc.bodies.values().nth(0).unwrap().shadow, "repeat originals stay real");
        // Box extent along X is 10, so step = 15: instance offsets 15 and 30.
        let min_x = |bi: crate::model::BodyKey| {
            crate::extrude::body_solid_mesh(&state.doc, bi)
                .unwrap()
                .triangles
                .iter()
                .flat_map(|t| t.iter())
                .map(|p| p.x)
                .fold(f32::INFINITY, f32::min)
        };
        let base = min_x(bkey(0));
        assert!((min_x(op.outputs[0]) - base - 15.0).abs() < 1e-3);
        assert!((min_x(op.outputs[1]) - base - 30.0).abs() < 1e-3);

        state.apply(Action::UndoLast);
        assert!(state.doc.repeat_ops.is_empty());
        assert_eq!(state.doc.bodies.len(), 2);
    }

    /// #1396: a repeat's copies carry incrementing numbers off the source body's name. A base
    /// named "Jim" whose copies are drawn from shows up as Jim1, Jim2, …; a base whose name
    /// already ends in a number ("Jim1") uses the "-N" form: Jim1-1, Jim1-2, ….
    #[test]
    fn repeat_copies_number_off_the_base_body_name() {
        let mut state = two_box_state(false);
        set_element_name(&mut state.doc, SceneElement::Body(bkey(0)), "Jim".into()).unwrap();
        state.apply(Action::CreateRepeatOperation {
            targets: vec![bkey(0)],
            plane_targets: Vec::new(),
            extrusion_targets: Vec::new(),
            sketch_targets: Vec::new(),
            axis: crate::model::RevolveAxis::X,
            path_circle: None,
            around_axis: false,
            flip: false,
            mode: crate::model::RepeatMode::CountGap,
            count: "3".to_string(),
            spacing: "5".to_string(),
            length: String::new(),
            length_target: None,
        });
        let op = state.doc.repeat_ops.values().next().unwrap().clone();
        assert_eq!(op.outputs.len(), 2, "3 instances = original + 2 outputs");
        let names: Vec<_> = op
            .outputs
            .iter()
            .map(|b| state.doc.bodies[*b].name.clone())
            .collect();
        assert_eq!(
            names,
            vec![Some("Jim1".to_string()), Some("Jim2".to_string())]
        );
    }

