    /// #189: selecting a point and the origin, then applying Coincident, pins the point to the
    /// origin — the constraint-tool flow the user asked for (not just snapping).
    #[test]
    fn selecting_a_point_and_the_origin_constrains_coincident() {
        use crate::geometric_constraints::GeometricConstraintType;
        use crate::model::{ConstraintPoint, LineEnd};

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state
            .doc
            .lines
            .insert(Line::from_local_endpoints(sketch, 5.0, 5.0, 12.0, 8.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.refresh_document_health();

        state.apply(Action::ClickSceneElement {
            element: SceneElement::Point(ConstraintPoint::LineEndpoint { line: lkey(0), end: LineEnd::Start }),
            additive: false,
        });
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Origin,
            additive: true,
        });
        let result = state.apply(Action::AddGeometricConstraint(GeometricConstraintType::Coincident));
        assert!(matches!(result, ActionResult::Ok), "{}", state.status);
        assert!(
            state.doc.lines[lkey(0)].x0.abs() < 1e-3 && state.doc.lines[lkey(0)].y0.abs() < 1e-3,
            "start should be pinned to the origin, got ({}, {})",
            state.doc.lines[lkey(0)].x0,
            state.doc.lines[lkey(0)].y0
        );
    }

    /// #198: with a circle drawn on a body face, selecting the circle's center and one of the
    /// face's own edges resolves to a point-to-line distance dimension — the thing the user
    /// couldn't do. Exercises the selection→constraint logic end to end (the viewport pick and
    /// this share `dimension_edit_from_selection`).
    #[test]
    fn circle_center_and_face_edge_resolve_to_a_point_line_distance() {
        use crate::model::{ConstraintLine, ConstraintPoint, DimensionTarget, DistanceTarget};

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        let rect = crate::construction::add_line_rectangle(&mut state.doc, sketch, 0.0, 0.0, 20.0, 20.0, [false; 4]);
        let profile = ExtrudeFace::Polygon(rect.to_vec());
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![profile.clone()],
            distance: 10.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
        
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,

        });
        let cap = FaceId::ExtrudeCap { extrusion: xkey(0), profile, top: true };
        state.apply(Action::BeginSketch { face: cap.clone(), viewport: None });
        let cap_sketch = state.sketch_session.unwrap().sketch;
        state
            .doc
            .circles
            .insert(crate::model::Circle::from_local_center_radius(cap_sketch, 5.0, 5.0, 3.0, 0.0));
        let ci = state.doc.circles.keys().last().unwrap();
        state.doc.shape_order.push(ShapeKind::Circle);
        state.refresh_document_health();

        state.apply(Action::ClickSceneElement {
            element: SceneElement::Point(ConstraintPoint::CircleCenter(ci)),
            additive: false,
        });
        state.apply(Action::ClickSceneElement {
            element: SceneElement::FaceEdge(ConstraintLine::FaceEdge { face: cap, index: 0 }),
            additive: true,
        });

        let target = crate::constraints::dimension_edit_from_selection(
            &state.doc,
            cap_sketch,
            &state.scene_selection,
        );
        assert!(
            matches!(
                target,
                Some(DimensionTarget::Distance(DistanceTarget::PointLineDistance { .. }))
            ),
            "circle center + face edge should dimension as a point-line distance, got {target:?}"
        );

        // And the viewport pick actually resolves the circle center: aim a top-down camera at
        // the cap, project the center, and click there.
        let center_world = crate::face::circle_world_center(&state.doc, &state.doc.circles[ci])
            .expect("circle center world position");
        let mut cam = crate::camera::Camera::default();
        let (yaw, pitch) = crate::camera::StandardView::Top.yaw_pitch();
        cam.yaw = yaw;
        cam.pitch = pitch;
        cam.target = center_world;
        cam.distance = 120.0;
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0));
        let vp = cam.view_proj(viewport);
        let project = |w: glam::Vec3| cam.project(w, viewport, &vp);
        let center_px = project(center_world).expect("center projects into view");
        let picked = crate::construction::nearest_sketch_point_in_sketch(
            center_px,
            &project,
            &state.doc,
            cap_sketch,
        );
        assert!(
            matches!(
                picked,
                Some((crate::model::ConstraintPoint::CircleCenter(c), _)) if c == ci
            ),
            "clicking the circle's center on a body-face sketch should pick it, got {picked:?}"
        );

        // #199: the face's own edges are pickable in the same sketch — click an edge midpoint.
        let loop_ = crate::extrude::face_boundary_loop_world(
            &state.doc,
            &FaceId::ExtrudeCap { extrusion: xkey(0), profile: ExtrudeFace::Polygon(rect.to_vec()), top: true },
        )
        .expect("cap boundary loop");
        let edge_mid = (loop_[0] + loop_[1]) * 0.5;
        let edge_px = project(edge_mid).expect("edge midpoint projects into view");
        let edge_pick =
            crate::construction::nearest_sketch_line_in_sketch(edge_px, &project, &state.doc, cap_sketch);
        assert!(
            matches!(
                edge_pick,
                Some((crate::model::ConstraintLine::FaceEdge { index: 0, .. }, _))
            ),
            "clicking a face edge on a body-face sketch should pick it, got {edge_pick:?}"
        );
    }

    /// #1436: a sketch on the cap of an extruded circle, with a smaller circle drawn on
    /// it — selecting the origin (the extruded circle's centre) and the little circle
    /// must resolve to a point-to-point distance so the hole can be located from the
    /// centre. Shares `dimension_edit_from_selection` with the viewport pick path.
    #[test]
    fn origin_and_circle_on_extruded_circle_cap_resolve_to_a_distance() {
        use crate::model::{DimensionTarget, DistanceTarget};

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state
            .doc
            .circles
            .insert(crate::model::Circle::from_local_center_radius(sketch, 0.0, 0.0, 20.0, 0.0));
        state.doc.shape_order.push(crate::model::ShapeKind::Circle);
        let profile = ExtrudeFace::Circle(rkey(0));
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![profile.clone()],
            distance: 10.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,
        });
        let cap = FaceId::ExtrudeCap {
            extrusion: xkey(0),
            profile,
            top: true,
        };
        state.apply(Action::BeginSketch {
            face: cap,
            viewport: None,
        });
        let cap_sketch = state.sketch_session.unwrap().sketch;
        state.doc.circles.insert(
            crate::model::Circle::from_local_center_radius(cap_sketch, 8.0, 0.0, 3.0, 0.0),
        );
        let ci = state.doc.circles.keys().last().unwrap();
        state.doc.shape_order.push(crate::model::ShapeKind::Circle);
        state.refresh_document_health();

        state.apply(Action::ClickSceneElement {
            element: SceneElement::Origin,
            additive: false,
        });
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Circle(ci),
            additive: true,
        });

        let target = crate::constraints::dimension_edit_from_selection(
            &state.doc,
            cap_sketch,
            &state.scene_selection,
        );
        assert!(
            matches!(
                target,
                Some(DimensionTarget::Distance(DistanceTarget::PointPointDistance { .. }))
            ),
            "origin + little circle on a circular cap should dimension as a centre distance, got {target:?}"
        );

        // The origin (cap centre) is pickable under the Dimension tool too: aim a
        // top-down camera at the cap and click the centre.
        let frame = crate::face::sketch_geometry_frame(&state.doc, cap_sketch)
            .expect("cap sketch frame");
        let mut cam = crate::camera::Camera::default();
        let (yaw, pitch) = crate::camera::StandardView::Top.yaw_pitch();
        cam.yaw = yaw;
        cam.pitch = pitch;
        cam.target = frame.origin;
        cam.distance = 120.0;
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0));
        let vp = cam.view_proj(viewport);
        let project = |w: glam::Vec3| cam.project(w, viewport, &vp);
        let origin_px = project(frame.origin).expect("origin projects into view");
        let picked = crate::construction::nearest_sketch_point_in_sketch(
            origin_px,
            &project,
            &state.doc,
            cap_sketch,
        );
        // A real vertex at the origin still wins; when the centre is empty the origin
        // itself must be the pick (see handle_dimension_point_pick).
        assert!(
            picked.is_none(),
            "the circular cap's centre is the origin, not a sketch vertex, got {picked:?}"
        );
    }

    /// #201: committing a repeat whose count is typed as `name = expr` defines the parameter
    /// and stores the bare name, so the repeat stays parameter-driven.
    #[test]
    fn repeat_input_defines_inline_parameter() {
        let mut state = two_box_state(false);
        state.apply(Action::SetTool(Tool::Repeat));
        {
            let cr = state.creating_repeat.as_mut().unwrap();
            cr.targets = vec![bkey(0)];
            cr.axis = Some(crate::model::RevolveAxis::X);
            cr.count = "n = 4".to_string();
            cr.spacing = "10".to_string();
        }
        assert!(matches!(state.apply(Action::CommitRepeat), ActionResult::Ok), "{}", state.status);
        assert!(state.doc.parameters.values().any(|p| p.name == "n"));
        assert_eq!(state.doc.repeat_ops.values().nth(0).unwrap().count, "n", "the stored count should be the bare name");
        assert_eq!(state.doc.repeat_ops.values().nth(0).unwrap().outputs.len(), 3, "n = 4 → 3 extra instances");
    }

    /// #439: activating the Repeat tool seeds its targets from the selected body, the
    /// axis starts unset, and committing without an axis is refused.
    #[test]
    fn repeat_tool_seeds_selection_and_requires_axis() {
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        state.apply(Action::ClickSceneElement {
            element: crate::hierarchy::SceneElement::Body(bkey(0)),
            additive: false,
        });
        state.apply(Action::SetTool(Tool::Repeat));
        let cr = state.creating_repeat.as_ref().unwrap();
        assert_eq!(cr.targets, vec![bkey(0)], "selected body seeds the repeat targets");
        assert_eq!(cr.axis, None, "the axis starts unset");
        {
            let cr = state.creating_repeat.as_mut().unwrap();
            cr.count = "3".to_string();
            cr.spacing = "10".to_string();
        }
        assert!(
            matches!(state.apply(Action::CommitRepeat), ActionResult::Err(_)),
            "commit without an axis is refused"
        );
        state.creating_repeat.as_mut().unwrap().axis = Some(crate::model::RevolveAxis::X);
        assert!(
            matches!(state.apply(Action::CommitRepeat), ActionResult::Ok),
            "{}",
            state.status
        );
    }

    /// #201: a move offset typed as `name = expr` defines the parameter and stays parametric.
