    /// Adds an XY-parallel construction plane at `z` and returns it as a planar slice cutter.
    fn add_offset_xy_plane(state: &mut AppState, z: f32) -> crate::model::SliceCutter {
        let plane = plane_from_definition(
            &definition_from_reference(
                &PlaneReference::Face {
                    origin: Vec3::ZERO,
                    normal: Vec3::Z,
                    label: "Ground".to_string(),
                },
                z,
                0.0,
            ),
            ConstructionPlaneParent::Root,
        );
        state.doc.construction_planes.insert(plane);
        crate::model::SliceCutter::Face(FaceId::ConstructionPlane(
            state.doc.construction_planes.keys().last().unwrap(),
        ))
    }

    /// #1154: Slice 3D auto-arms Cutters after the first target lands; further targets keep
    /// focus on Targets so multi-body slices don't bounce away from the picker you're filling.
    #[test]
    fn slice_first_target_arms_cutters_further_targets_keep_targets() {
        use crate::hierarchy::SceneElement;
        let mut state = two_box_state(false);
        state.apply(Action::SetTool(Tool::Slice));
        assert!(
            !state.creating_slice.as_ref().unwrap().picking_cutter,
            "Targets is armed first"
        );

        // First target: focus walks to Cutters.
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SliceTargets,
            &SceneElement::Body(bkey(0)),
        ));
        let cs = state.creating_slice.as_ref().unwrap();
        assert_eq!(cs.targets, vec![bkey(0)]);
        assert!(
            cs.picking_cutter,
            "after the first target, Cutters should take focus"
        );

        // User re-arms Targets to add another body.
        focus_tool_picker(&mut state, crate::context::PickerTarget::SliceTargets);
        assert!(!state.creating_slice.as_ref().unwrap().picking_cutter);
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SliceTargets,
            &SceneElement::Body(bkey(1)),
        ));
        let cs = state.creating_slice.as_ref().unwrap();
        assert_eq!(cs.targets, vec![bkey(0), bkey(1)]);
        assert!(
            !cs.picking_cutter,
            "a second target must leave focus on Targets"
        );

        // Toggle the first body off then back on while Targets already holds another:
        // still not "the first" target (set was non-empty), so stay on Targets.
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SliceTargets,
            &SceneElement::Body(bkey(0)),
        ));
        assert_eq!(state.creating_slice.as_ref().unwrap().targets, vec![bkey(1)]);
        assert!(!state.creating_slice.as_ref().unwrap().picking_cutter);
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SliceTargets,
            &SceneElement::Body(bkey(0)),
        ));
        assert_eq!(
            state.creating_slice.as_ref().unwrap().targets,
            vec![bkey(1), bkey(0)]
        );
        assert!(
            !state.creating_slice.as_ref().unwrap().picking_cutter,
            "re-adding while another target remains is not the first pick"
        );

        // Clear and pick one again: once more the first target, so Cutters arms.
        state.creating_slice.as_mut().unwrap().targets.clear();
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SliceTargets,
            &SceneElement::Body(bkey(0)),
        ));
        assert!(
            state.creating_slice.as_ref().unwrap().picking_cutter,
            "an empty Targets set + one pick is again the first target"
        );
    }

    /// #1567: Cut/Intersect/Difference auto-arm Side B after the first Side A pick; further
    /// Side A picks (user re-armed Side A) keep Side A so multi-body operands don't bounce.
    #[test]
    fn combine_first_side_a_pick_arms_side_b_further_picks_keep_side_a() {
        use crate::hierarchy::SceneElement;
        for mode in ["cut", "intersect", "difference"] {
            let mut state = two_box_state(false);
            state.apply(Action::SetTool(Tool::Combine));
            set_tool_mode(&mut state, mode).unwrap();
            assert!(
                !state.creating_boolean.as_ref().unwrap().picking_b,
                "{mode}: Side A is armed first"
            );

            assert!(apply_pick(
                &mut state,
                crate::context::PickerTarget::CombineA,
                &SceneElement::Body(bkey(0)),
            ));
            let cb = state.creating_boolean.as_ref().unwrap();
            assert_eq!(cb.a, vec![bkey(0)]);
            assert!(
                cb.picking_b,
                "{mode}: first Side A pick should arm Side B"
            );
            assert_eq!(
                state.picker_focus,
                Some(crate::context::PickerTarget::CombineB),
                "{mode}: Side B picker should take focus"
            );

            focus_tool_picker(&mut state, crate::context::PickerTarget::CombineA);
            assert!(!state.creating_boolean.as_ref().unwrap().picking_b);
            assert!(apply_pick(
                &mut state,
                crate::context::PickerTarget::CombineA,
                &SceneElement::Body(bkey(1)),
            ));
            let cb = state.creating_boolean.as_ref().unwrap();
            assert_eq!(cb.a, vec![bkey(0), bkey(1)]);
            assert!(
                !cb.picking_b,
                "{mode}: a second Side A pick must leave focus on Side A"
            );
            assert_eq!(
                state.picker_focus,
                Some(crate::context::PickerTarget::CombineA),
                "{mode}: Side A stays armed after a further pick"
            );

            // Toggle the first body off then back on while Side A already holds another:
            // still not "the first" pick, so stay on Side A.
            assert!(apply_pick(
                &mut state,
                crate::context::PickerTarget::CombineA,
                &SceneElement::Body(bkey(0)),
            ));
            assert_eq!(state.creating_boolean.as_ref().unwrap().a, vec![bkey(1)]);
            assert!(!state.creating_boolean.as_ref().unwrap().picking_b);
            assert!(apply_pick(
                &mut state,
                crate::context::PickerTarget::CombineA,
                &SceneElement::Body(bkey(0)),
            ));
            assert_eq!(
                state.creating_boolean.as_ref().unwrap().a,
                vec![bkey(1), bkey(0)]
            );
            assert!(
                !state.creating_boolean.as_ref().unwrap().picking_b,
                "{mode}: re-adding while another A body remains is not the first pick"
            );
        }

        // Combine (union) has no Side B — the first pick stays on Bodies/Side A.
        let mut state = two_box_state(false);
        state.apply(Action::SetTool(Tool::Combine));
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::CombineA,
            &SceneElement::Body(bkey(0)),
        ));
        let cb = state.creating_boolean.as_ref().unwrap();
        assert_eq!(cb.a, vec![bkey(0)]);
        assert!(
            !cb.picking_b,
            "union mode has no Side B to arm"
        );
        assert_ne!(
            state.picker_focus,
            Some(crate::context::PickerTarget::CombineB),
            "union mode must not jump to a Side B picker that is not shown"
        );
    }

    /// Slice: a plane through the middle of a box splits it into two fragment bodies, the
    /// input becomes a shadow body, and one undo restores everything.
    #[test]
    fn slice_splits_a_box_into_two_fragments() {
        let mut state = two_box_state(false);
        // Box 0 spans z 0..5; a plane at z=2.5 halves it.
        let cutter = add_offset_xy_plane(&mut state, 2.5);
        let bodies_before = state.doc.bodies.len();
        let result = state.apply(Action::CreateSliceOperation {
            targets: vec![bkey(0)],
            cutters: vec![cutter],
            extend_infinite: true,
        });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        assert_eq!(state.doc.slice_ops.len(), 1);
        let op = &state.doc.slice_ops.values().nth(0).unwrap();
        assert_eq!(op.outputs.len(), 2, "a mid-plane cut yields two fragments");
        for &out in &op.outputs {
            assert!(matches!(
                state.doc.bodies[out].source,
                crate::model::BodySource::Sliced { op, .. } if op == slckey(0)
            ));
            assert!(!state.doc.bodies[out].shadow);
            assert!(
                crate::extrude::body_solid_mesh(&state.doc, out).is_some(),
                "fragment {out:?} should have a kernel mesh"
            );
        }
        assert!(state.doc.bodies.values().nth(0).unwrap().shadow, "the sliced input becomes a shadow body");
        assert_eq!(state.doc.bodies.len(), bodies_before + 2);

        state.apply(Action::UndoLast);
        assert!(state.doc.slice_ops.is_empty());
        assert_eq!(state.doc.bodies.len(), bodies_before);
        assert!(!state.doc.bodies.values().nth(0).unwrap().shadow, "undo restores the input body");
    }

    /// A cutter that misses the body leaves it whole (one fragment).
    #[test]
    fn slice_with_a_missing_cutter_keeps_the_body_whole() {
        let mut state = two_box_state(false);
        // Box 0 spans z 0..5; a plane at z=20 is entirely above it.
        let cutter = add_offset_xy_plane(&mut state, 20.0);
        state.apply(Action::CreateSliceOperation {
            targets: vec![bkey(0)],
            cutters: vec![cutter],
            extend_infinite: true,
        });
        assert_eq!(state.doc.slice_ops.values().nth(0).unwrap().outputs.len(), 1);
    }

    /// Editing a slice re-points its cutters and resizes the fragment list.
    #[test]
    fn slice_edit_resizes_outputs() {
        let mut state = two_box_state(false);
        let miss = add_offset_xy_plane(&mut state, 20.0);
        let hit = add_offset_xy_plane(&mut state, 2.5);
        state.apply(Action::CreateSliceOperation {
            targets: vec![bkey(0)],
            cutters: vec![miss],
            extend_infinite: true,
        });
        assert_eq!(state.doc.slice_ops.values().nth(0).unwrap().outputs.len(), 1);
        let result = state.apply(Action::EditSliceOperation {
            op: slckey(0),
            targets: vec![bkey(0)],
            cutters: vec![hit],
            extend_infinite: true,
        });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        assert_eq!(
            state.doc.slice_ops.values().nth(0).unwrap().outputs.len(),
            2,
            "the mid-plane cutter now yields two fragments"
        );
        assert!(state.doc.bodies.values().nth(0).unwrap().shadow);
    }

    /// Slice rejects an empty cutter set and a shadow input.
    #[test]
    fn slice_validation_rejects_no_cutters_and_shadow_inputs() {
        let mut state = two_box_state(false);
        let no_cutters = state.apply(Action::CreateSliceOperation {
            targets: vec![bkey(0)],
            cutters: Vec::new(),
            extend_infinite: true,
        });
        assert!(matches!(no_cutters, ActionResult::Err(_)));
        // Shadow body 0 via a move op, then it can't be sliced.
        state.doc.bodies.values_mut().nth(0).unwrap().shadow = true;
        let cutter = add_offset_xy_plane(&mut state, 2.5);
        let shadowed = state.apply(Action::CreateSliceOperation {
            targets: vec![bkey(0)],
            cutters: vec![cutter],
            extend_infinite: true,
        });
        assert!(matches!(shadowed, ActionResult::Err(_)));
    }

    /// #1156: shell a box with its top face open — input shadows, one hollow output, undoable.
    #[test]
    fn shell_hollows_a_box_and_shadows_the_input() {
        use crate::model::shell_op_key_for_slot as shkey;
        let mut state = two_box_state(false);
        // Box 0 is a 10×10×5 extrusion (z 0..5). Open the top cap.
        let ext = state.doc.extrusions.keys().next().unwrap();
        let profile = state.doc.extrusions[ext].faces[0].clone();
        let top = FaceId::ExtrudeCap {
            extrusion: ext,
            profile,
            top: true,
        };
        let bodies_before = state.doc.bodies.len();
        let result = state.apply(Action::CreateShellOperation {
            targets: vec![bkey(0)],
            open_faces: vec![top],
            thickness: "1".to_string(),
        });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        assert_eq!(state.doc.shell_ops.len(), 1);
        let op = state.doc.shell_ops.values().nth(0).unwrap();
        assert_eq!(op.outputs.len(), 1);
        let out = op.outputs[0];
        assert!(matches!(
            state.doc.bodies[out].source,
            crate::model::BodySource::Shelled { op, .. } if op == shkey(0)
        ));
        assert!(!state.doc.bodies[out].shadow);
        assert!(state.doc.bodies[bkey(0)].shadow, "input becomes a shadow body");
        assert!(
            crate::extrude::body_solid_mesh(&state.doc, out).is_some(),
            "shelled output should have a kernel mesh"
        );
        // Hollow volume is less than the solid 10×10×5 = 500.
        if let Some(shape) = crate::extrude::occt_body_shape(&state.doc, out) {
            let v = shape.volume().unwrap_or(0.0);
            assert!(v > 0.0 && v < 500.0, "shelled volume {v} should be under 500");
        }
        assert_eq!(state.doc.bodies.len(), bodies_before + 1);

        state.apply(Action::UndoLast);
        assert!(state.doc.shell_ops.is_empty());
        assert_eq!(state.doc.bodies.len(), bodies_before);
        assert!(!state.doc.bodies[bkey(0)].shadow);
    }

