    /// #1170/#1171: thickness typed as `name=value` (with or without a unit) defines a
    /// parameter and shells with that value; the stored thickness is the bare name so it
    /// stays parametric — same contract as Extrude/Move/Repeat ValueInputs.
    #[test]
    fn shell_thickness_input_defines_inline_parameter() {
        let mut state = two_box_state(false);
        let result = state.apply(Action::CreateShellOperation {
            targets: vec![bkey(0)],
            open_faces: Vec::new(),
            thickness: "foo=12".to_string(),
        });
        assert!(
            matches!(result, ActionResult::Ok),
            "foo=12 refused: {result:?} status={}",
            state.status
        );
        assert!(
            state.doc.parameters.values().any(|p| p.name == "foo" && p.expression == "12"),
            "should define foo=12, got {:?}",
            state
                .doc
                .parameters
                .values()
                .map(|p| (&p.name, &p.expression))
                .collect::<Vec<_>>()
        );
        assert_eq!(
            state.doc.shell_ops.values().nth(0).unwrap().thickness,
            "foo",
            "stored thickness should be the bare parameter name"
        );

        // With a unit suffix (#1170).
        let mut state = two_box_state(false);
        let result = state.apply(Action::CreateShellOperation {
            targets: vec![bkey(1)],
            open_faces: Vec::new(),
            thickness: "bar=2mm".to_string(),
        });
        assert!(
            matches!(result, ActionResult::Ok),
            "bar=2mm refused: {result:?} status={}",
            state.status
        );
        assert!(
            state
                .doc
                .parameters
                .values()
                .any(|p| p.name == "bar" && p.expression == "2mm"),
            "should define bar=2mm"
        );
        assert_eq!(state.doc.shell_ops.values().nth(0).unwrap().thickness, "bar");

        // UI commit path: typed thickness field → CommitShell.
        let mut state = two_box_state(false);
        state.apply(Action::SetTool(Tool::Shell));
        {
            let cs = state.creating_shell.as_mut().unwrap();
            cs.targets = vec![bkey(0)];
            cs.thickness_text = "wall=1.5mm".to_string();
            cs.user_edited = true;
        }
        assert!(
            matches!(state.apply(Action::CommitShell), ActionResult::Ok),
            "CommitShell wall=1.5mm refused: {}",
            state.status
        );
        assert!(
            state
                .doc
                .parameters
                .values()
                .any(|p| p.name == "wall" && p.expression == "1.5mm"),
            "CommitShell should define wall=1.5mm"
        );
        assert_eq!(state.doc.shell_ops.values().nth(0).unwrap().thickness, "wall");
    }

    /// #1164: the Shell tool exposes a thickness push/pull gizmo once a body is targeted;
    /// `set_gizmo("shell", …)` drives the live wall thickness.
    #[test]
    fn gizmos_expose_and_drive_the_shell_thickness() {
        let mut state = two_box_state(false);
        state.apply(Action::SetTool(Tool::Shell));
        // No gizmo until a body is in the target set.
        assert!(
            available_gizmos(&state)
                .iter()
                .all(|g| g.name != "shell"),
            "shell gizmo should wait for a target body"
        );
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::ShellTargets,
            &crate::hierarchy::SceneElement::Body(bkey(0)),
        ));
        let gizmos = available_gizmos(&state);
        let shell = gizmos
            .iter()
            .find(|g| g.name == "shell")
            .expect("shell thickness gizmo after a body pick");
        assert_eq!(shell.kind, "push_pull");
        assert_eq!(
            gizmo_value(&state, "shell"),
            Some(state.creating_shell.as_ref().unwrap().thickness_live)
        );

        assert!(set_gizmo(&mut state, "shell", 3.5));
        let cs = state.creating_shell.as_ref().unwrap();
        assert!((cs.thickness_live - 3.5).abs() < 1e-4, "live={}", cs.thickness_live);
        // Gizmo-set thickness is authoritative — typed text resyncs to the dragged value.
        assert!(!cs.user_edited);
        let cur = gizmo_value(&state, "shell").unwrap();
        assert!(set_gizmo(&mut state, "shell", cur + 1.0));
        assert!((state.creating_shell.as_ref().unwrap().thickness_live - 4.5).abs() < 1e-4);
    }

    /// #1502: Offset and Repeat gizmos write the live number but leave a typed field alone.
    #[test]
    fn offset_and_repeat_gizmo_drags_lock_a_typed_value() {
        let mut co = CreatingSketchOffset::new(crate::model::SketchId::from_bits(0));
        co.apply_gizmo_distance(14.0, crate::value::LengthUnit::Mm);
        assert!(
            crate::value::eval_length_mm_in_doc(&co.distance, &Document::default())
                .is_some_and(|d| (d - 14.0).abs() < 1e-3),
            "untyped drag should write the field, got {}",
            co.distance
        );
        co.user_edited = true;
        co.distance = "12".to_string();
        co.apply_gizmo_distance(20.0, crate::value::LengthUnit::Mm);
        assert_eq!(co.distance, "12", "typed offset must not be overwritten by the handle");

        let mut cr = CreatingRepeat::default();
        cr.apply_gizmo_distance(30.0, crate::value::LengthUnit::Mm);
        assert!(
            crate::value::eval_length_mm_in_doc(&cr.length, &Document::default())
                .is_some_and(|d| (d - 30.0).abs() < 1e-3),
            "untyped repeat drag should write Distance, got {}",
            cr.length
        );
        cr.user_edited = true;
        cr.length = "25".to_string();
        cr.apply_gizmo_distance(40.0, crate::value::LengthUnit::Mm);
        assert_eq!(cr.length, "25", "typed repeat Distance must not be overwritten by the handle");
    }

    /// #1126: a sketch line on the top face of a box laser-cuts through the body, splitting
    /// it into two fragments just like a mid-plane cutter would.
    #[test]
    fn slice_with_a_line_on_a_face_splits_like_a_laser() {
        let mut state = box_extrusion_state();
        // Top cap of the 10×10×5 box (z = 5). Sketch a midline from x=0..10 at y=5.
        let top = FaceId::ExtrudeCap {
            extrusion: xkey(0),
            profile: ExtrudeFace::Polygon(
                state
                    .doc
                    .lines
                    .keys()
                    .take(4)
                    .collect::<Vec<_>>(),
            ),
            top: true,
        };
        // Recover the actual profile lines from the extrusion (order matters for FaceId equality
        // elsewhere, but sketch_frame only needs a valid ExtrudeCap).
        let top = {
            let ext = &state.doc.extrusions[xkey(0)];
            match &ext.faces[0] {
                ExtrudeFace::Polygon(lines) => FaceId::ExtrudeCap {
                    extrusion: xkey(0),
                    profile: ExtrudeFace::Polygon(lines.clone()),
                    top: true,
                },
                _ => top,
            }
        };
        let sketch = state.doc.add_sketch(top);
        let line = state.doc.lines.insert(crate::model::Line::from_local_endpoints(
            sketch, 0.0, 5.0, 10.0, 5.0,
        ));
        let bodies_before = state.doc.bodies.len();
        let result = state.apply(Action::CreateSliceOperation {
            targets: vec![bkey(0)],
            cutters: vec![crate::model::SliceCutter::Line { line }],
            extend_infinite: true,
        });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        let op = &state.doc.slice_ops.values().nth(0).unwrap();
        assert_eq!(op.outputs.len(), 2, "a midline laser cut yields two fragments");
        assert!(state.doc.bodies[bkey(0)].shadow);
        assert_eq!(state.doc.bodies.len(), bodies_before + 2);
        for &out in &op.outputs {
            let mesh = crate::extrude::body_solid_mesh(&state.doc, out).expect("fragment mesh");
            let vol = crate::extrude::mesh_signed_volume(&mesh).abs();
            assert!(
                (vol - 250.0).abs() < 5.0,
                "each half of a 10×10×5 box should be ~250, got {vol}"
            );
        }
    }

