    /// #1146: cutter order must not change the laser path — picking the last line first
    /// still chains into one continuous cut (two pieces), not one half-space per segment.
    #[test]
    fn slice_zigzag_with_reverse_cutter_order_still_splits_into_two() {
        for extend in [true, false] {
            for rev in [false, true] {
                let mut state = box_extrusion_state();
                let top = {
                    let ext = &state.doc.extrusions[xkey(0)];
                    match &ext.faces[0] {
                        ExtrudeFace::Polygon(lines) => FaceId::ExtrudeCap {
                            extrusion: xkey(0),
                            profile: ExtrudeFace::Polygon(lines.clone()),
                            top: true,
                        },
                        _ => panic!("box profile"),
                    }
                };
                let sketch = state.doc.add_sketch(top);
                let a = state.doc.lines.insert(crate::model::Line::from_local_endpoints(
                    sketch, 3.0, 0.0, 7.0, 3.5,
                ));
                let b = state.doc.lines.insert(crate::model::Line::from_local_endpoints(
                    sketch, 7.0, 3.5, 3.0, 6.5,
                ));
                let c = state.doc.lines.insert(crate::model::Line::from_local_endpoints(
                    sketch, 3.0, 6.5, 7.0, 10.0,
                ));
                let order = if rev {
                    vec![c, b, a]
                } else {
                    vec![a, b, c]
                };
                let result = state.apply(Action::CreateSliceOperation {
                    targets: vec![bkey(0)],
                    cutters: order
                        .iter()
                        .map(|&line| crate::model::SliceCutter::Line { line })
                        .collect(),
                    extend_infinite: extend,
                });
                assert!(
                    matches!(result, ActionResult::Ok),
                    "extend={extend} rev={rev}: {result:?}"
                );
                let outputs = &state.doc.slice_ops.values().nth(0).unwrap().outputs;
                let mut vols: Vec<f32> = outputs
                    .iter()
                    .map(|&out| {
                        let mesh =
                            crate::extrude::body_solid_mesh(&state.doc, out).expect("mesh");
                        crate::extrude::mesh_signed_volume(&mesh).abs()
                    })
                    .collect();
                vols.sort_by(|x, y| x.partial_cmp(y).unwrap());
                assert_eq!(
                    outputs.len(),
                    2,
                    "extend={extend} rev={rev}: continuous zigzag → two fragments, vols={vols:?}"
                );
                assert!(
                    vols[0] > 50.0 && vols[1] > 50.0,
                    "extend={extend} rev={rev}: both pieces real, vols={vols:?}"
                );
                assert!(
                    (vols[0] + vols[1] - 500.0).abs() < 20.0,
                    "extend={extend} rev={rev}: volumes sum to box, vols={vols:?}"
                );
            }
        }
    }

    /// #1144: laser surface previews stay inside the target body's AABB (no long wings
    /// past the solid).
    #[test]
    fn slice_laser_preview_is_truncated_to_body_bounds() {
        let mut state = box_extrusion_state();
        let top = {
            let ext = &state.doc.extrusions[xkey(0)];
            match &ext.faces[0] {
                ExtrudeFace::Polygon(lines) => FaceId::ExtrudeCap {
                    extrusion: xkey(0),
                    profile: ExtrudeFace::Polygon(lines.clone()),
                    top: true,
                },
                _ => panic!("box profile"),
            }
        };
        let sketch = state.doc.add_sketch(top);
        let a = state.doc.lines.insert(crate::model::Line::from_local_endpoints(
            sketch, 3.0, 0.0, 7.0, 3.5,
        ));
        let b = state.doc.lines.insert(crate::model::Line::from_local_endpoints(
            sketch, 7.0, 3.5, 3.0, 6.5,
        ));
        let c = state.doc.lines.insert(crate::model::Line::from_local_endpoints(
            sketch, 3.0, 6.5, 7.0, 10.0,
        ));
        let cutters = vec![
            crate::model::SliceCutter::Line { line: a },
            crate::model::SliceCutter::Line { line: b },
            crate::model::SliceCutter::Line { line: c },
        ];
        let body = crate::extrude::body_solid_mesh(&state.doc, bkey(0)).expect("body");
        let (bmin, bmax) = body.bounds().expect("bounds");
        // Small pad for tessellation / floating point only.
        let pad = 0.5;
        for extend in [false, true] {
            let meshes = crate::extrude::slice_laser_preview_meshes(
                &state.doc,
                &cutters,
                extend,
                &[bkey(0)],
            );
            assert_eq!(meshes.len(), 1, "extend={extend}");
            for tri in &meshes[0].triangles {
                for p in tri {
                    assert!(
                        p.x >= bmin.x - pad
                            && p.x <= bmax.x + pad
                            && p.y >= bmin.y - pad
                            && p.y <= bmax.y + pad
                            && p.z >= bmin.z - pad
                            && p.z <= bmax.z + pad,
                        "preview vertex {p:?} outside body bounds {bmin:?}..{bmax:?} (extend={extend})"
                    );
                }
            }
        }
    }

    /// #1147 / #1148: report cuboid with a top-to-bottom zigzag on a side face.
    fn issue_1147_cuboid_zigzag_state() -> (AppState, Vec<crate::model::SliceCutter>) {
        let bytes = include_bytes!("../tests/fixtures/issue_1147.json");
        let mut state = AppState::default();
        state.doc = crate::storage::from_json_bytes(bytes).expect("load issue_1147");
        state.doc.bump_mesh_rev();
        let cutters: Vec<_> = state
            .doc
            .lines
            .keys()
            .map(|line| crate::model::SliceCutter::Line { line })
            .collect();
        assert_eq!(cutters.len(), 3, "fixture has three laser lines");
        (state, cutters)
    }

    /// World polyline of the fixture's zigzag (sketch line order, stitched).
    fn issue_1147_path_world(doc: &crate::model::Document) -> Vec<glam::Vec3> {
        let keys: Vec<_> = doc.lines.keys().collect();
        let mut path = Vec::new();
        for &key in &keys {
            let line = &doc.lines[key];
            let poly = crate::face::line_world_polyline(doc, line).expect("poly");
            if path.is_empty() {
                path = poly;
            } else {
                let tip = *path.last().unwrap();
                let mut poly = poly;
                if (*poly.last().unwrap() - tip).length_squared()
                    < (poly[0] - tip).length_squared()
                {
                    poly.reverse();
                }
                path.extend(poly.into_iter().skip(1));
            }
        }
        path
    }

    /// #1147: with Infinite cut, free-end extension must not warp a path that already
    /// spans the body — preview follows the drawn lines, and infinite ≈ finite.
    #[test]
    fn slice_laser_preview_follows_top_to_bottom_path_with_infinite() {
        let (state, cutters) = issue_1147_cuboid_zigzag_state();
        let body_key = state
            .doc
            .bodies
            .iter()
            .find(|(_, b)| !b.shadow)
            .map(|(k, _)| k)
            .expect("body");
        let path = issue_1147_path_world(&state.doc);
        assert!(path.len() >= 2);
        let finite = crate::extrude::slice_laser_preview_meshes(
            &state.doc,
            &cutters,
            false,
            &[body_key],
        );
        let infinite = crate::extrude::slice_laser_preview_meshes(
            &state.doc,
            &cutters,
            true,
            &[body_key],
        );
        assert_eq!(finite.len(), 1);
        assert_eq!(infinite.len(), 1);
        // Every drawn path vertex must lie on the preview surface (near some triangle).
        let near_mesh = |mesh: &crate::extrude::SolidMesh, p: glam::Vec3, tol: f32| -> bool {
            mesh.triangles.iter().any(|tri| {
                for i in 0..3 {
                    let a = tri[i];
                    let b = tri[(i + 1) % 3];
                    let ab = b - a;
                    let t = if ab.length_squared() < 1e-12 {
                        0.0
                    } else {
                        ((p - a).dot(ab) / ab.length_squared()).clamp(0.0, 1.0)
                    };
                    if (a + ab * t - p).length() < tol {
                        return true;
                    }
                }
                // Also accept points on the triangle face (ruled strip interior).
                let n = (tri[1] - tri[0]).cross(tri[2] - tri[0]);
                let nn = n.length_squared();
                if nn < 1e-12 {
                    return false;
                }
                let n = n / nn.sqrt();
                if (p - tri[0]).dot(n).abs() > tol {
                    return false;
                }
                true
            })
        };
        for (i, &p) in path.iter().enumerate() {
            assert!(
                near_mesh(&finite[0], p, 1.5),
                "finite preview misses path vertex {i}: {p:?}"
            );
            assert!(
                near_mesh(&infinite[0], p, 1.5),
                "infinite preview misses path vertex {i}: {p:?}"
            );
        }
        // Infinite must not invent a path that runs to the AABB corner (the old clamp
        // bug): first/last preview edge along the face should stay near the drawn ends.
        let start = path[0];
        let end = *path.last().unwrap();
        let inf_verts: Vec<_> = infinite[0]
            .triangles
            .iter()
            .flat_map(|t| t.iter().copied())
            .collect();
        // Among preview verts near the start's face plane position (same "along face"
        // plane as start), none should be many body-widths away from start.
        let body = crate::extrude::body_solid_mesh(&state.doc, body_key).expect("body");
        let (bmin, bmax) = body.bounds().expect("bounds");
        let diag = (bmax - bmin).length();
        for &v in &inf_verts {
            // On the sketch face (front of cuboid, y ≈ start.y): far lateral drift is the bug.
            if (v.y - start.y).abs() < 0.5 && (v.z - start.z).abs() < 0.5 {
                assert!(
                    (v.x - start.x).abs() < diag * 0.15,
                    "infinite preview end drifted along top face: start={start:?} vert={v:?}"
                );
            }
            if (v.y - end.y).abs() < 0.5 && (v.z - end.z).abs() < 0.5 {
                assert!(
                    (v.x - end.x).abs() < diag * 0.15,
                    "infinite preview end drifted along bottom face: end={end:?} vert={v:?}"
                );
            }
        }
    }

    /// #1147: when the path already spans the body, infinite and finite cuts produce the
    /// same fragment volumes (extension along the face is a no-op inside the solid).
    #[test]
    fn slice_top_to_bottom_zigzag_infinite_matches_finite() {
        let (state_base, cutters) = issue_1147_cuboid_zigzag_state();
        let body_key = state_base
            .doc
            .bodies
            .iter()
            .find(|(_, b)| !b.shadow)
            .map(|(k, _)| k)
            .expect("body");
        let vols_for = |extend: bool| -> Vec<f32> {
            let mut state = AppState {
                doc: state_base.doc.clone(),
                ..AppState::default()
            };
            state.doc.bump_mesh_rev();
            let result = state.apply(Action::CreateSliceOperation {
                targets: vec![body_key],
                cutters: cutters.clone(),
                extend_infinite: extend,
            });
            assert!(matches!(result, ActionResult::Ok), "extend={extend}: {result:?}");
            let op = state.doc.slice_ops.values().next().unwrap();
            assert_eq!(op.outputs.len(), 2, "extend={extend}: two fragments");
            let mut vols: Vec<f32> = op
                .outputs
                .iter()
                .map(|&out| {
                    let mesh = crate::extrude::body_solid_mesh(&state.doc, out).expect("mesh");
                    crate::extrude::mesh_signed_volume(&mesh).abs()
                })
                .collect();
            vols.sort_by(|a, b| a.partial_cmp(b).unwrap());
            vols
        };
        let finite = vols_for(false);
        let infinite = vols_for(true);
        assert_eq!(finite.len(), 2);
        assert_eq!(infinite.len(), 2);
        for i in 0..2 {
            assert!(
                (finite[i] - infinite[i]).abs() < 5.0,
                "infinite vs finite volumes differ: finite={finite:?} infinite={infinite:?}"
            );
        }
    }

    /// #1217: infinite laser preview is a rectangular ruled strip — front and back edges
    /// stay parallel (same direction as the path), not a sheared/collapsed triangle when
    /// the sketch face is tilted relative to the body AABB.
    #[test]
    fn slice_laser_preview_infinite_is_square_with_parallel_edges() {
        let bytes = include_bytes!("../tests/fixtures/issue_1217.json");
        let mut state = AppState::default();
        state.doc = crate::storage::from_json_bytes(bytes).expect("load issue_1217");
        state.doc.bump_mesh_rev();
        let sk1 = crate::model::sketch_key_for_slot(1);
        // Report used two straight cutters on the extrude side face (a V peak).
        let cutters: Vec<_> = state
            .doc
            .lines
            .iter()
            .filter(|(_, l)| l.sketch == sk1 && !l.construction && l.bezier.is_none())
            .take(2)
            .map(|(k, _)| crate::model::SliceCutter::Line { line: k })
            .collect();
        assert_eq!(cutters.len(), 2);
        let body_key = crate::model::body_key_for_slot(2);
        let meshes = crate::extrude::slice_laser_preview_meshes(
            &state.doc,
            &cutters,
            true,
            &[body_key],
        );
        assert_eq!(meshes.len(), 1, "one continuous laser surface");
        let mesh = &meshes[0];
        assert!(
            mesh.triangles.len() >= 2,
            "at least one ruled quad (two tris), got {}",
            mesh.triangles.len()
        );

        // Rebuild the path the preview used (infinite free-end extension) and measure
        // each ruling (front→back along the face normal). Every ruling must be a
        // non-zero translation of the same vector so front ∥ back.
        // Infer rulings from consecutive triangle pairs that share the strip structure
        // [a0,b0,b1] + [a0,b1,a1] → ruling at a is a1-a0, at b is b1-b0.
        let mut rulings: Vec<glam::Vec3> = Vec::new();
        let tris = &mesh.triangles;
        let mut i = 0;
        while i + 1 < tris.len() {
            let t0 = tris[i];
            let t1 = tris[i + 1];
            // Match the strip order from slice_laser_preview_meshes.
            let a0 = t0[0];
            let b0 = t0[1];
            let b1 = t0[2];
            let a1 = t1[2];
            // Sanity: second tri should be [a0, b1, a1].
            assert!(
                (t1[0] - a0).length() < 1e-3 && (t1[1] - b1).length() < 1e-3,
                "preview triangulation is not the expected ruled strip at tri {i}"
            );
            let r_a = a1 - a0;
            let r_b = b1 - b0;
            rulings.push(r_a);
            rulings.push(r_b);
            // No collapsed end: ruling must have real length (the goofy triangle).
            assert!(
                r_a.length() > 1.0,
                "ruling collapsed at segment start: |r|={}",
                r_a.length()
            );
            assert!(
                r_b.length() > 1.0,
                "ruling collapsed at segment end: |r|={}",
                r_b.length()
            );
            // Front and back edges of this quad must be parallel (and same sense).
            let front = b0 - a0;
            let back = b1 - a1;
            if front.length() > 1e-3 && back.length() > 1e-3 {
                let f = front.normalize();
                let b = back.normalize();
                let parallel = f.dot(b).abs() > 0.999;
                assert!(
                    parallel,
                    "front/back edges not parallel: front={front:?} back={back:?} dot={}",
                    f.dot(b)
                );
            }
            // Both rulings of the quad must match (parallelogram, not trapezoid/triangle).
            let ra = r_a.normalize();
            let rb = r_b.normalize();
            assert!(
                ra.dot(rb) > 0.999,
                "rulings of one quad not parallel: r_a={r_a:?} r_b={r_b:?}"
            );
            assert!(
                (r_a.length() - r_b.length()).abs() < 1.0,
                "ruling lengths differ across a quad (sheared strip): {} vs {}",
                r_a.length(),
                r_b.length()
            );
            i += 2;
        }
        // All rulings across the whole path must share one direction and length —
        // a prismatic laser slab, not a fan.
        assert!(!rulings.is_empty());
        let r0 = rulings[0];
        for (k, r) in rulings.iter().enumerate().skip(1) {
            assert!(
                r.normalize().dot(r0.normalize()) > 0.999,
                "ruling {k} not parallel to ruling 0: {r:?} vs {r0:?}"
            );
            assert!(
                (r.length() - r0.length()).abs() < 1.0,
                "ruling {k} length {} ≠ ruling 0 length {}",
                r.length(),
                r0.length()
            );
        }
    }

