    /// #1355/#1356: an empty boolean (target wholly inside the cutter, or disjoint
    /// intersect) must error instead of committing a phantom body.
    #[test]
    fn boolean_empty_result_is_rejected() {
        // Two overlapping boxes: cut the small overlap the wrong way by using a
        // 10×10×5 as A and a much larger box as B via a third, bigger extrusion.
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        let small = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            0.0,
            0.0,
            4.0,
            4.0,
            [false; 4],
        );
        let large = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            -20.0,
            -20.0,
            30.0,
            30.0,
            [false; 4],
        );
        for (rect, h) in [(&small, 4.0), (&large, 50.0)] {
            state.apply(Action::CreateExtrusion {
                expression: None,
                sketch,
                faces: vec![ExtrudeFace::Polygon(rect.to_vec())],
                distance: h,
                body: crate::actions::ExtrudeBodyChoice::New,
                target: None,
                symmetric: false,
                taper: 0.0,
                taper_mode: crate::model::ExtrudeTaperMode::Distance,
                taper_expression: None,
            });
        }
        let bodies_before = state.doc.bodies.len();
        let result = state.apply(Action::CreateBooleanOperation {
            kind: crate::model::BooleanOpKind::Cut,
            a: vec![bkey(0)],
            b: vec![bkey(1)],
            keep_b: false,
            solid_count: None,
        });
        assert!(
            matches!(result, ActionResult::Err(ref e) if e.to_ascii_lowercase().contains("empty")),
            "empty cut must error, got {result:?}"
        );
        assert_eq!(state.doc.bodies.len(), bodies_before, "no phantom body");
        assert!(state.doc.boolean_ops.is_empty());

        let result = state.apply(Action::CreateBooleanOperation {
            kind: crate::model::BooleanOpKind::Intersect,
            a: vec![bkey(0)],
            b: vec![bkey(1)],
            keep_b: false,
            solid_count: None,
        });
        // These two overlap — intersect is non-empty. Use a far-away third box instead.
        assert!(
            matches!(result, ActionResult::Ok),
            "overlapping intersect should still succeed, got {result:?}"
        );
        state.apply(Action::UndoLast);

        let far = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            80.0,
            80.0,
            90.0,
            90.0,
            [false; 4],
        );
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![ExtrudeFace::Polygon(far.to_vec())],
            distance: 10.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,
        });
        let bodies_before = state.doc.bodies.len();
        let result = state.apply(Action::CreateBooleanOperation {
            kind: crate::model::BooleanOpKind::Intersect,
            a: vec![bkey(0)],
            b: vec![bkey(2)],
            keep_b: false,
            solid_count: None,
        });
        assert!(
            matches!(result, ActionResult::Err(ref e) if e.to_ascii_lowercase().contains("empty")),
            "disjoint intersect must error, got {result:?}"
        );
        assert_eq!(state.doc.bodies.len(), bodies_before, "no phantom body");
        assert!(state.doc.boolean_ops.is_empty());
    }

    /// #122: pushing/pulling a bare side wall (no separate sketch) creates an implicit
    /// sketch on that exact face and starts extruding from it.
    #[test]
    fn extrude_body_face_pushes_a_box_side_wall_directly() {
        let mut state = box_extrusion_state();
        let profile = state.doc.extrusions[xkey(0)].faces[0].clone();
        let sketches_before = state.doc.sketches.len();
        let face_id = FaceId::ExtrudeSide {
            extrusion: xkey(0),
            profile,
            edge: 0,
        };
        // #508: default extrude grows toward the camera — stand outside the wall so the
        // push extends free space rather than into the solid.
        if let Some(frame) = crate::face::sketch_frame(&state.doc, face_id.clone()) {
            state.cam.target = frame.origin;
            // Place the eye outside along the face normal.
            let outside = frame.origin + frame.normal * 40.0;
            let offset = outside - state.cam.target;
            state.cam.distance = offset.length();
            let dir = offset.normalize_or_zero();
            state.cam.pitch = dir.z.asin();
            state.cam.yaw = dir.y.atan2(dir.x);
        }

        let result = state.apply(Action::ExtrudeBodyFace { face_id });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        assert_eq!(
            state.doc.sketches.len(),
            sketches_before + 1,
            "should create exactly one implicit sketch"
        );
        let ce = state
            .creating_extrusion
            .as_ref()
            .expect("should start a fresh in-progress extrusion");
        assert_eq!(ce.faces.len(), 1);
        assert!(matches!(ce.faces[0], ExtrudeFace::Polygon(_)));
        assert!(
            ce.distance > 0.0,
            "from outside the wall, default distance should be positive along the normal"
        );

        state.apply(Action::CommitExtrusion);
        assert_eq!(state.doc.extrusions.len(), 2, "should commit as a second extrusion");
        // Sketching on an existing body's face merges by default (#32/#1106): the host is
        // shadowed and a new combined body is the extrusion's output. The combined mesh
        // grows by the default 10mm along the outward normal of the wall.
        let live = state
            .doc
            .bodies
            .iter()
            .find(|(_, b)| !b.shadow)
            .map(|(k, _)| k)
            .expect("combined live body");
        let merged = crate::extrude::body_solid_mesh(&state.doc, live).unwrap();
        let (min, max) = merged.bounds().unwrap();
        let extent = (max - min).max_element();
        assert!(
            (max - min).min_element() > 4.0 && extent > 15.0,
            "merged body should grow past the original 10×10×5 box, got {min:?}..{max:?}"
        );
        assert_eq!(state.doc.bodies.len(), 2, "host shadowed + combined output");
        assert!(
            state.doc.bodies.values().any(|b| b.shadow),
            "original body is shadowed"
        );
    }

    /// #509: cancelling a body-face extrude discards the projected boundary sketch so
    /// filleted caps don't leave 100+ segments behind every attempt.
    #[test]
    fn cancelling_body_face_extrude_discards_orphan_sketch() {
        let mut state = box_extrusion_state();
        let profile = state.doc.extrusions[xkey(0)].faces[0].clone();
        let face_id = FaceId::ExtrudeSide {
            extrusion: xkey(0),
            profile,
            edge: 0,
        };
        state.apply(Action::SetTool(Tool::Extrude));
        state.apply(Action::ExtrudeBodyFace { face_id });
        let sketch = state.creating_extrusion.as_ref().unwrap().sketch.expect("body-face extrude has a sketch");
        assert!(state.doc.sketches.contains(sketch));
        state.apply(Action::CancelOperation);
        assert!(
            !state.doc.sketches.contains(sketch),
            "orphan body-face sketch should be removed on cancel"
        );
        assert!(
            !state.draft_has_picks(state.tool_row().draft),
            "cancel empties the extrude draft"
        );
    }

