    /// #1114: Zoom to Fit unions in-progress operation previews (e.g. a Mirror ghost) so the
    /// whole preview fits, not only committed bodies.
    #[test]
    fn zoom_to_fit_includes_mirror_preview() {
        let mut state = box_extrusion_state();
        state.apply(Action::ExitSketch);
        // Box is z in [0, 5]. Mirrored across the ground (z = 0) the ghost is z in [-5, 0];
        // document alone centres near z = 2.5, with the ghost the union centres near z = 0.
        state.creating_mirror = Some(CreatingMirror {
            plane: Some(FaceId::ConstructionPlane(pkey(0))),
            targets: vec![bkey(0)],
            mode: crate::model::MirrorMode::NewBody,
            editing: None,
        });
        state.cam.target = glam::Vec3::new(999.0, 999.0, 999.0);
        let result = state.apply(Action::ZoomToFit);
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        while state.cam.tick_transition(0.05) {}
        let target = state.cam.target;
        assert!(
            target.z.abs() < 0.75,
            "zoom-to-fit should include the mirror ghost below the plane (centre ~z=0), got {target:?}"
        );
        // Also when the source body is selected — selection alone would miss the ghost.
        state.apply(Action::ClickSceneElement {
            element: crate::hierarchy::SceneElement::Body(bkey(0)),
            additive: false,
        });
        state.cam.target = glam::Vec3::new(999.0, 999.0, 999.0);
        let result = state.apply(Action::ZoomToFit);
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        while state.cam.tick_transition(0.05) {}
        assert!(
            state.cam.target.z.abs() < 0.75,
            "selection + mirror preview must still frame both halves, got {:?}",
            state.cam.target
        );
    }

    /// #1381: Zoom to Fit ignores shadow bodies (ghost/faded copies consumed by an
    /// operation) when framing the document — only live geometry sets the bounds.
    #[test]
    fn zoom_to_fit_ignores_shadow_bodies() {
        let mut state = box_extrusion_state();
        // Solid box spans x/y in [0,10], z in [0,5]; its sketch lines sit on z = 0.
        assert_eq!(
            crate::extrude::document_world_bounds(&state.doc),
            Some((glam::Vec3::new(0.0, 0.0, 0.0), glam::Vec3::new(10.0, 10.0, 5.0)))
        );
        // Shadowing the body must drop the solid's height out of the fit: only the 2-D
        // sketch lines remain (max z becomes 0), proving shadow bodies are excluded.
        state.apply(Action::SetBodyShadow { body: bkey(0), shadow: true });
        let (min, max) = crate::extrude::document_world_bounds(&state.doc)
            .expect("sketch lines still give 2-D bounds");
        assert!(
            max.z < 0.01,
            "zoom-to-fit bounds must ignore the shadow body's height, got {min:?}..{max:?}"
        );
        // Clearing the selection and zooming frames the same (shadow-free) bounds, not a
        // failure.
        state.apply(Action::ExitSketch);
        let result = state.apply(Action::ZoomToFit);
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        while state.cam.tick_transition(0.05) {}
    }

    /// #164: Zoom to Fit frames the selection when one exists (camera target lands on the
    /// selected body's center), else the whole document's non-construction geometry.
    #[test]
    fn zoom_to_fit_frames_selection_then_falls_back_to_document() {
        let mut state = box_extrusion_state();
        state.apply(Action::ExitSketch);
        // Select the body (its box spans 0..10 in x/y, 0..5 in z → center (5, 5, 2.5)).
        state.apply(Action::ClickSceneElement {
            element: crate::hierarchy::SceneElement::Body(bkey(0)),
            additive: false,
        });
        let result = state.apply(Action::ZoomToFit);
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        while state.cam.tick_transition(0.05) {}
        let target = state.cam.target;
        assert!(
            (target - glam::Vec3::new(5.0, 5.0, 2.5)).length() < 0.5,
            "camera should center on the selected body, got {target:?}"
        );

        // Nothing selected: still zooms (whole document).
        state.apply(Action::ClearSceneSelection);
        state.cam.target = glam::Vec3::new(999.0, 999.0, 999.0);
        let result = state.apply(Action::ZoomToFit);
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        while state.cam.tick_transition(0.05) {}
        assert!(
            (state.cam.target - glam::Vec3::new(5.0, 5.0, 2.5)).length() < 0.6,
            "empty selection frames the whole document, got {:?}",
            state.cam.target
        );
    }

