    /// #166/#531: one plural commit builds a single edge-treatment operation carrying every
    /// edge in the set (shared kind + amount), shadowing the input body and producing one
    /// beveled output — as a single undo group (one Undo removes the whole operation).
    #[test]
    fn commit_edge_treatments_applies_the_whole_set_in_one_undo_group() {
        let mut state = box_extrusion_state();
        let edges = vec![
            (crate::model::TreatableSolid::Extrusion(xkey(0)), crate::model::ExtrusionEdgeRef::Vertical { face: 0, edge: 0 }),
            (crate::model::TreatableSolid::Extrusion(xkey(0)), crate::model::ExtrusionEdgeRef::Vertical { face: 0, edge: 2 }),
        ];
        let result = state.apply(Action::CommitEdgeTreatments {
            edges: edges.clone(),
            kind: VertexTreatmentKind::Chamfer,
            amount: 2.0,
            expression: String::new(),
        });
        assert!(matches!(result, ActionResult::Ok), "{result:?}");
        assert_eq!(state.doc.edge_treatment_ops.len(), 1, "one operation created");
        let op = &state.doc.edge_treatment_ops.values().nth(0).unwrap();
        let treated: Vec<_> = op.edges.iter().map(|t| t.edge).collect();
        assert_eq!(treated.len(), 2, "both edges treated: {treated:?}");
        for (_, edge) in &edges {
            assert!(treated.contains(edge), "missing {edge:?} in {treated:?}");
        }
        assert_eq!(op.targets, vec![bkey(0)], "the one input body is the target");
        assert_eq!(op.outputs.len(), 1, "one beveled output body");
        assert!(state.doc.bodies.values().nth(0).unwrap().shadow, "the input body becomes a shadow");
        assert!(!state.doc.bodies[op.outputs[0]].shadow, "the output is a real body");

        // #168: the plural commit is one undo group — a single Undo reverts the whole
        // operation while leaving the extrusion (and un-shadowing the input body).
        state.apply(Action::UndoLast);
        assert!(
            state.doc.edge_treatment_ops.is_empty(),
            "one undo must remove the whole operation"
        );
        assert!(state.doc.extrusions.contains(xkey(0)), "the extrusion must survive the undo");
        assert!(!state.doc.bodies.values().nth(0).unwrap().shadow, "the input body is no longer shadowed");
    }

    /// #168/#531: undoing a committed chamfer removes its whole operation (releasing the
    /// shadow input and beveled output), never the extrusion.
    #[test]
    fn undo_reverts_a_single_edge_treatment() {
        let mut state = box_extrusion_state();
        let edge = crate::model::ExtrusionEdgeRef::Vertical { face: 0, edge: 0 };
        state.apply(Action::CommitEdgeTreatments {
            edges: vec![(crate::model::TreatableSolid::Extrusion(xkey(0)), edge)],
            kind: VertexTreatmentKind::Chamfer,
            amount: 2.0,
            expression: String::new(),
        });
        assert_eq!(state.doc.edge_treatment_ops.len(), 1);
        assert!(state.doc.bodies.values().nth(0).unwrap().shadow);

        state.apply(Action::UndoLast);
        assert!(
            state.doc.edge_treatment_ops.is_empty(),
            "undo removes the operation"
        );
        assert!(!state.doc.bodies.values().nth(0).unwrap().shadow, "the input body is released from shadow");
        assert!(state.doc.extrusions.contains(xkey(0)), "the extrusion must survive");
    }

    /// #157/#166: switching to the Chamfer tool with treatable body edges already selected
    /// preloads them into the in-progress treatment so the gizmo shows immediately.
    #[test]
    fn switching_to_chamfer_preloads_selected_edges() {
        use crate::hierarchy::{quantize_body_point, SceneElement};

        let mut state = box_extrusion_state();
        state.apply(Action::ExitSketch);
        let treatable = crate::extrude::treatable_edges(&state.doc);
        let (_, _, a, b) = treatable[0].clone();
        state.apply(Action::ClickSceneElement {
            element: SceneElement::BodyEdge {
                body: bkey(0),
                a: quantize_body_point(a),
                b: quantize_body_point(b),
            },
            additive: false,
        });
        state.apply(Action::SetTool(Tool::Chamfer));
        let cet = state
            .creating_edge_treatment
            .as_ref()
            .expect("selection should preload the treatment");
        assert_eq!(cet.edges.len(), 1);
        assert_eq!(cet.kind, VertexTreatmentKind::Chamfer);

        // Without a selection, no preload happens.
        let mut state = box_extrusion_state();
        state.apply(Action::ExitSketch);
        state.apply(Action::SetTool(Tool::Chamfer));
        assert!(state.creating_edge_treatment.is_none());
    }

