    /// #138: typing `name=value` into a dimension text input (here a circle's diameter) creates
    /// the variable and drives the dimension by it. `dia=30` makes a parameter `dia`=30 and a
    /// diameter constraint whose expression is `dia`.
    #[test]
    fn commit_circle_with_inline_variable_creates_parameter() {
        let mut state = AppState::default();
        begin_default_sketch(&mut state);
        state.creating_circle = Some(CreatingCircle {
            origin: Vec3::ZERO,
            text: "dia=30".to_string(),
            last_mouse: Vec3::new(10.0, 0.0, 0.0),
            user_edited: true,
            pending_focus: false,
            construction: false,
            anchor: crate::actions::CircleAnchor::Center,
        });
        state.apply(Action::CommitCircle);
        assert_eq!(state.doc.circles.len(), 1);
        assert!((state.doc.circles[rkey(0)].diameter() - 30.0).abs() < 1e-4);
        let param = state
            .doc
            .parameters
            .values()
            .find(|p| p.name == "dia")
            .expect("variable dia created");
        assert_eq!(param.expression, "30");
        assert_eq!(
            state.doc.constraints.values().next().unwrap().expression,
            "dia"
        );
    }

    /// #147 / SPEC §5.1.1: `dia=30` when `dia` already exists **redefines** the parameter and
    /// commits the circle, instead of failing with a duplicate-name error.
    #[test]
    fn commit_circle_with_inline_variable_redefines_existing_parameter() {
        let mut state = AppState::default();
        crate::parameters::add_parameter(&mut state.doc, "dia".to_string(), "20mm".to_string())
            .unwrap();
        begin_default_sketch(&mut state);
        state.creating_circle = Some(CreatingCircle {
            origin: Vec3::ZERO,
            text: "dia=30".to_string(),
            last_mouse: Vec3::new(10.0, 0.0, 0.0),
            user_edited: true,
            pending_focus: false,
            construction: false,
            anchor: crate::actions::CircleAnchor::Center,
        });
        state.apply(Action::CommitCircle);
        assert_eq!(state.doc.circles.len(), 1, "commit must not fail: {}", state.status);
        assert!((state.doc.circles[rkey(0)].diameter() - 30.0).abs() < 1e-4);
        let dia_params: Vec<_> = state
            .doc
            .parameters
            .values()
            .filter(|p| p.name == "dia")
            .collect();
        assert_eq!(dia_params.len(), 1, "still exactly one 'dia' parameter");
        assert_eq!(dia_params[0].expression, "30", "existing parameter redefined");
    }

    /// #763: picking up the Dimension tool with a line already selected goes straight into
    /// *placing* its length — the preview follows the cursor until a click drops it.
    #[test]
    fn dimension_tool_places_a_length_when_a_line_is_selected() {
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 8.0, 0.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        state.apply(Action::SetTool(Tool::Dimension));
        assert!(state.editing_committed_dim.is_none());
        assert_eq!(
            state.placing_dimension.as_ref().map(|p| p.target.clone()),
            Some(DimensionTarget::Distance(DistanceTarget::LineLength(lkey(0))))
        );
        // The placement click (the viewport's job) opens the value editor.
        state.apply(Action::BeginDimensionEdit {
            target: DimensionTarget::Distance(DistanceTarget::LineLength(lkey(0))),
        });
        assert_eq!(
            state.editing_committed_dim.as_ref().unwrap().target,
            DimEditTarget::New(DimensionTarget::Distance(DistanceTarget::LineLength(lkey(0))))
        );
    }

    /// #400: the floating dimension editor must not linger into tools that can't
    /// interact with it — switching to any tool other than Select/Dimension cancels it.
    #[test]
    fn switching_tools_cancels_in_progress_dimension_edit() {
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 8.0, 0.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        state.apply(Action::SetTool(Tool::Dimension));
        state.apply(Action::BeginDimensionEdit {
            target: DimensionTarget::Distance(DistanceTarget::LineLength(lkey(0))),
        });
        assert!(state.editing_committed_dim.is_some());
        // Select can still drag/edit dimension labels, so the edit survives it.
        state.apply(Action::SetTool(Tool::Select));
        assert!(state.editing_committed_dim.is_some());
        state.apply(Action::SetTool(Tool::Constraint));
        assert!(state.editing_committed_dim.is_none());
    }

    #[test]
    fn angle_gizmo_constraint_only_while_editing_committed_angle() {
        use crate::model::{ConstraintLine, DimensionTarget};

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0));
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 0.0, 10.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.doc.shape_order.push(ShapeKind::Line);
        let rotation_sign = crate::constraints::angle_constraint_natural_sign(
            &state.doc,
            ConstraintLine::Line(lkey(0)),
            ConstraintLine::Line(lkey(1)),
        )
        .unwrap();
        crate::constraints::add_angle_constraint_with_sign(
            &mut state.doc,
            sketch,
            ConstraintLine::Line(lkey(0)),
            ConstraintLine::Line(lkey(1)),
            rotation_sign,
            "90deg".to_string(),
        )
        .unwrap();
        assert_eq!(
            angle_gizmo_constraint_for_edit(state.editing_committed_dim.as_ref(), &state.doc),
            None
        );
        state.editing_committed_dim = Some(EditingCommittedDim {
            target: DimEditTarget::Constraint(nkey(0)),
            text: "90deg".to_string(),
            pending_focus: true,
            user_edited: false,
            dim_offset: None,
        });
        assert_eq!(
            angle_gizmo_constraint_for_edit(state.editing_committed_dim.as_ref(), &state.doc),
            Some(nkey(0))
        );
        state.editing_committed_dim = Some(EditingCommittedDim {
            target: DimEditTarget::New(DimensionTarget::Angle {
                line_a: ConstraintLine::Line(lkey(0)),
                line_b: ConstraintLine::Line(lkey(1)),
                rotation_sign: 1,
            }),
            text: "45deg".to_string(),
            pending_focus: true,
            user_edited: false,
            dim_offset: None,
        });
        assert_eq!(
            angle_gizmo_constraint_for_edit(state.editing_committed_dim.as_ref(), &state.doc),
            None
        );
    }

    #[test]
    fn dimension_tool_begins_angle_edit_for_two_non_parallel_lines() {
        use crate::model::{ConstraintLine, DimensionTarget};

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0));
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 0.0, 10.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.doc.shape_order.push(ShapeKind::Line);
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(1)),
            additive: true,
        });
        state.apply(Action::SetTool(Tool::Dimension));
        // A brand-new angle dimension enters a placement phase (mouse picks the quadrant)
        // rather than jumping straight to editing the value (#40).
        assert!(state.editing_committed_dim.is_none());
        assert_eq!(
            state.placing_dimension,
            Some(PlacingDimension {
                target: DimensionTarget::Angle {
                    line_a: ConstraintLine::Line(lkey(0)),
                    line_b: ConstraintLine::Line(lkey(1)),
                    rotation_sign: 1,
                },
                offset: None,
            })
        );

        let target = DimensionTarget::Angle {
            line_a: ConstraintLine::Line(lkey(0)),
            line_b: ConstraintLine::Line(lkey(1)),
            rotation_sign: 1,
        };
        state.placing_dimension = None;
        state.apply(Action::BeginDimensionEdit { target: target.clone() });
        assert_eq!(
            state.editing_committed_dim.as_ref().unwrap().target,
            DimEditTarget::New(target)
        );
    }

    /// #763: under the Dimension tool a plain click dimensions what it hits — the first
    /// edge goes straight into placing its length — and **Shift**+click adds a second edge,
    /// which turns the placement into the angle between them.
    #[test]
    fn dimension_tool_click_places_length_then_shift_click_places_angle() {
        use crate::model::{ConstraintLine, DimensionTarget};

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state
            .doc
            .lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0));
        state
            .doc
            .lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 0.0, 10.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.doc.shape_order.push(ShapeKind::Line);
        state.apply(Action::SetTool(Tool::Dimension));
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        assert!(
            state.editing_committed_dim.is_none(),
            "the value editor waits until the dimension is placed"
        );
        assert_eq!(
            state.placing_dimension,
            Some(PlacingDimension {
                target: DimensionTarget::Distance(DistanceTarget::LineLength(lkey(0))),
                offset: None,
            }),
            "one edge places its length"
        );
        assert!(state.scene_selection.is_selected(SceneElement::Line(lkey(0))));

        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(1)),
            additive: true, // Shift adds the second edge
        });
        assert!(state.editing_committed_dim.is_none());
        assert_eq!(
            state.placing_dimension,
            Some(PlacingDimension {
                target: DimensionTarget::Angle {
                    line_a: ConstraintLine::Line(lkey(0)),
                    line_b: ConstraintLine::Line(lkey(1)),
                    rotation_sign: 1,
                },
                offset: None,
            })
        );

        // #762: a plain click on a third edge switches to dimensioning *that*, instead of
        // dropping the angle where the click landed.
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 20.0, 10.0, 24.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(2)),
            additive: false,
        });
        assert_eq!(
            state.placing_dimension,
            Some(PlacingDimension {
                target: DimensionTarget::Distance(DistanceTarget::LineLength(lkey(2))),
                offset: None,
            })
        );
        assert!(!state.scene_selection.is_selected(SceneElement::Line(lkey(0))));
    }

    /// #780: an edge that already carries a dimension opens its value editor when clicked —
    /// and Shift+clicking a second edge from there drops that edit and dimensions the angle
    /// between the two instead of being swallowed.
    #[test]
    fn shift_click_while_typing_a_value_adds_to_the_selection() {
        use crate::model::{ConstraintLine, DimensionTarget};

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0));
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 0.0, 10.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.doc.shape_order.push(ShapeKind::Line);
        state.apply(Action::SetTool(Tool::Dimension));

        // Give line 0 a length, then click it: its value editor opens straight away.
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        state.apply(Action::BeginDimensionEdit {
            target: DimensionTarget::Distance(DistanceTarget::LineLength(lkey(0))),
        });
        state.editing_committed_dim.as_mut().unwrap().text = "12".to_string();
        state.apply(Action::CommitCommittedDim);
        // A single click on an already-dimensioned edge only selects it (#802) — a
        // double-click is what opens the value; the tool's own entry point does the same.
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        assert!(state.editing_committed_dim.is_none(), "a single click doesn't edit");
        state.try_begin_dimension_from_selection();
        assert!(state.editing_committed_dim.is_some(), "double-click / D edits it");

        // Shift+click the other edge: the edit gives way to the angle between them.
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(1)),
            additive: true,
        });
        assert!(state.editing_committed_dim.is_none(), "the edit stood down");
        assert!(state.scene_selection.is_selected(SceneElement::Line(lkey(0))));
        assert!(state.scene_selection.is_selected(SceneElement::Line(lkey(1))));
        assert_eq!(
            state.placing_dimension.as_ref().map(|p| p.target.clone()),
            Some(DimensionTarget::Angle {
                line_a: ConstraintLine::Line(lkey(0)),
                line_b: ConstraintLine::Line(lkey(1)),
                rotation_sign: 1,
            })
        );
    }

    /// #802: an edge that already carries a dimension is still selectable — the click just
    /// doesn't open its value.
    #[test]
    fn single_click_on_a_dimensioned_edge_only_selects_it() {
        use crate::model::DimensionTarget;

        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        state.doc.lines
            .insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 8.0, 0.0));
        state.doc.shape_order.push(ShapeKind::Line);
        state.apply(Action::SetTool(Tool::Dimension));
        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        state.apply(Action::BeginDimensionEdit {
            target: DimensionTarget::Distance(DistanceTarget::LineLength(lkey(0))),
        });
        state.editing_committed_dim.as_mut().unwrap().text = "20".to_string();
        state.apply(Action::CommitCommittedDim);

        state.apply(Action::ClickSceneElement {
            element: SceneElement::Line(lkey(0)),
            additive: false,
        });
        assert!(state.editing_committed_dim.is_none(), "no editor from a single click");
        assert!(state.placing_dimension.is_none(), "and nothing new to place either");
        assert!(
            state.scene_selection.is_selected(SceneElement::Line(lkey(0))),
            "but it IS selected, so it can pair with something else"
        );
    }

