    /// #749: Esc during a Move drops the in-progress picks — the destination ghost
    /// follows them, so it vanishes too — and a second Esc leaves the tool with the
    /// usual tool-switch cleanup, not a bare tool assignment that lets stale picks
    /// resurface on the next visit.
    #[test]
    fn escape_cancels_an_in_progress_move_then_leaves_the_tool() {
        let mut state = AppState::default();
        state.apply(Action::SetTool(Tool::Move));
        state.creating_move.as_mut().unwrap().targets.push(bkey(0));
        state.creating_move.as_mut().unwrap().start_point_a =
            Some(crate::model::MovePointRef::Vertex { body: bkey(0), p: [0; 3] });

        state.apply(Action::CancelOperation);
        assert_eq!(state.tool, Tool::Move, "first Esc only cancels the picks");
        let cm = state.creating_move.as_ref().unwrap();
        assert!(cm.targets.is_empty() && cm.start_point_a.is_none(), "picks dropped");

        state.apply(Action::CancelOperation);
        assert_eq!(state.tool, Tool::Select, "second Esc leaves the tool");
        assert!(state.creating_move.is_none(), "the switch cleans the move state up");
    }

    /// #1481: ALL is generated from the enum, so Shape cannot fall out of it again.
    #[test]
    fn tool_all_includes_shape_and_has_no_duplicates() {
        assert!(Tool::ALL.contains(&Tool::Shape));
        let mut seen = std::collections::HashSet::new();
        for tool in Tool::ALL {
            assert!(seen.insert(tool), "{tool:?} listed twice in Tool::ALL");
        }
    }

    /// #1490: switching into any tool carries the subset of the current picks that its
    /// primary picker accepts, and drops the rest. Walking `Tool::ALL` so a later tool
    /// inherits the rule instead of needing another hand-written block.
    #[test]
    fn set_tool_seeds_the_primary_picker_from_the_handoff() {
        use crate::context::PickerTarget as P;
        use crate::tooltable::{row, spaces, ToolSpace};

        for tool in Tool::ALL {
            for &space in spaces(tool) {
                if space == ToolSpace::Drawing {
                    continue;
                }
                let primary = match row(tool, space).primary_picker() {
                    Some(p) => p,
                    None => continue,
                };
                if matches!(
                    primary.target,
                    P::PlaneAnchor | P::SectionPlaneAnchor | P::DrawingAlignBase | P::DrawingSelection
                ) {
                    continue;
                }

                let mut state = handoff_fixture(space);
                if primary.target == P::Selection
                    && crate::context::selection_picker_for(
                        &state.doc,
                        tool,
                        state.sketch_session.map(|s| s.sketch),
                        &state.scene_selection,
                    )
                    .is_none()
                {
                    continue;
                }
                let candidates = handoff_candidates(&state, space);
                let filter = primary_handoff_filter(&state, tool, space, primary.target);
                let accepted: Vec<_> = candidates
                    .iter()
                    .filter(|e| filter.accepts(&state.doc, e))
                    .cloned()
                    .collect();
                let rejected: Vec<_> = candidates
                    .iter()
                    .filter(|e| !filter.accepts(&state.doc, e))
                    .cloned()
                    .collect();
                assert!(
                    !accepted.is_empty(),
                    "{tool:?}/{space:?} fixture must include something the primary picker accepts"
                );

                state.scene_selection.clear();
                for element in &candidates {
                    crate::selection::click_scene_selection(
                        &mut state.scene_selection,
                        element.clone(),
                        true,
                    );
                }

                state.apply(Action::SetTool(tool));

                let picked = primary_picker_contents(&state, primary.target);
                for element in &accepted {
                    let expected = expected_in_picker(&state.doc, primary.target, element);
                    assert!(
                        picked.iter().any(|p| p == &expected),
                        "{tool:?}/{space:?} should keep {element:?} (as {expected:?}); picker has {picked:?}"
                    );
                }
                for element in &rejected {
                    assert!(
                        !picked.contains(element),
                        "{tool:?}/{space:?} should drop {element:?}; picker has {picked:?}"
                    );
                }
            }
        }
    }

    fn handoff_fixture(space: crate::tooltable::ToolSpace) -> AppState {
        use crate::model::Circle;
        let mut state = AppState::default();
        let sketch = begin_default_sketch(&mut state);
        let rect = crate::construction::add_line_rectangle(
            &mut state.doc,
            sketch,
            0.0,
            0.0,
            10.0,
            10.0,
            [false; 4],
        );
        state.doc.circles.insert(Circle::from_local_center_radius(
            sketch, 20.0, 20.0, 3.0, 0.0,
        ));
        state.doc.shape_order.push(crate::model::ShapeKind::Circle);
        state.refresh_document_health();
        state.apply(Action::CreateExtrusion {
            expression: None,
            sketch,
            faces: vec![ExtrudeFace::Polygon(rect.to_vec())],
            distance: 5.0,
            body: crate::actions::ExtrudeBodyChoice::New,
            target: None,
            symmetric: false,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: None,
        });
        if space != crate::tooltable::ToolSpace::Sketch {
            state.apply(Action::ExitSketch);
        }
        state
    }

    fn handoff_candidates(
        state: &AppState,
        space: crate::tooltable::ToolSpace,
    ) -> Vec<SceneElement> {
        use crate::hierarchy::quantize_body_point;
        use crate::model::{ConstraintPoint, FaceId, LineEnd};
        let mut out = Vec::new();
        out.push(SceneElement::ConstructionPlane(pkey(0)));
        if let Some(si) = state.doc.sketches.keys().next() {
            out.push(SceneElement::Sketch(si));
        }
        if let Some(li) = state.doc.lines.keys().next() {
            out.push(SceneElement::Line(li));
            out.push(SceneElement::Point(ConstraintPoint::LineEndpoint {
                line: li,
                end: LineEnd::Start,
            }));
        }
        if let Some(ci) = state.doc.circles.keys().next() {
            // The analytic face, not the circle entity: both map to the same Offset/Slice
            // slot, and a toggle-style pick would add then remove it.
            out.push(SceneElement::SketchFace(FaceId::Circle(ci)));
        }
        if let Some(lines) = closed_rect_lines(state) {
            out.push(SceneElement::SketchFace(FaceId::Polygon(lines)));
        }
        if let Some(bi) = state.doc.bodies.keys().next() {
            out.push(SceneElement::Body(bi));
        }
        if let Some(ei) = state.doc.extrusions.keys().next() {
            out.push(SceneElement::Extrusion(ei));
        }
        if space == crate::tooltable::ToolSpace::Solid {
            if let Some((_, _, a, b)) = crate::extrude::treatable_edges(&state.doc).first() {
                if let Some(bi) = state.doc.bodies.keys().next() {
                    out.push(SceneElement::BodyEdge {
                        body: bi,
                        a: quantize_body_point(*a),
                        b: quantize_body_point(*b),
                    });
                }
            }
        }
        out
    }

    fn closed_rect_lines(state: &AppState) -> Option<Vec<crate::model::LineKey>> {
        let sketch = state.doc.sketches.keys().next()?;
        crate::polygon::closed_line_loops(&state.doc, sketch)
            .into_iter()
            .next()
    }

    fn primary_handoff_filter(
        state: &AppState,
        tool: Tool,
        _space: crate::tooltable::ToolSpace,
        target: crate::context::PickerTarget,
    ) -> crate::element_picker::ElementFilter {
        use crate::context::PickerTarget as P;
        if target == P::Selection {
            return crate::context::selection_picker_for(
                &state.doc,
                tool,
                state.sketch_session.map(|s| s.sketch),
                &state.scene_selection,
            )
            .map(|p| p.filter().clone())
            .unwrap_or_else(crate::element_picker::ElementFilter::everything);
        }
        let mut filter = crate::context::picker_filter(target);
        if let Some(sketch) = state.sketch_session.map(|s| s.sketch) {
            if crate::context::picker_is_sketch_scoped(target) {
                filter = filter.rule(crate::element_picker::PickRule::InSketch(sketch));
            }
        }
        filter
    }

    fn expected_in_picker(
        doc: &crate::model::Document,
        target: crate::context::PickerTarget,
        element: &SceneElement,
    ) -> SceneElement {
        use crate::context::PickerTarget as P;
        match (target, element) {
            (P::TreatmentEdges, SceneElement::BodyEdge { body, a, b }) => {
                match crate::extrude::treatable_edge_for_selection(doc, *body, *a, *b) {
                    Some((crate::model::TreatableSolid::Extrusion(extrusion), edge)) => {
                        SceneElement::ExtrusionEdge { extrusion, edge }
                    }
                    Some((crate::model::TreatableSolid::Primitive(primitive), edge)) => {
                        SceneElement::PrimitiveEdge { primitive, edge }
                    }
                    None => element.clone(),
                }
            }
            (P::MoveTargets, SceneElement::Body(bi)) => {
                match doc.bodies.get(*bi).map(|b| &b.source) {
                    Some(crate::model::BodySource::UnitInstance(ui)) => {
                        SceneElement::UnitInstance(*ui)
                    }
                    _ => element.clone(),
                }
            }
            (P::JointMembers, _) => element
                .as_joint_ref(doc)
                .map(SceneElement::from_joint_ref)
                .unwrap_or_else(|| element.clone()),
            (
                P::SketchSliceTargets,
                SceneElement::SketchFace(crate::model::FaceId::Circle(ci)),
            ) => SceneElement::Circle(*ci),
            _ => element.clone(),
        }
    }

    fn primary_picker_contents(
        state: &AppState,
        target: crate::context::PickerTarget,
    ) -> Vec<SceneElement> {
        use crate::context::PickerTarget as P;
        match target {
            P::Selection => state.scene_selection.ordered(),
            P::CombineA => state
                .creating_boolean
                .as_ref()
                .map(|c| c.a.iter().map(|&bi| SceneElement::Body(bi)).collect())
                .unwrap_or_default(),
            P::MoveTargets => state
                .creating_move
                .as_ref()
                .map(|c| {
                    c.targets
                        .iter()
                        .map(|&bi| SceneElement::Body(bi))
                        .chain(c.instance_targets.iter().map(|&ui| SceneElement::UnitInstance(ui)))
                        .chain(c.plane_targets.iter().map(|&pi| SceneElement::ConstructionPlane(pi)))
                        .chain(c.image_targets.iter().map(|&ii| SceneElement::Image(ii)))
                        .collect()
                })
                .unwrap_or_default(),
            P::JointMembers => state
                .creating_joint
                .as_ref()
                .map(|c| {
                    c.members
                        .iter()
                        .map(|m| SceneElement::from_joint_ref(*m))
                        .collect()
                })
                .unwrap_or_default(),
            P::MirrorTargets => state
                .creating_mirror
                .as_ref()
                .map(|c| c.targets.iter().map(|&bi| SceneElement::Body(bi)).collect())
                .unwrap_or_default(),
            P::MirrorPlane => state
                .creating_mirror
                .as_ref()
                .and_then(|c| c.plane.clone())
                .map(|face| vec![SceneElement::from_face_id(face)])
                .unwrap_or_default(),
            P::RepeatTargets => state
                .creating_repeat
                .as_ref()
                .map(|c| {
                    c.targets
                        .iter()
                        .map(|&bi| SceneElement::Body(bi))
                        .chain(c.plane_targets.iter().map(|&pi| SceneElement::ConstructionPlane(pi)))
                        .chain(c.sketch_targets.iter().map(|&si| SceneElement::Sketch(si)))
                        .chain(c.extrusion_targets.iter().map(|&ei| SceneElement::Extrusion(ei)))
                        .collect()
                })
                .unwrap_or_default(),
            P::SliceTargets => state
                .creating_slice
                .as_ref()
                .map(|c| c.targets.iter().map(|&bi| SceneElement::Body(bi)).collect())
                .unwrap_or_default(),
            P::ShellTargets => state
                .creating_shell
                .as_ref()
                .map(|c| c.targets.iter().map(|&bi| SceneElement::Body(bi)).collect())
                .unwrap_or_default(),
            P::ExtrudeProfile => state
                .creating_extrusion
                .as_ref()
                .map(|c| {
                    c.faces
                        .iter()
                        .map(crate::extrude::extrude_face_scene_element)
                        .collect()
                })
                .unwrap_or_default(),
            P::RevolveProfile => state
                .creating_revolve
                .as_ref()
                .map(|c| {
                    c.faces
                        .iter()
                        .map(crate::extrude::extrude_face_scene_element)
                        .collect()
                })
                .unwrap_or_default(),
            P::SweepProfile => state
                .creating_sweep
                .as_ref()
                .map(|c| {
                    c.faces
                        .iter()
                        .map(crate::extrude::extrude_face_scene_element)
                        .collect()
                })
                .unwrap_or_default(),
            P::LoftSections => state
                .creating_loft
                .as_ref()
                .map(|c| {
                    c.sections
                        .iter()
                        .map(|s| crate::extrude::extrude_face_scene_element(&s.face))
                        .collect()
                })
                .unwrap_or_default(),
            P::TreatmentEdges => state
                .creating_edge_treatment
                .as_ref()
                .map(|c| {
                    c.edges
                        .iter()
                        .map(|&(solid, edge)| match solid {
                            crate::model::TreatableSolid::Extrusion(extrusion) => {
                                SceneElement::ExtrusionEdge { extrusion, edge }
                            }
                            crate::model::TreatableSolid::Primitive(primitive) => {
                                SceneElement::PrimitiveEdge { primitive, edge }
                            }
                        })
                        .collect()
                })
                .unwrap_or_default(),
            P::SketchOffsetEntities => state
                .creating_sketch_offset
                .as_ref()
                .map(|c| {
                    c.line_targets
                        .iter()
                        .map(|&li| SceneElement::Line(li))
                        .chain(c.circle_targets.iter().map(|&ci| SceneElement::Circle(ci)))
                        .collect()
                })
                .unwrap_or_default(),
            P::SketchRepeatEntities => state
                .creating_sketch_repeat
                .as_ref()
                .map(|c| {
                    c.line_targets
                        .iter()
                        .map(|&li| SceneElement::Line(li))
                        .chain(c.circle_targets.iter().map(|&ci| SceneElement::Circle(ci)))
                        .collect()
                })
                .unwrap_or_default(),
            P::SketchMirrorShapes => state
                .creating_sketch_mirror
                .as_ref()
                .map(|c| {
                    c.line_targets
                        .iter()
                        .map(|&li| SceneElement::Line(li))
                        .chain(c.circle_targets.iter().map(|&ci| SceneElement::Circle(ci)))
                        .collect()
                })
                .unwrap_or_default(),
            P::SketchMirrorLine => state
                .creating_sketch_mirror
                .as_ref()
                .and_then(|c| c.line)
                .map(|axis| vec![SceneElement::from_sketch_mirror_axis(axis)])
                .unwrap_or_default(),
            P::SectionPlaneAnchor => state
                .creating_section
                .as_ref()
                .and_then(|c| c.anchor.clone())
                .map(|e| vec![e])
                .unwrap_or_default(),
            P::SketchSliceTargets => state
                .creating_sketch_slice
                .as_ref()
                .map(|c| {
                    c.line_targets
                        .iter()
                        .map(|&li| SceneElement::Line(li))
                        .chain(c.circle_targets.iter().map(|&ci| SceneElement::Circle(ci)))
                        .chain(c.face_targets.iter().map(|lines| {
                            SceneElement::from_face_id(crate::model::FaceId::Polygon(lines.clone()))
                        }))
                        .collect()
                })
                .unwrap_or_default(),
            _ => Vec::new(),
        }
    }

    /// #1482: a placement draft owns the next click and blocks a letter-key switch;
    /// a value-gizmo or picker draft never does. One predicate, every letter.
    #[test]
    fn placement_drafts_block_a_tool_switch_and_value_drafts_do_not() {
        let mut state = AppState::default();
        begin_default_sketch(&mut state);
        state.apply(Action::SetTool(Tool::Circle));
        assert!(!state.draft_blocks_tool_switch(), "empty circle does not block");
        state.creating_circle = Some(CreatingCircle {
            origin: Vec3::ZERO,
            text: String::new(),
            last_mouse: Vec3::new(10.0, 0.0, 0.0),
            user_edited: false,
            pending_focus: false,
            construction: false,
            anchor: CircleAnchor::Center,
        });
        assert!(state.draft_blocks_tool_switch(), "a half-drawn circle owns the next click");

        state.apply(Action::SetTool(Tool::Extrude));
        assert!(
            !state.draft_blocks_tool_switch(),
            "a value-gizmo extrude does not own the next click"
        );
    }

    /// #1498: committing Extrude / Revolve / Sweep / Loft leaves the tool armed with
    /// an empty draft, ready for another.
    #[test]
    fn commit_leaves_feature_tools_armed() {
        for tool in [Tool::Extrude, Tool::Revolve, Tool::Sweep, Tool::Loft] {
            let mut state = AppState::default();
            state.apply(Action::SetTool(tool));
            match tool {
                Tool::Extrude => {
                    let sketch = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
                    let lines = crate::construction::add_line_rectangle(
                        &mut state.doc, sketch, 0.0, 0.0, 10.0, 10.0, [false; 4],
                    );
                    state.creating_extrusion = Some(CreatingExtrusion {
                        sketch: Some(sketch),
                        faces: vec![ExtrudeFace::Polygon(lines.to_vec())],
                        distance: 8.0,
                        text: "8".into(),
                        user_edited: false,
                        pending_focus: false,
                        target: None,
                        edit_index: None,
                        body_mode: ExtrudeBodyMode::NewBody,
                        merge_candidate: None,
                        symmetric: false,
                        taper: 0.0,
                        taper_text: String::new(),
                        taper_user_edited: false,
                        taper_mode: crate::model::ExtrudeTaperMode::Distance,
                    });
                    assert!(matches!(state.apply(Action::CommitExtrusion), ActionResult::Ok), "{}", state.status);
                }
                Tool::Revolve => {
                    let sketch = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
                    let lines = crate::construction::add_line_rectangle(
                        &mut state.doc, sketch, 10.0, 0.0, 10.0, 10.0, [false; 4],
                    );
                    state.creating_revolve = Some(CreatingRevolve {
                        sketch: Some(sketch),
                        faces: vec![ExtrudeFace::Polygon(lines.to_vec())],
                        axis: Some(crate::model::RevolveAxis::Y),
                        ..CreatingRevolve::default()
                    });
                    assert!(matches!(state.apply(Action::CommitRevolve), ActionResult::Ok), "{}", state.status);
                }
                Tool::Sweep => {
                    let sketch = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
                    let lines = crate::construction::add_line_rectangle(
                        &mut state.doc, sketch, 0.0, 0.0, 10.0, 10.0, [false; 4],
                    );
                    state.doc.construction_planes.insert(crate::model::ConstructionPlane {
                        origin: glam::Vec3::ZERO,
                        normal: glam::Vec3::Y,
                        u_axis: glam::Vec3::X,
                        v_axis: glam::Vec3::Z,
                        parent: crate::model::ConstructionPlaneParent::Root,
                        definition: crate::face::default_xy_plane_definition(),
                        repeat_instance: None,
                        name: None,
                        extent: crate::model::PlaneExtent::default(),
                    });
                    let path_sketch = state.doc.add_sketch(FaceId::ConstructionPlane(
                        state.doc.construction_planes.keys().last().unwrap(),
                    ));
                    state.doc.lines.insert(crate::model::Line::from_local_endpoints(
                        path_sketch, 5.0, 0.0, 5.0, 25.0,
                    ));
                    let li = state.doc.lines.keys().last().unwrap();
                    state.creating_sweep = Some(CreatingSweep {
                        sketch: Some(sketch),
                        faces: vec![ExtrudeFace::Polygon(lines.to_vec())],
                        path: vec![li],
                        ..CreatingSweep::default()
                    });
                    assert!(matches!(state.apply(Action::CommitSweep), ActionResult::Ok), "{}", state.status);
                }
                Tool::Loft => {
                    let bottom = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
                    state.doc.circles.insert(crate::model::Circle::from_local_center_radius(
                        bottom, 0.0, 0.0, 5.0, 0.0,
                    ));
                    state.doc.construction_planes.insert(plane_from_definition(
                        &definition_from_reference(
                            &PlaneReference::Face {
                                origin: Vec3::ZERO,
                                normal: Vec3::Z,
                                label: "Ground".to_string(),
                            },
                            10.0,
                            0.0,
                        ),
                        ConstructionPlaneParent::Root,
                    ));
                    let top = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(1)));
                    state.doc.circles.insert(crate::model::Circle::from_local_center_radius(
                        top, 0.0, 0.0, 2.0, 0.0,
                    ));
                    for (sketch, ci) in [(bottom, rkey(0)), (top, rkey(1))] {
                        state.apply(Action::ToggleLoftSection {
                            section: crate::model::LoftSection {
                                sketch,
                                face: ExtrudeFace::Circle(ci),
                            },
                        });
                    }
                    assert!(matches!(state.apply(Action::CommitLoft), ActionResult::Ok), "{}", state.status);
                }
                _ => unreachable!(),
            }
            assert_eq!(state.tool, tool, "{tool:?} must stay armed after commit (#1498)");
            assert!(
                !state.draft_has_picks(state.tool_row().draft),
                "{tool:?} must have an empty draft after commit"
            );
        }
    }

    /// #1499: SetTool each Output-row tool, then cycle — the mode changes immediately,
    /// before any pick.
    #[test]
    fn set_tool_arms_output_row_tools_so_cycle_changes_mode() {
        for tool in [Tool::Extrude, Tool::Revolve, Tool::Sweep, Tool::Loft, Tool::Mirror] {
            let mut state = AppState::default();
            state.apply(Action::SetTool(tool));
            let before = match tool {
                Tool::Extrude => ToolOutputMode::from(
                    state.creating_extrusion.as_ref().expect("Extrude armed on SetTool").body_mode,
                ),
                Tool::Revolve => ToolOutputMode::from(
                    state.creating_revolve.as_ref().expect("Revolve armed on SetTool").body_choice,
                ),
                Tool::Sweep => ToolOutputMode::from(
                    state.creating_sweep.as_ref().expect("Sweep armed on SetTool").body_choice,
                ),
                Tool::Loft => ToolOutputMode::from(
                    state.creating_loft.as_ref().expect("Loft armed on SetTool").body_choice,
                ),
                Tool::Mirror => ToolOutputMode::from(
                    state.creating_mirror.as_ref().expect("Mirror armed on SetTool").mode,
                ),
                _ => unreachable!(),
            };
            state.apply(Action::CycleToolOutputMode);
            let after = match tool {
                Tool::Extrude => ToolOutputMode::from(state.creating_extrusion.as_ref().unwrap().body_mode),
                Tool::Revolve => ToolOutputMode::from(state.creating_revolve.as_ref().unwrap().body_choice),
                Tool::Sweep => ToolOutputMode::from(state.creating_sweep.as_ref().unwrap().body_choice),
                Tool::Loft => ToolOutputMode::from(state.creating_loft.as_ref().unwrap().body_choice),
                Tool::Mirror => ToolOutputMode::from(state.creating_mirror.as_ref().unwrap().mode),
                _ => unreachable!(),
            };
            assert_eq!(after, before.next(), "{tool:?} Y must change the Output mode before a pick (#1499)");
        }
    }

    /// #1534: the same Y action that cycles Extrude Output also walks Combine's Mode
    /// (combine → cut → intersect → difference) as soon as SetTool arms the draft.
    #[test]
    fn set_tool_arms_combine_so_y_cycles_mode() {
        use crate::model::BooleanOpKind;
        let mut state = AppState::default();
        state.apply(Action::SetTool(Tool::Combine));
        assert_eq!(
            state.creating_boolean.as_ref().expect("Combine armed on SetTool").kind,
            BooleanOpKind::Combine
        );
        for expected in [
            BooleanOpKind::Cut,
            BooleanOpKind::Intersect,
            BooleanOpKind::Difference,
            BooleanOpKind::Combine,
        ] {
            state.apply(Action::CycleToolOutputMode);
            assert_eq!(
                state.creating_boolean.as_ref().unwrap().kind,
                expected,
                "Y must cycle Combine mode before a pick (#1534)"
            );
            assert_eq!(
                current_tool_mode(&state).as_deref(),
                Some(expected.script_name())
            );
        }
        // `tool_mode("next")` is the scripted Y.
        set_tool_mode(&mut state, "next").unwrap();
        assert_eq!(
            state.creating_boolean.as_ref().unwrap().kind,
            BooleanOpKind::Cut
        );
        set_tool_mode(&mut state, "cycle").unwrap();
        assert_eq!(
            state.creating_boolean.as_ref().unwrap().kind,
            BooleanOpKind::Intersect
        );
    }

    /// #1500: last-used output mode, combine kind, joint kind, and revolve symmetric
    /// survive leaving the tool.
    #[test]
    fn last_used_options_survive_leaving_the_tool() {
        let mut state = AppState::default();
        state.apply(Action::SetTool(Tool::Extrude));
        state.apply(Action::CycleToolOutputMode);
        let saved = ToolOutputMode::from(state.creating_extrusion.as_ref().unwrap().body_mode);
        state.apply(Action::SetTool(Tool::Select));
        state.apply(Action::SetTool(Tool::Extrude));
        assert_eq!(
            ToolOutputMode::from(state.creating_extrusion.as_ref().unwrap().body_mode),
            saved,
            "Extrude output mode is last-used (#1500)"
        );

        state.apply(Action::SetTool(Tool::Combine));
        set_tool_mode(&mut state, "cut").unwrap();
        assert_eq!(state.creating_boolean.as_ref().unwrap().kind, crate::model::BooleanOpKind::Cut);
        state.apply(Action::SetTool(Tool::Select));
        state.apply(Action::SetTool(Tool::Combine));
        assert_eq!(
            state.creating_boolean.as_ref().unwrap().kind,
            crate::model::BooleanOpKind::Cut,
            "Combine kind is last-used (#1500)"
        );

        state.apply(Action::SetTool(Tool::Revolve));
        state.creating_revolve.as_mut().unwrap().symmetric = true;
        state.tool_prefs.entry(Tool::Revolve).symmetric = Some(true);
        state.apply(Action::SetTool(Tool::Select));
        state.apply(Action::SetTool(Tool::Revolve));
        assert!(
            state.creating_revolve.as_ref().unwrap().symmetric,
            "Revolve symmetric is last-used (#1500)"
        );
    }

