    #[test]
    fn undo_last_refreshes_document_health() {
        let mut state = AppState::default();
        // Checkpoint the empty document, then force an invalid-parameter state in place.
        state.undo_stack.push(state.doc.clone());
        state.doc.parameters.insert(crate::model::Parameter {
            name: "bad".to_string(),
            expression: "1mm / 0".to_string(),
            primary: false,
            minimum: None,
            maximum: None,
            step: None,
            source: None,
        });
        state.doc.shape_order.push(ShapeKind::Parameter);
        state.refresh_document_health();
        let param = state.doc.parameters.keys().next().expect("the parameter");
        assert_eq!(
            state.document_health.parameter_status(param),
            crate::document_health::HealthStatus::Invalid
        );

        // Undo restores the checkpoint and recomputes health from the restored document.
        state.apply(Action::UndoLast);
        assert!(state.doc.parameters.is_empty());
        assert!(state.document_health.parameters.is_empty());
    }

    #[test]
    fn open_document_with_deletions_recomputes_health() {
        use crate::document_lifecycle::delete_element;
        use crate::model::{Constraint, ConstraintKind, ConstraintLine};

        let dir = std::env::temp_dir();
        let path = dir.join("bearcad_open_health.bearcad");
        let path = path.to_string_lossy().to_string();
        let _ = std::fs::remove_file(&path);

        let mut doc = Document::default();
        let sketch = doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
        doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0));
        doc.shape_order.push(ShapeKind::Line);
        doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, 5.0, 10.0, 5.0));
        doc.shape_order.push(ShapeKind::Line);
        doc.constraints.insert(Constraint {
            sketch,
            kind: ConstraintKind::Parallel {
                line_a: ConstraintLine::Line(lkey(0)),
                line_b: ConstraintLine::Line(lkey(1)),
            },
            expression: String::new(),
            dim_offset: None,
            name: None,
        });
        doc.shape_order.push(ShapeKind::Constraint);
        delete_element(&mut doc, SceneElement::Line(lkey(0)));
        crate::storage::save(&path, &doc).unwrap();

        let loaded = crate::storage::open(&path).unwrap();
        assert!(!loaded.lines.contains(lkey(0)));
        assert!(loaded.lines.contains(lkey(1)));
        let health_after_load = crate::document_health::recompute_document_health(&loaded);
        assert_eq!(
            health_after_load.element_status(SceneElement::Constraint(nkey(0))),
            crate::document_health::HealthStatus::Invalid
        );
        assert_eq!(
            health_after_load.element_status(SceneElement::Line(lkey(1))),
            crate::document_health::HealthStatus::Unstable
        );

        let mut state = AppState::default();
        state.apply(Action::Open { path: path.clone() });
        assert_eq!(
            state.document_health.element_status(SceneElement::Constraint(nkey(0))),
            crate::document_health::HealthStatus::Invalid
        );
        assert_eq!(
            state.document_health.element_status(SceneElement::Line(lkey(1))),
            crate::document_health::HealthStatus::Unstable
        );

        drop(state);
        std::fs::remove_file(&path).unwrap();
    }

