    /// #1158: create a drawing of a body in one step (Elements-pane body context menu): a new
    /// drawing opens with a default-orientation view of that body. Named bodies seed the
    /// drawing's name; missing bodies are rejected.
    /// #1689: a technical drawing can import a whole cross-section view — its bodies, cut the
    /// way the View workbench shows them, with the opened faces hatched on the page.
    #[test]
    fn a_drawing_can_import_a_cross_section_view() {
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        let body = state.doc.bodies.keys().next().expect("a body");
        let whole = crate::extrude::body_solid_mesh(&state.doc, body).expect("mesh");
        let (min, max) = whole.bounds().expect("bounds");
        let mid_z = (min.z + max.z) * 0.5;

        state.apply(Action::CreateCrossSection { name: Some("Half".into()) });
        let view = state.doc.cross_sections.keys().next().expect("the view");
        state.apply(Action::AddCrossSectionCut {
            view: Some(view),
            cut: crate::model::CrossSectionCut {
                origin: glam::Vec3::new(0.0, 0.0, mid_z),
                normal: glam::Vec3::Z,
                ..Default::default()
            },
        });

        state.apply(Action::CreateDrawing { name: None });
        let drawing = state.doc.drawings.keys().next().expect("the drawing");
        assert_eq!(
            state.apply(Action::AddDrawingCrossSectionView {
                drawing,
                view,
                orientation: crate::model::DrawingOrientation::default(),
            }),
            ActionResult::Ok
        );
        let placed = &state.doc.drawings[drawing].views[0];
        assert_eq!(placed.cross_section, Some(view), "the page view is sectioned");
        assert!(!placed.bodies.is_empty(), "and it took the model's bodies");

        // What it projects is the cut geometry, not the whole body.
        let mesh = crate::drawing::drawing_view_solid_mesh(&state.doc, placed).expect("mesh");
        let (lo, _) = mesh.bounds().expect("bounds");
        assert!(lo.z > mid_z - 1e-2, "nothing below the cutting plane is projected");
        assert!(
            !crate::drawing::section_hatch_world_segments(&state.doc, placed).is_empty(),
            "the opened face is hatched on the page"
        );

        // An ordinary projection is untouched by any of this.
        state.apply(Action::AddDrawingView {
            drawing,
            bodies: vec![body],
            orientation: crate::model::DrawingOrientation::default(),
        });
        let plain = &state.doc.drawings[drawing].views[1];
        assert_eq!(plain.cross_section, None);
        assert!(crate::drawing::section_hatch_world_segments(&state.doc, plain).is_empty());
    }

    /// #1688: a view's planes chop the bodies — half the box is gone, and the opening comes
    /// back as a real cut face for the hatch to sit on.
    #[test]
    fn cross_section_planes_chop_the_body() {
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        let body = state.doc.bodies.keys().next().expect("a body");
        let whole = crate::extrude::body_solid_mesh(&state.doc, body).expect("the body's mesh");
        let (min, max) = whole.bounds().expect("bounds");
        let full = crate::extrude::mesh_signed_volume(&whole).abs();
        let mid_z = (min.z + max.z) * 0.5;

        // Cut across the middle: the kept side is the one the normal points toward.
        let cut = crate::model::CrossSectionCut {
            origin: glam::Vec3::new(0.0, 0.0, mid_z),
            normal: glam::Vec3::Z,
            ..Default::default()
        };
        let top = crate::extrude::cross_section_body_mesh(&state.doc, body, &[cut.clone()])
            .expect("the cut mesh");
        let top_volume = crate::extrude::mesh_signed_volume(&top).abs();
        assert!(
            (top_volume - full / 2.0).abs() < full * 0.05,
            "half the box survives: {top_volume} of {full}"
        );
        let (top_min, top_max) = top.bounds().expect("bounds");
        assert!(top_min.z > mid_z - 1e-2, "nothing below the plane is left");
        assert!(top_max.z > mid_z, "and the upper half is");

        // Flipping keeps the other half instead.
        let flipped = crate::model::CrossSectionCut { flip: true, ..cut.clone() };
        let bottom = crate::extrude::cross_section_body_mesh(&state.doc, body, &[flipped])
            .expect("the flipped mesh");
        let (_, bottom_max) = bottom.bounds().expect("bounds");
        assert!(bottom_max.z < mid_z + 1e-2, "the flip keeps what the first cut removed");

        // The opening is closed: the cut mesh has triangles lying in the cutting plane.
        let on_plane = top
            .triangles
            .iter()
            .filter(|t| t.iter().all(|p| (p.z - mid_z).abs() < 1e-3))
            .count();
        assert!(on_plane > 0, "the cut face is real geometry, not an open shell");

        // Two planes cut in two directions at once.
        let side = crate::model::CrossSectionCut {
            origin: glam::Vec3::new((min.x + max.x) * 0.5, 0.0, 0.0),
            normal: glam::Vec3::X,
            ..Default::default()
        };
        let quarter = crate::extrude::cross_section_body_mesh(&state.doc, body, &[cut, side])
            .expect("the twice-cut mesh");
        let quarter_volume = crate::extrude::mesh_signed_volume(&quarter).abs();
        assert!(
            (quarter_volume - full / 4.0).abs() < full * 0.05,
            "two planes leave a quarter: {quarter_volume} of {full}"
        );
    }

    /// #1756: a cutting plane coplanar with a face of the body, with nothing on the keep
    /// side, must not leave that face behind.
    #[test]
    fn coplanar_cut_with_no_keep_side_hides_the_face() {
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        let body = state.doc.bodies.keys().next().expect("a body");
        let whole = crate::extrude::body_solid_mesh(&state.doc, body).expect("the body's mesh");
        let (min, max) = whole.bounds().expect("bounds");
        // Keep pointing away from the body: origin on the bottom face, normal down.
        let cut = crate::model::CrossSectionCut {
            origin: glam::Vec3::new(0.0, 0.0, min.z),
            normal: -glam::Vec3::Z,
            ..Default::default()
        };
        let mesh = crate::extrude::cross_section_body_mesh(&state.doc, body, &[cut]);
        assert!(
            mesh.is_none() || mesh.as_ref().is_some_and(|m| m.triangles.is_empty()),
            "no keep-side volume means the coplanar face is gone, got {mesh:?}"
        );
        let _ = max;
    }

    /// #1769: a plane only cuts the bodies it lists, and never the excluded ones — an
    /// exclusion wins even over an explicit list.
    #[test]
    fn cutting_planes_cut_only_listed_bodies_and_skip_excluded_ones() {
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        let keys: Vec<_> = state.doc.bodies.keys().collect();
        assert!(keys.len() >= 2, "two bodies to scope between");
        let (a, b) = (keys[0], keys[1]);
        let whole_a = crate::extrude::body_solid_mesh(&state.doc, a).expect("mesh a");
        let whole_b = crate::extrude::body_solid_mesh(&state.doc, b).expect("mesh b");
        let volume = |m: &crate::extrude::SolidMesh| {
            crate::extrude::mesh_signed_volume(m).abs()
        };
        let (_, max) = whole_a.bounds().expect("bounds");
        let mid_z = max.z * 0.5;
        let cut = crate::model::CrossSectionCut {
            origin: glam::Vec3::new(0.0, 0.0, mid_z),
            normal: glam::Vec3::Z,
            cut_bodies: Some(vec![a]),
            exclude_bodies: Vec::new(),
            ..Default::default()
        };
        // The listed body is halved; the unlisted one draws whole.
        let sectioned_a = crate::extrude::sectioned_body_mesh(&state.doc, a, &[cut.clone()])
            .expect("the scoped mesh");
        let sectioned_b =
            crate::extrude::sectioned_body_mesh(&state.doc, b, &[cut.clone()])
                .expect("the unscoped mesh stays whole");
        assert!(
            (volume(&sectioned_a) - volume(&whole_a) / 2.0).abs() < volume(&whole_a) * 0.05,
            "a listed body is half: {} of {}",
            volume(&sectioned_a),
            volume(&whole_a)
        );
        assert!(
            (volume(&sectioned_b) - volume(&whole_b)).abs() < volume(&whole_b) * 1e-4,
            "an unlisted body is untouched"
        );
        // An exclusion wins over All.
        let excluding = crate::model::CrossSectionCut {
            origin: glam::Vec3::new(0.0, 0.0, mid_z),
            normal: glam::Vec3::Z,
            exclude_bodies: vec![b],
            ..Default::default()
        };
        let spared =
            crate::extrude::sectioned_body_mesh(&state.doc, b, &[excluding.clone()])
                .expect("the spared mesh");
        assert!(
            (volume(&spared) - volume(&whole_b)).abs() < volume(&whole_b) * 1e-4,
            "an excluded body is spared even under All"
        );
        let still_cut =
            crate::extrude::sectioned_body_mesh(&state.doc, a, &[excluding.clone()])
                .expect("mesh");
        assert!(
            (volume(&still_cut) - volume(&whole_a) / 2.0).abs() < volume(&whole_a) * 0.05,
            "and everybody else still feels it"
        );
        // Directly on the model: exclusions win over an explicit list too.
        let mut both_ways = excluding.clone();
        both_ways.cut_bodies = Some(vec![a, b]);
        assert!(
            !both_ways.cut_applies_to(b),
            "exclusion beats an explicit listing"
        );
        assert!(both_ways.cut_applies_to(a));
    }

    /// #1769: the tool's draft carries the scopes — BeginEdit restores them from the
    /// hanging plane, commit writes them back, and pane picks fill them.
    #[test]
    fn cutting_plane_scope_round_trips_through_edit_and_pick() {
        use crate::hierarchy::SceneElement;
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        let keys: Vec<_> = state.doc.bodies.keys().collect();
        assert!(keys.len() >= 2, "two bodies to scope between");
        let (a, b) = (keys[0], keys[1]);

        state.apply(Action::CreateCrossSection { name: None });
        let view = state.doc.cross_sections.keys().next().expect("the view");
        state.apply(Action::AddCrossSectionCut {
            view: None,
            cut: crate::model::CrossSectionCut {
                origin: glam::Vec3::ZERO,
                normal: glam::Vec3::Z,
                cut_bodies: Some(vec![b]),
                exclude_bodies: vec![a],
                ..Default::default()
            },
        });

        // Reopening the plane (#1755) brings its scopes back with everything else.
        assert_eq!(
            state.apply(Action::BeginEditSectionPlane { view, cut: 0 }),
            ActionResult::Ok
        );
        let cs = state.creating_section.as_ref().expect("the draft");
        assert_eq!(cs.cut_bodies, Some(vec![b]));
        assert_eq!(cs.exclude_bodies, vec![a]);

        // Pane picks extend them while editing: a cut-list pick lands in the explicit list,
        // an exclude pick in the exclusions.
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SectionPlaneCutBodies,
            &SceneElement::Body(a)
        ));
        let cs = state.creating_section.as_ref().expect("the draft");
        assert_eq!(
            cs.cut_bodies.as_deref(),
            Some([b, a].as_slice()),
            "the pick joined the explicit list"
        );
        // A partial edit rescopes without touching anything else (#1769).
        state.apply(Action::SetCrossSectionCut {
            view: Some(view),
            cut: 0,
            offset_mm: None,
            roll_deg: None,
            depth_mm: None,
            flip: None,
            cut_bodies: Some(Some(vec![b])),
            exclude_bodies: None,
        });
        let stored = &state.doc.cross_sections[view].cuts[0];
        assert_eq!(stored.cut_bodies.as_deref(), Some([b].as_slice()));
        assert_eq!(stored.exclude_bodies, &[a]);

        // Commit replaces the hanging plane with the draft's scopes intact.
        let cs = state.creating_section.take().expect("still editing");
        state.creating_section = Some(cs);
        assert_eq!(state.apply(Action::CommitSectionPlane), ActionResult::Ok);
        let stored = &state.doc.cross_sections[view].cuts[0];
        assert_eq!(
            stored.cut_bodies.as_deref(),
            Some([b, a].as_slice()),
            "commit keeps the edited scope"
        );
        assert_eq!(stored.exclude_bodies, &[a]);
    }

    /// #1687: the cutting-plane tool hangs planes off faces, and each one slides, turns, and
    /// flips independently. Several combine to cut in several directions at once.
    #[test]
    fn cross_section_cuts_are_placed_and_adjusted() {
        let mut state = AppState::default();
        state.apply(Action::CreateCrossSection { name: None });
        let view = state.doc.cross_sections.keys().next().expect("the view");

        // Placed on the open view, no key needed.
        assert_eq!(
            state.apply(Action::AddCrossSectionCut {
                view: None,
                cut: crate::model::CrossSectionCut {
                    origin: glam::Vec3::new(0.0, 0.0, 5.0),
                    normal: glam::Vec3::Z,
                    ..Default::default()
                },
            }),
            ActionResult::Ok
        );
        state.apply(Action::AddCrossSectionCut {
            view: None,
            cut: crate::model::CrossSectionCut {
                origin: glam::Vec3::ZERO,
                normal: glam::Vec3::X,
                ..Default::default()
            },
        });
        assert_eq!(state.doc.cross_sections[view].cuts.len(), 2, "several planes at once");

        // Slide, turn, flip — each field on its own, the others left alone.
        state.apply(Action::SetCrossSectionCut {
            view: None,
            cut: 0,
            offset_mm: Some(-3.5),
            roll_deg: None,
            depth_mm: None,
            flip: None,
            cut_bodies: None,
            exclude_bodies: None,
        });
        state.apply(Action::SetCrossSectionCut {
            view: None,
            cut: 0,
            offset_mm: None,
            roll_deg: Some(90.0),
            depth_mm: None,
            flip: Some(true),
            cut_bodies: None,
            exclude_bodies: None,
        });
        let cut = state.doc.cross_sections[view].cuts[0].clone();
        assert_eq!(cut.offset_mm, -3.5);
        assert!((cut.roll - std::f32::consts::FRAC_PI_2).abs() < 1e-5, "roll stored in radians");
        assert!(cut.flip, "and the kept side flipped");
        assert_eq!(cut.normal, glam::Vec3::Z, "the plane itself is untouched");

        // Removing one leaves the other.
        assert_eq!(
            state.apply(Action::RemoveCrossSectionCut { view: None, cut: 0 }),
            ActionResult::Ok
        );
        assert_eq!(state.doc.cross_sections[view].cuts.len(), 1);
        assert_eq!(state.doc.cross_sections[view].cuts[0].normal, glam::Vec3::X);

        // Out-of-range and viewless cases refuse rather than panic.
        assert!(matches!(
            state.apply(Action::RemoveCrossSectionCut { view: None, cut: 7 }),
            ActionResult::Err(_)
        ));
        state.apply(Action::EditCrossSection { view: None });
        assert!(matches!(
            state.apply(Action::AddCrossSectionCut {
                view: None,
                cut: Default::default(),
            }),
            ActionResult::Err(_)
        ));
    }

    /// #1745: picking an anchor fills the draft; Enter / CommitSectionPlane hangs the plane.
    #[test]
    fn cutting_plane_pick_fills_the_draft_and_accept_commits() {
        use crate::hierarchy::SceneElement;
        let mut state = AppState::default();
        state.apply(Action::CreateCrossSection { name: None });
        let view = state.doc.cross_sections.keys().next().expect("the view");
        let plane = SceneElement::ConstructionPlane(pkey(0));
        state.tool = Tool::SectionPlane;
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SectionPlaneAnchor,
            &plane
        ));
        assert!(state.creating_section.is_some(), "the pick starts a draft");
        assert_eq!(state.doc.cross_sections[view].cuts.len(), 0, "click does not hang the plane");
        assert_eq!(
            state.creating_section.as_ref().unwrap().anchor.as_ref(),
            Some(&plane)
        );
        assert_eq!(state.apply(Action::CommitSectionPlane), ActionResult::Ok);
        assert_eq!(state.doc.cross_sections[view].cuts.len(), 1);
        assert!(state.creating_section.is_none(), "accept empties the draft");
        assert_eq!(state.tool, Tool::SectionPlane, "and stays armed");
    }

    /// #1757: a body's edge (or a world axis) is an axis anchor, the way the construction
    /// plane tool treats it — the line lies *in* the cutting plane, it is not the plane's
    /// normal.
    #[test]
    fn cutting_plane_edge_pick_is_an_axis_anchor() {
        use crate::construction::{GlobalAxis, PlaneReference};
        use crate::hierarchy::SceneElement;
        let mut state = AppState::default();
        state.apply(Action::CreateCrossSection { name: None });
        state.tool = Tool::SectionPlane;
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SectionPlaneAnchor,
            &SceneElement::GlobalAxis(GlobalAxis::X),
        ));
        let cs = state.creating_section.as_ref().expect("the pick starts a draft");
        assert!(
            matches!(cs.reference, PlaneReference::Axis { direction, .. } if direction.dot(glam::Vec3::X).abs() > 0.99),
            "an axis/edge pick must be an axis reference, got {:?}",
            cs.reference
        );
        let gizmos = available_gizmos(&state);
        assert!(
            gizmos.iter().any(|g| g.name == "offset"),
            "axis anchors get the offset gizmo, got {gizmos:?}"
        );
        assert!(
            gizmos.iter().any(|g| g.kind == "rotate" && g.name != "tilt_v"),
            "axis anchors rotate around the edge, got {gizmos:?}"
        );
        assert!(
            !gizmos.iter().any(|g| g.name == "tilt_v"),
            "an axis is one rotation, not two face tilts"
        );
    }

    /// #1750/#1752/#1753: after a face pick the offset field takes focus, the picker lets
    /// go, one offset gizmo and two tilt gizmos show — not a spin around the face normal.
    #[test]
    fn cutting_plane_face_pick_focuses_offset_and_exposes_two_tilts() {
        use crate::construction::PlaneReference;
        use crate::hierarchy::SceneElement;
        let mut state = AppState::default();
        state.apply(Action::CreateCrossSection { name: None });
        state.tool = Tool::SectionPlane;
        let plane = SceneElement::ConstructionPlane(pkey(0));
        assert!(apply_pick(
            &mut state,
            crate::context::PickerTarget::SectionPlaneAnchor,
            &plane
        ));
        let cs = state.creating_section.as_ref().expect("the pick starts a draft");
        assert!(matches!(cs.reference, PlaneReference::Face { .. }));
        assert!(cs.pending_focus, "the offset field takes the keyboard");
        assert!(
            state.picker_focus != Some(crate::context::PickerTarget::SectionPlaneAnchor),
            "the Anchor picker must lose focus so a gizmo grab is not another pick"
        );
        let gizmos = available_gizmos(&state);
        let names: Vec<_> = gizmos.iter().map(|g| g.name).collect();
        assert_eq!(
            gizmos.iter().filter(|g| g.name == "offset").count(),
            1,
            "one offset gizmo, got {names:?}"
        );
        assert!(
            gizmos.iter().any(|g| g.name == "tilt_u") && gizmos.iter().any(|g| g.name == "tilt_v"),
            "two tilts around the in-plane axes, got {names:?}"
        );
        assert!(
            !gizmos.iter().any(|g| g.name == "roll"),
            "rotation is not around the face normal, got {names:?}"
        );
    }

    /// #1755: double-clicking a hanging cutting plane reopens the same draft.
    #[test]
    fn begin_edit_section_plane_reopens_the_draft() {
        let mut state = AppState::default();
        state.apply(Action::CreateCrossSection { name: None });
        let view = state.doc.cross_sections.keys().next().expect("the view");
        state.apply(Action::AddCrossSectionCut {
            view: None,
            cut: crate::model::CrossSectionCut {
                origin: glam::Vec3::ZERO,
                normal: glam::Vec3::Z,
                offset_mm: 4.0,
                flip: true,
                ..Default::default()
            },
        });
        assert_eq!(
            state.apply(Action::BeginEditSectionPlane { view, cut: 0 }),
            ActionResult::Ok
        );
        assert_eq!(state.tool, Tool::SectionPlane);
        let cs = state.creating_section.as_ref().expect("the plane reopens");
        assert!((cs.offset_live - 4.0).abs() < 1e-4);
        assert!(cs.flip);
        assert_eq!(cs.edit_cut, Some((view, 0)));
        assert_eq!(state.apply(Action::CommitSectionPlane), ActionResult::Ok);
        assert_eq!(state.doc.cross_sections[view].cuts.len(), 1, "edit replaces, it does not stack");
        assert!((state.doc.cross_sections[view].cuts[0].offset_mm - 4.0).abs() < 1e-4);
    }

    /// #1671/#1686: creating a cross-section view opens the View workbench; leaving it puts
    /// the app back on the modeling bar.
    #[test]
    fn create_cross_section_opens_the_view_workbench() {
        let mut state = AppState::default();
        assert_eq!(state.workbench(), Workbench::Model);

        assert_eq!(
            state.apply(Action::CreateCrossSection { name: Some("Front".into()) }),
            ActionResult::Ok
        );
        let key = state.doc.cross_sections.keys().next().expect("the view");
        assert_eq!(state.editing_cross_section, Some(key), "opens the new view");
        assert_eq!(state.workbench(), Workbench::View);

        // The View bar's tools are its own; a modeling tool doesn't survive the switch.
        assert!(
            crate::tooltable::workbench_tools(Workbench::View).contains(&state.tool),
            "the active tool belongs to the View bar, got {:?}",
            state.tool
        );

        state.apply(Action::EditCrossSection { view: None });
        assert_eq!(state.editing_cross_section, None, "Back leaves the workbench");
        assert_eq!(state.workbench(), Workbench::Model);
        assert!(crate::tooltable::workbench_tools(Workbench::Model).contains(&state.tool));

        // Re-opening an existing view returns to it.
        state.apply(Action::EditCrossSection { view: Some(key) });
        assert_eq!(state.workbench(), Workbench::View);
    }

    #[test]
    fn create_drawing_of_body_opens_with_a_view() {
        use crate::model::DrawingOrientation;
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        state.doc.bodies[bkey(0)].name = Some("Plate".to_string());

        assert_eq!(
            state.apply(Action::CreateDrawingOfBody { body: bkey(0) }),
            ActionResult::Ok
        );
        assert_eq!(state.doc.drawings.len(), 1);
        assert_eq!(state.editing_drawing, Some(dkey(0)), "opens the new drawing");
        let drawing = &state.doc.drawings[dkey(0)];
        assert_eq!(drawing.name.as_deref(), Some("Plate"));
        assert_eq!(drawing.views.len(), 1, "one view of the body");
        assert_eq!(drawing.views[0].bodies[0], bkey(0));
        assert_eq!(drawing.views[0].orientation, DrawingOrientation::default());

        // Unnamed body → default "Drawing N" title, still with a view.
        assert_eq!(
            state.apply(Action::CreateDrawingOfBody { body: bkey(1) }),
            ActionResult::Ok
        );
        assert_eq!(state.doc.drawings[dkey(1)].name, None);
        assert_eq!(state.doc.drawings[dkey(1)].views[0].bodies[0], bkey(1));

        assert!(matches!(
            state.apply(Action::CreateDrawingOfBody { body: bkey(99) }),
            ActionResult::Err(_)
        ));
    }

    /// #1191: shift-click path — append bodies to the selected projection rather than opening
    /// a second card. Plain click still creates a new view.
    #[test]
    fn drawing_add_shift_click_appends_bodies_to_the_selected_view() {
        use crate::hierarchy::SceneElement;
        use crate::model::DrawingOrientation;
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        state.apply(Action::CreateDrawing { name: None });
        let drawing = state.editing_drawing.expect("drawing open");
        state.tool = Tool::DrawingAdd;

        // Plain click → new view of body 0.
        assert_eq!(
            state.apply(Action::ClickSceneElement {
                element: SceneElement::Body(bkey(0)),
                additive: false,
            }),
            ActionResult::Ok
        );
        assert_eq!(state.doc.drawings[drawing].views.len(), 1);
        assert_eq!(state.doc.drawings[drawing].views[0].bodies, vec![bkey(0)]);

        // Shift+click body 1 → same view now holds both.
        assert_eq!(
            state.apply(Action::ClickSceneElement {
                element: SceneElement::Body(bkey(1)),
                additive: true,
            }),
            ActionResult::Ok
        );
        assert_eq!(
            state.doc.drawings[drawing].views.len(),
            1,
            "shift-click must not open a second card"
        );
        assert_eq!(
            state.doc.drawings[drawing].views[0].bodies,
            vec![bkey(0), bkey(1)]
        );

        // Plain click again → a fresh view.
        assert_eq!(
            state.apply(Action::ClickSceneElement {
                element: SceneElement::Body(bkey(0)),
                additive: false,
            }),
            ActionResult::Ok
        );
        assert_eq!(state.doc.drawings[drawing].views.len(), 2);
        assert_eq!(state.doc.drawings[drawing].views[1].bodies, vec![bkey(0)]);
        assert_eq!(
            state.doc.drawings[drawing].views[1].orientation,
            DrawingOrientation::default()
        );
    }

    /// #1190: with the Projection tool active, clicking a component projects every body in it
    /// as one multi-body view.
    #[test]
    fn drawing_add_component_projects_every_body() {
        use crate::hierarchy::SceneElement;
        use crate::model::ComponentMember as CM;
        let mut state = two_box_state(false);
        state.apply(Action::ExitSketch);
        state.apply(Action::CreateComponent {
            name: Some("Frame".to_string()),
            parent: None,
        });
        state
            .doc
            .set_component_member(CM::Body(bkey(0)), Some(ckey(0)));
        state
            .doc
            .set_component_member(CM::Body(bkey(1)), Some(ckey(0)));
        state.apply(Action::CreateDrawing { name: None });
        let drawing = state.editing_drawing.expect("drawing open");
        state.tool = Tool::DrawingAdd;

        assert_eq!(
            state.apply(Action::ClickSceneElement {
                element: SceneElement::Component(ckey(0)),
                additive: false,
            }),
            ActionResult::Ok
        );
        assert_eq!(state.doc.drawings[drawing].views.len(), 1);
        let mut bodies = state.doc.drawings[drawing].views[0].bodies.clone();
        bodies.sort_unstable();
        assert_eq!(bodies, vec![bkey(0), bkey(1)]);
        let label = crate::drawing::drawing_view_source_label(
            &state.doc,
            &state.doc.drawings[drawing].views[0],
        );
        assert!(
            label.contains("Frame"),
            "caption should name the component, got {label:?}"
        );
    }

